INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C1','math',5,2,'u4',2,'소수의 10배·⟨1/10⟩ — 10배 하면 소수점이 오른쪽으로, ⟨1/10⟩ 하면 왼쪽으로 한 자리 옮겨짐을 되짚고, 길이의 차이는 뺄셈·같은 양이 여러 개면 곱셈식으로 적어야 함을 가리기',ARRAY['6수01-09']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C2','math',5,2,'u4',2,'(소수 한 자리)×(자연수) — 수직선에서 같은 소수씩 뛰어 세기·0.1의 개수·분수의 곱셈(⟨12/10⟩ × 4)·자연수의 곱셈(12 × 4의 ⟨1/10⟩배)으로 계산하고, 곱이 어느 두 자연수 사이에 있어야 하는지 어림하기',ARRAY['6수01-09']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C3','math',5,2,'u4',3,'(소수 두 자리)×(자연수) — 분수(⟨24/100⟩ × 3)나 자연수의 곱셈(24 × 3의 ⟨1/100⟩배)으로 계산하고, 계산 전에 어림한 값과 견주어 소수점을 너무 왼쪽·오른쪽에 찍은 오류를 찾기',ARRAY['6수01-09']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C4','math',5,2,'u4',4,'(자연수)×(소수 한 자리) — 「2의 0.8배」는 2를 똑같이 10으로 나눈 것 중의 8임을 알고 분수·자연수의 곱셈으로 계산하며, 곱하는 수가 1보다 작으면 곱이 처음 수보다 작고 1보다 크면 커짐을 계산 전에 가리기',ARRAY['6수01-09']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C5','math',5,2,'u4',5,'(자연수)×(소수 두 자리) — 6 × 0.38을 6 × 38의 ⟨1/100⟩배로 계산하고, 곱하는 수가 1보다 작으면 곱이 처음 수보다 작아야 함을 어림으로 확인하며 자리를 바꾸어 계산해도 곱이 같음을 알기',ARRAY['6수01-09']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C6','math',5,2,'u4',6,'(소수 한 자리)×(소수 한 자리) — 1을 100칸으로 나눈 넓이 모델에서 한 칸이 0.01임을 알고 칠한 칸 수로 곱을 구하며, 두 수가 모두 ⟨1/10⟩배이면 곱은 자연수의 곱의 ⟨1/100⟩배임을 알기',ARRAY['6수01-09']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C7','math',5,2,'u4',7,'자릿수가 다른 소수끼리의 곱셈 — 0.47 × 0.3처럼 ⟨1/100⟩배와 ⟨1/10⟩배이면 곱은 ⟨1/1000⟩배임을 알고, 끝자리 0을 생략하며, 계산하기 전에 어림하여 곱이 기준보다 큰지 작은지 가리기',ARRAY['6수01-09']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C8','math',5,2,'u4',8,'곱의 소수점 위치 — 10·100·1000을 곱하면 소수점이 오른쪽으로, 0.1·0.01·0.001을 곱하면 왼쪽으로 그 0의 개수만큼 옮겨지고, 소수끼리의 곱은 자연수의 곱에서 두 수의 소수점 아래 자릿수의 합만큼 왼쪽으로 옮긴 자리임을 알기',ARRAY['6수01-09']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u4-C9','math',5,2,'u4',9,'문제 해결 — 표에서 한 사람의 효과와 실천한 사람 수를 읽고, 반 전체의 효과(한 사람 효과 × 사람 수)를 어림셈으로 먼저 견준 뒤 계산으로 확인하며, 한 사람 효과나 사람 수 하나만 보고 판단하면 안 됨을 알기',ARRAY['6수01-09']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X01','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'곱의 소수점을 찍지 않고 자연수의 곱을 그대로 쓴다(1.2 × 4를 48로)','소수점을 꼭 찍어요 — 어림하면 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X02','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C7']::text[],'곱의 소수점을 한 자리 이상 잘못 찍어 곱을 10배 크게 또는 ⟨1/10⟩배 작게 쓴다(1.35 × 4를 0.540으로)','어림한 값과 견주어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X03','math',5,'u4',ARRAY['M5-2-u4-C6','M5-2-u4-C7','M5-2-u4-C8']::text[],'소수끼리 곱할 때 한 수의 소수점 아래 자릿수만 세어 곱의 소수점을 찍는다(75.9 × 0.6을 455.4로)','두 수의 소수점 아래 자릿수를 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X04','math',5,'u4',ARRAY['M5-2-u4-C3','M5-2-u4-C5','M5-2-u4-C7']::text[],'끝자리 0을 생략하면서 다른 자리의 숫자까지 지우거나 0을 지운 뒤 소수점 위치를 바꾼다','끝자리 0만 생략해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X05','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C2','M5-2-u4-C3']::text[],'같은 소수를 여러 번 더하는 것을 곱셈식으로 세우지 못하고 소수와 자연수를 더한다(1.5를 세 번 더한 것을 1.5 + 3으로)','같은 수를 여러 번 더하면 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X06','math',5,'u4',ARRAY['M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'곱하면 언제나 커진다고 여긴다(1보다 작은 소수를 곱해도 커진다고 본다)','1보다 작은 수를 곱하면 작아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X07','math',5,'u4',ARRAY['M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C7']::text[],'곱의 크기를 어림할 때 곱하는 수와 1을 견주지 않고 곱해지는 수나 자리 수만 본다','곱하는 수를 1과 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X08','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'소수를 분수로 바꿀 때 분모를 잘못 쓴다(0.24를 ⟨24/10⟩로, 1.2를 ⟨12/100⟩로)','소수 한 자리는 분모 10, 두 자리는 100') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X09','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C6']::text[],'0.1·0.01이 몇 개인지 셀 때 개수를 10배 또는 ⟨1/10⟩로 잘못 센다(0.3을 0.1이 30개로)','0.3은 0.1이 3개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X10','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C8']::text[],'10·100을 곱할 때 소수점을 왼쪽으로, 0.1·0.01을 곱할 때 오른쪽으로 옮긴다(방향을 거꾸로 한다)','10배는 오른쪽, ⟨1/10⟩배는 왼쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X11','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C8']::text[],'소수점을 옮기는 자리 수를 잘못 센다(100을 곱하는데 한 자리만 옮긴다)','0의 개수만큼 옮겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X12','math',5,'u4',ARRAY['M5-2-u4-C7','M5-2-u4-C8']::text[],'곱의 자릿수가 모자랄 때 빈 자리를 0으로 채우지 않는다(0.09 × 0.07을 0.063으로)','모자란 자리는 0으로 채워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X13','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7','M5-2-u4-C9']::text[],'자연수의 곱셈(또는 뺄셈)을 잘못 계산한다','세로셈으로 한 번 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X14','math',5,'u4',ARRAY['M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C9']::text[],'어림한 값을 정확한 값처럼 쓰거나, 「적어도 몇 개」에서 모자라는 수를 답으로 고른다','어림은 크기 가리기용 — 모자라면 하나 더') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X15','math',5,'u4',ARRAY['M5-2-u4-C9']::text[],'반 전체의 효과를 견줄 때 한 사람의 효과나 실천한 사람 수 하나만 보고 판단한다','효과 × 사람 수로 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X16','math',5,'u4',ARRAY['M5-2-u4-C5','M5-2-u4-C9']::text[],'시간·단위를 소수로 바꿀 때 잘못 바꾼다(1시간 30분을 1.3시간으로)','30분 = 0.5시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X17','math',5,'u4',ARRAY['M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7']::text[],'「몇 배」를 구할 때 곱셈 대신 덧셈을 한다(1.5 m의 1.2배를 2.7 m로)','「몇 배」는 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u4-X18','math',5,'u4',ARRAY['M5-2-u4-C1','M5-2-u4-C2','M5-2-u4-C3','M5-2-u4-C4','M5-2-u4-C5','M5-2-u4-C6','M5-2-u4-C7','M5-2-u4-C8','M5-2-u4-C9']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔바른, 큰↔작은, 몇 자리↔몇 개','물음의 「잘못·가장·몇 자리」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#1','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',1,'mc','auto','0.34의 10배는 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"0.34의 10배는 얼마인가요?","options":[{"t":"3.4","correct":true},{"t":"0.034","mis":"M5-2-u4-X10"},{"t":"34","mis":"M5-2-u4-X11"},{"t":"340","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","10배는 소수점을 오른쪽으로 한 자리 옮겨요.","0.34 × 10 = 3.4예요."],"variant_rule":{"alt":[{"stem":"2.58의 100배는 얼마인가요?","options":[{"t":"258","correct":true},{"t":"0.0258","mis":"M5-2-u4-X10"},{"t":"2580","mis":"M5-2-u4-X11"},{"t":"25.8","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","100배는 소수점을 오른쪽으로 두 자리 옮겨요.","2.58 × 100 = 258이에요."]},{"stem":"0.071의 1000배는 얼마인가요?","options":[{"t":"71","correct":true},{"t":"0.000071","mis":"M5-2-u4-X10"},{"t":"710","mis":"M5-2-u4-X11"},{"t":"7.1","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","1000배는 소수점을 오른쪽으로 세 자리 옮겨요.","0.071 × 1000 = 71이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#2','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',1,'mc','auto','1.5 + 1.5 + 1.5를 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X05','M5-2-u4-X01']::text[],true,'{"seq":2,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"1.5 + 1.5 + 1.5를 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"1.5 × 3","correct":true},{"t":"1.5 × 4","mis":"M5-2-u4-X18"},{"t":"1.5 + 3","mis":"M5-2-u4-X05"},{"t":"15 × 3","mis":"M5-2-u4-X01"}],"explanation":["1.5를 3번 더했어요.","분수에서 같은 수를 여러 번 더할 때 곱셈으로 적었던 것처럼 소수도 곱셈식으로 적어요.","1.5 + 1.5 + 1.5 = 1.5 × 3 = 4.5예요."],"variant_rule":{"alt":[{"stem":"0.8 + 0.8 + 0.8 + 0.8을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"0.8 × 4","correct":true},{"t":"0.8 × 5","mis":"M5-2-u4-X18"},{"t":"0.8 + 4","mis":"M5-2-u4-X05"},{"t":"8 × 4","mis":"M5-2-u4-X01"}],"explanation":["0.8을 4번 더했어요.","분수에서 같은 수를 여러 번 더할 때 곱셈으로 적었던 것처럼 소수도 곱셈식으로 적어요.","0.8 + 0.8 + 0.8 + 0.8 = 0.8 × 4 = 3.2예요."]},{"stem":"2.3 + 2.3 + 2.3을 곱셈식으로 나타내면 어느 것인가요?","options":[{"t":"2.3 × 3","correct":true},{"t":"2.3 × 4","mis":"M5-2-u4-X18"},{"t":"2.3 + 3","mis":"M5-2-u4-X05"},{"t":"23 × 3","mis":"M5-2-u4-X01"}],"explanation":["2.3을 3번 더했어요.","분수에서 같은 수를 여러 번 더할 때 곱셈으로 적었던 것처럼 소수도 곱셈식으로 적어요.","2.3 + 2.3 + 2.3 = 2.3 × 3 = 6.9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#3','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',1,'ox','auto','0.034의 10배는 0.34예요.',ARRAY['M5-2-u4-X10']::text[],true,'{"seq":3,"concept":"M5-2-u4-C1","difficulty":1,"kind":"ox","stem":"0.034의 10배는 0.34예요.","answer":"O","reason_options":[{"t":"10배 하면 소수점이 오른쪽으로 한 자리 옮겨지므로","correct":true},{"t":"10배 하면 소수점이 왼쪽으로 옮겨지므로","mis":"M5-2-u4-X10"}],"mis":"M5-2-u4-X10","explanation":["10배 하면 소수점이 오른쪽으로 한 자리 옮겨져요.","0.034 × 10 = 0.34예요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"1.5 + 1.5 + 1.5는 1.5 × 3과 같아요.","answer":"O","reason_options":[{"t":"같은 수를 세 번 더한 것은 그 수에 3을 곱한 것과 같으므로","correct":true},{"t":"소수는 곱셈식으로 나타낼 수 없으므로","mis":"M5-2-u4-X05"}],"explanation":["같은 수를 여러 번 더하면 곱셈식으로 적어요.","1.5 + 1.5 + 1.5 = 1.5 × 3 = 4.5예요.","그래서 맞아요."]},{"stem":"0.8을 네 번 더한 값은 3.2예요.","answer":"O","reason_options":[{"t":"0.8 × 4는 0.1이 8 × 4 = 32개이므로","correct":true},{"t":"곱하면 소수점이 한 자리 더 왼쪽으로 가서 0.32가 되므로","mis":"M5-2-u4-X02"}],"explanation":["0.8을 네 번 더한 것은 0.8 × 4예요.","0.8 + 0.8 + 0.8 + 0.8 = 3.2예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#4','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C1',1,'mc','auto','「두 호스 길이의 차이」를 구할 때 알맞은 셈은 무엇인가요?',ARRAY['M5-2-u4-X18']::text[],true,'{"seq":4,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"「두 호스 길이의 차이」를 구할 때 알맞은 셈은 무엇인가요?","options":[{"t":"뺄셈","correct":true},{"t":"곱셈","mis":"M5-2-u4-X18"},{"t":"나눗셈","mis":"M5-2-u4-X18"},{"t":"덧셈","mis":"M5-2-u4-X18"}],"explanation":["무엇을 구하는지 먼저 가려요.","길이의 차이를 구하니 뺄셈이에요.","그래서 뺄셈으로 구해요."],"variant_rule":{"alt":[{"stem":"「1.5 kg인 소화기 3개의 무게」를 구할 때 알맞은 셈은 무엇인가요?","options":[{"t":"곱셈","correct":true},{"t":"뺄셈","mis":"M5-2-u4-X05"},{"t":"나눗셈","mis":"M5-2-u4-X18"},{"t":"소수와 자연수의 덧셈","mis":"M5-2-u4-X05"}],"explanation":["무엇을 구하는지 먼저 가려요.","같은 양이 여러 개 있으니 같은 수를 여러 번 더하는 곱셈이에요.","그래서 곱셈으로 구해요."]},{"stem":"「하루에 1.2 km씩 5일 동안 걸은 거리」를 구할 때 알맞은 셈은 무엇인가요?","options":[{"t":"곱셈","correct":true},{"t":"뺄셈","mis":"M5-2-u4-X05"},{"t":"나눗셈","mis":"M5-2-u4-X18"},{"t":"소수와 자연수의 덧셈","mis":"M5-2-u4-X05"}],"explanation":["무엇을 구하는지 먼저 가려요.","같은 양이 여러 개 있으니 같은 수를 여러 번 더하는 곱셈이에요.","그래서 곱셈으로 구해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#5','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'mc','auto','1.2 × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"1.2 × 4를 계산하면 얼마인가요?","options":[{"t":"4.8","correct":true},{"t":"48","mis":"M5-2-u4-X01"},{"t":"0.48","mis":"M5-2-u4-X02"},{"t":"480","mis":"M5-2-u4-X02"}],"explanation":["12 × 4 = 48이에요.","1.2는 12의 ⟨1/10⟩배이므로 곱도 48의 ⟨1/10⟩배예요.","1.2 × 4 = 4.8이에요."],"variant_rule":{"alt":[{"stem":"0.7 × 6을 계산하면 얼마인가요?","options":[{"t":"4.2","correct":true},{"t":"42","mis":"M5-2-u4-X01"},{"t":"0.42","mis":"M5-2-u4-X02"},{"t":"420","mis":"M5-2-u4-X02"}],"explanation":["7 × 6 = 42예요.","0.7은 7의 ⟨1/10⟩배이므로 곱도 42의 ⟨1/10⟩배예요.","0.7 × 6 = 4.2예요."]},{"stem":"2.6 × 3을 계산하면 얼마인가요?","options":[{"t":"7.8","correct":true},{"t":"78","mis":"M5-2-u4-X01"},{"t":"0.78","mis":"M5-2-u4-X02"},{"t":"780","mis":"M5-2-u4-X02"}],"explanation":["26 × 3 = 78이에요.","2.6은 26의 ⟨1/10⟩배이므로 곱도 78의 ⟨1/10⟩배예요.","2.6 × 3 = 7.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#6','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'sa','auto','0.3 × 4를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u4-C2","difficulty":2,"kind":"sa","stem":"0.3 × 4를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["0.3은 0.1이 3개예요.","이 묶음이 4개이므로 0.1이 3 × 4 = 12개예요.","그래서 0.3 × 4 = 1.2예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"0.8 × 7을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["0.8은 0.1이 8개예요.","이 묶음이 7개이므로 0.1이 8 × 7 = 56개예요.","그래서 0.8 × 7 = 5.6이에요."]},{"stem":"1.2 × 3을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["1.2는 0.1이 12개예요.","이 묶음이 3개이므로 0.1이 12 × 3 = 36개예요.","그래서 1.2 × 3 = 3.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#7','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'mc','auto','수직선의 0에서 0.6씩 4번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X05','M5-2-u4-X18']::text[],true,'{"seq":7,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"수직선의 0에서 0.6씩 4번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?","options":[{"t":"2.4","correct":true},{"t":"24","mis":"M5-2-u4-X01"},{"t":"4.6","mis":"M5-2-u4-X05"},{"t":"3","mis":"M5-2-u4-X18"}],"explanation":["0.6씩 4번 뛰어 세는 것은 0.6을 4번 더한 것이에요.","0.6 × 4 = 0.6 + 0.6 + 0.6 + 0.6이에요.","0.6 + 0.6 + 0.6 + 0.6 = 2.4 — 수직선에서 2.4에 닿아요."],"variant_rule":{"alt":[{"stem":"수직선의 0에서 1.3씩 3번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?","options":[{"t":"3.9","correct":true},{"t":"39","mis":"M5-2-u4-X01"},{"t":"4.3","mis":"M5-2-u4-X05"},{"t":"5.2","mis":"M5-2-u4-X18"}],"explanation":["1.3씩 3번 뛰어 세는 것은 1.3을 3번 더한 것이에요.","1.3 × 3 = 1.3 + 1.3 + 1.3이에요.","1.3 + 1.3 + 1.3 = 3.9 — 수직선에서 3.9에 닿아요."]},{"stem":"수직선의 0에서 0.9씩 5번 뛰어 세었어요. 닿은 곳의 수는 얼마인가요?","options":[{"t":"4.5","correct":true},{"t":"45","mis":"M5-2-u4-X01"},{"t":"5.9","mis":"M5-2-u4-X05"},{"t":"5.4","mis":"M5-2-u4-X18"}],"explanation":["0.9씩 5번 뛰어 세는 것은 0.9를 5번 더한 것이에요.","0.9 × 5 = 0.9 + 0.9 + 0.9 + 0.9 + 0.9예요.","0.9 + 0.9 + 0.9 + 0.9 + 0.9 = 4.5 — 수직선에서 4.5에 닿아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#8','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'mc','auto','우유로 플라스틱 장난감을 만들어요. 한 모둠에 우유를 0.6 L씩, 5모둠이 썼어요. 우리 반이 쓴 우유는 모두 몇 L인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X05','M5-2-u4-X02']::text[],true,'{"seq":8,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"우유로 플라스틱 장난감을 만들어요. 한 모둠에 우유를 0.6 L씩, 5모둠이 썼어요. 우리 반이 쓴 우유는 모두 몇 L인가요?","options":[{"t":"3 L","correct":true},{"t":"30 L","mis":"M5-2-u4-X01"},{"t":"5.6 L","mis":"M5-2-u4-X05"},{"t":"0.3 L","mis":"M5-2-u4-X02"}],"explanation":["같은 양 0.6 L가 5번 있으니 곱셈식 0.6 × 5를 세워요.","6 × 5 = 30이에요. 곱해지는 수가 ⟨1/10⟩배이면 곱도 ⟨1/10⟩배예요.","0.6 × 5 = 3 — 모두 3 L예요."],"variant_rule":{"alt":[{"stem":"리본을 한 사람에게 1.4 m씩 6명에게 나누어 주었어요. 나누어 준 리본은 모두 몇 m인가요?","options":[{"t":"8.4 m","correct":true},{"t":"84 m","mis":"M5-2-u4-X01"},{"t":"7.4 m","mis":"M5-2-u4-X05"},{"t":"0.84 m","mis":"M5-2-u4-X02"}],"explanation":["같은 양 1.4 m가 6번 있으니 곱셈식 1.4 × 6을 세워요.","14 × 6 = 84예요. 곱해지는 수가 ⟨1/10⟩배이면 곱도 ⟨1/10⟩배예요.","1.4 × 6 = 8.4 — 모두 8.4 m예요."]},{"stem":"하루에 2.5 km씩 3일 동안 걸었어요. 걸은 거리는 모두 몇 km인가요?","options":[{"t":"7.5 km","correct":true},{"t":"75 km","mis":"M5-2-u4-X01"},{"t":"5.5 km","mis":"M5-2-u4-X05"},{"t":"0.75 km","mis":"M5-2-u4-X02"}],"explanation":["같은 양 2.5 km가 3번 있으니 곱셈식 2.5 × 3을 세워요.","25 × 3 = 75예요. 곱해지는 수가 ⟨1/10⟩배이면 곱도 ⟨1/10⟩배예요.","2.5 × 3 = 7.5 — 모두 7.5 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#9','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',2,'ox','auto','0.3 × 4는 0.1이 12개예요.',ARRAY['M5-2-u4-X09']::text[],true,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":2,"kind":"ox","stem":"0.3 × 4는 0.1이 12개예요.","answer":"O","reason_options":[{"t":"0.3은 0.1이 3개이고 이것이 4묶음이므로","correct":true},{"t":"0.3은 0.1이 30개이므로","mis":"M5-2-u4-X09"}],"mis":"M5-2-u4-X09","explanation":["0.3은 0.1이 3개예요.","3 × 4 = 12 — 0.1이 12개예요.","0.3 × 4 = 1.2예요."],"variant_rule":{"alt":[{"stem":"1.2 × 4 = ⟨12/10⟩ × 4로 계산할 수 있어요.","answer":"O","reason_options":[{"t":"1.2 = ⟨12/10⟩이므로 분수의 곱셈으로 바꿀 수 있으므로","correct":true},{"t":"1.2는 ⟨12/100⟩이므로","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10인 분수예요.","⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이에요.","그래서 맞아요."]},{"stem":"13.7 × 3 = 41.1이에요.","answer":"O","reason_options":[{"t":"137 × 3 = 411의 ⟨1/10⟩배이므로","correct":true},{"t":"137 × 3 = 411이므로 소수점을 찍지 않아도 되므로","mis":"M5-2-u4-X01"}],"explanation":["137 × 3 = 411이에요.","13.7은 137의 ⟨1/10⟩배예요.","13.7 × 3 = 41.1 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_basic#10','math',5,2,'u4','L02','g5_2_math_u4_L02_basic','lesson_basic','M5-2-u4-C2',3,'mc','auto','1.2 × 4의 곱은 어느 두 수 사이에 있나요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X14']::text[],true,'{"seq":10,"concept":"M5-2-u4-C2","difficulty":3,"kind":"mc","stem":"1.2 × 4의 곱은 어느 두 수 사이에 있나요?","options":[{"t":"4와 8 사이","correct":true},{"t":"40과 80 사이","mis":"M5-2-u4-X01"},{"t":"0.4와 0.8 사이","mis":"M5-2-u4-X02"},{"t":"8과 12 사이","mis":"M5-2-u4-X14"}],"explanation":["1.2는 1과 2 사이의 수예요.","1 × 4 = 4, 2 × 4 = 8이에요.","그래서 곱은 4와 8 사이 — 실제로 1.2 × 4 = 4.8이에요."],"variant_rule":{"alt":[{"stem":"2.7 × 3의 곱은 어느 두 수 사이에 있나요?","options":[{"t":"6과 9 사이","correct":true},{"t":"60과 90 사이","mis":"M5-2-u4-X01"},{"t":"0.6과 0.9 사이","mis":"M5-2-u4-X02"},{"t":"3과 6 사이","mis":"M5-2-u4-X14"}],"explanation":["2.7은 2와 3 사이의 수예요.","2 × 3 = 6, 3 × 3 = 9예요.","그래서 곱은 6과 9 사이 — 실제로 2.7 × 3 = 8.1이에요."]},{"stem":"3.4 × 6의 곱은 어느 두 수 사이에 있나요?","options":[{"t":"18과 24 사이","correct":true},{"t":"180과 240 사이","mis":"M5-2-u4-X01"},{"t":"1.8과 2.4 사이","mis":"M5-2-u4-X02"},{"t":"12와 18 사이","mis":"M5-2-u4-X14"}],"explanation":["3.4는 3과 4 사이의 수예요.","3 × 6 = 18, 4 × 6 = 24예요.","그래서 곱은 18과 24 사이 — 실제로 3.4 × 6 = 20.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#1','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C1',2,'mc','auto','왼쪽 호스는 3.2 m, 오른쪽 호스는 1.5 m예요. 왼쪽 호스는 오른쪽 호스보다 몇 m 더 긴가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X13','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C1","difficulty":2,"kind":"mc","stem":"왼쪽 호스는 3.2 m, 오른쪽 호스는 1.5 m예요. 왼쪽 호스는 오른쪽 호스보다 몇 m 더 긴가요?","options":[{"t":"1.7 m","correct":true},{"t":"4.7 m","mis":"M5-2-u4-X18"},{"t":"2.3 m","mis":"M5-2-u4-X13"},{"t":"17 m","mis":"M5-2-u4-X02"}],"explanation":["길이의 차이는 뺄셈으로 구해요.","소수점을 맞추어 빼요 — 3.2 − 1.5 = 1.7이에요.","그래서 1.7 m 더 길어요."],"variant_rule":{"alt":[{"stem":"왼쪽 리본는 4.13 m, 오른쪽 리본는 2.56 m예요. 왼쪽 리본는 오른쪽 리본보다 몇 m 더 긴가요?","options":[{"t":"1.57 m","correct":true},{"t":"6.69 m","mis":"M5-2-u4-X18"},{"t":"2.43 m","mis":"M5-2-u4-X13"},{"t":"15.7 m","mis":"M5-2-u4-X02"}],"explanation":["길이의 차이는 뺄셈으로 구해요.","소수점을 맞추어 빼요 — 4.13 − 2.56 = 1.57이에요.","그래서 1.57 m 더 길어요."]},{"stem":"왼쪽 줄넘기는 5.6 m, 오른쪽 줄넘기는 2.8 m예요. 왼쪽 줄넘기는 오른쪽 줄넘기보다 몇 m 더 긴가요?","options":[{"t":"2.8 m","correct":true},{"t":"8.4 m","mis":"M5-2-u4-X18"},{"t":"3.2 m","mis":"M5-2-u4-X13"},{"t":"28 m","mis":"M5-2-u4-X02"}],"explanation":["길이의 차이는 뺄셈으로 구해요.","소수점을 맞추어 빼요 — 5.6 − 2.8 = 2.8이에요.","그래서 2.8 m 더 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#2','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',2,'mc','auto','1.2 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],true,'{"seq":2,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"1.2 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨12/10⟩ × 4","correct":true},{"t":"⟨12/100⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/12⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨12/10⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.2 = ⟨12/10⟩예요.","⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이에요."],"variant_rule":{"alt":[{"stem":"0.7 × 8을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨7/10⟩ × 8","correct":true},{"t":"⟨7/100⟩ × 8","mis":"M5-2-u4-X08"},{"t":"⟨1/7⟩ × 8","mis":"M5-2-u4-X08"},{"t":"⟨7/10⟩ × ⟨8/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.7 = ⟨7/10⟩이에요.","⟨7/10⟩ × 8 = ⟨56/10⟩ = 5.6이에요."]},{"stem":"3.6 × 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨36/10⟩ × 2","correct":true},{"t":"⟨36/100⟩ × 2","mis":"M5-2-u4-X08"},{"t":"⟨1/36⟩ × 2","mis":"M5-2-u4-X08"},{"t":"⟨36/10⟩ × ⟨2/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","3.6 = ⟨36/10⟩이에요.","⟨36/10⟩ × 2 = ⟨72/10⟩ = 7.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#3','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C1',3,'mc','auto','기념품으로 1.5 kg인 소화기를 3개 받았어요. 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있을까요?',ARRAY['M5-2-u4-X13','M5-2-u4-X18','M5-2-u4-X05']::text[],true,'{"seq":3,"concept":"M5-2-u4-C1","difficulty":3,"kind":"mc","stem":"기념품으로 1.5 kg인 소화기를 3개 받았어요. 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있을까요?","options":[{"t":"담을 수 없다 — 4.5 kg은 4 kg보다 무겁다","correct":true},{"t":"담을 수 있다 — 4.5 kg은 4 kg보다 가볍다","mis":"M5-2-u4-X13"},{"t":"담을 수 있다 — 소화기가 3개뿐이다","mis":"M5-2-u4-X18"},{"t":"알 수 없다 — 곱셈을 아직 안 배웠다","mis":"M5-2-u4-X05"}],"explanation":["소화기 3개의 무게는 1.5 × 3 = 4.5(kg)이에요.","4.5와 4를 견주어요.","4.5 > 4 — 그래서 담을 수 없어요."],"variant_rule":{"alt":[{"stem":"기념품으로 2.4 kg인 소화기를 3개 받았어요. 7 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있을까요?","options":[{"t":"담을 수 없다 — 7.2 kg은 7 kg보다 무겁다","correct":true},{"t":"담을 수 있다 — 7.2 kg은 7 kg보다 가볍다","mis":"M5-2-u4-X13"},{"t":"담을 수 있다 — 소화기가 3개뿐이다","mis":"M5-2-u4-X18"},{"t":"알 수 없다 — 곱셈을 아직 안 배웠다","mis":"M5-2-u4-X05"}],"explanation":["소화기 3개의 무게는 2.4 × 3 = 7.2(kg)이에요.","7.2와 7을 견주어요.","7.2 > 7 — 그래서 담을 수 없어요."]},{"stem":"기념품으로 0.8 kg인 소화기를 6개 받았어요. 5 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있을까요?","options":[{"t":"담을 수 있다 — 4.8 kg은 5 kg보다 가볍다","correct":true},{"t":"담을 수 없다 — 4.8 kg이 5 kg보다 무겁다","mis":"M5-2-u4-X13"},{"t":"담을 수 없다 — 소화기가 6개나 된다","mis":"M5-2-u4-X18"},{"t":"알 수 없다 — 곱셈을 아직 안 배웠다","mis":"M5-2-u4-X05"}],"explanation":["소화기 6개의 무게는 0.8 × 6 = 4.8(kg)이에요.","4.8과 5를 견주어요.","4.8 < 5 — 그래서 담을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#4','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'error','auto','수아는 1.2 × 4를 48로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":4,"concept":"M5-2-u4-C2","difficulty":3,"kind":"error","stem":"수아는 1.2 × 4를 48로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 4.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"12 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.2는 1과 2 사이의 수라 곱은 48보다 훨씬 작아야 해요.","12 × 4 = 48은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 4.8이에요."],"variant_rule":{"alt":[{"stem":"민준은 2.3 × 6을 138로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 13.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"23 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["2.3은 2와 3 사이의 수라 곱은 138보다 훨씬 작아야 해요.","23 × 6 = 138은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 13.8이에요."]},{"stem":"가온은 3.7 × 5를 185로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 18.5이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"37 × 5를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["3.7은 3과 4 사이의 수라 곱은 185보다 훨씬 작아야 해요.","37 × 5 = 185는 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 18.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#5','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'mc','auto','한 변의 길이가 2.4 cm인 정삼각형의 둘레는 몇 cm인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X05','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C2","difficulty":3,"kind":"mc","stem":"한 변의 길이가 2.4 cm인 정삼각형의 둘레는 몇 cm인가요?","options":[{"t":"7.2 cm","correct":true},{"t":"72 cm","mis":"M5-2-u4-X01"},{"t":"5.4 cm","mis":"M5-2-u4-X05"},{"t":"0.72 cm","mis":"M5-2-u4-X02"}],"explanation":["정삼각형은 3개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 3이에요.","2.4 × 3 = 7.2 — 둘레는 7.2 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 1.7 cm인 정사각형의 둘레는 몇 cm인가요?","options":[{"t":"6.8 cm","correct":true},{"t":"68 cm","mis":"M5-2-u4-X01"},{"t":"5.7 cm","mis":"M5-2-u4-X05"},{"t":"0.68 cm","mis":"M5-2-u4-X02"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 4예요.","1.7 × 4 = 6.8 — 둘레는 6.8 cm예요."]},{"stem":"한 변의 길이가 3.5 cm인 정오각형의 둘레는 몇 cm인가요?","options":[{"t":"17.5 cm","correct":true},{"t":"175 cm","mis":"M5-2-u4-X01"},{"t":"8.5 cm","mis":"M5-2-u4-X05"},{"t":"1.75 cm","mis":"M5-2-u4-X02"}],"explanation":["정오각형은 5개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 5예요.","3.5 × 5 = 17.5 — 둘레는 17.5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#6','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',3,'mc','auto','1.8 × 4와 2.3 × 3 가운데 곱이 더 큰 것은 어느 것인가요?',ARRAY['M5-2-u4-X07','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":6,"concept":"M5-2-u4-C2","difficulty":3,"kind":"mc","stem":"1.8 × 4와 2.3 × 3 가운데 곱이 더 큰 것은 어느 것인가요?","options":[{"t":"1.8 × 4","correct":true},{"t":"2.3 × 3","mis":"M5-2-u4-X07"},{"t":"두 곱이 같다","mis":"M5-2-u4-X13"},{"t":"견줄 수 없다","mis":"M5-2-u4-X18"}],"explanation":["두 곱을 각각 계산해요.","1.8 × 4 = 7.2, 2.3 × 3 = 6.9예요.","7.2 > 6.9이므로 1.8 × 4가 더 커요."],"variant_rule":{"alt":[{"stem":"0.7 × 9와 1.6 × 4 가운데 곱이 더 큰 것은 어느 것인가요?","options":[{"t":"1.6 × 4","correct":true},{"t":"0.7 × 9","mis":"M5-2-u4-X07"},{"t":"두 곱이 같다","mis":"M5-2-u4-X13"},{"t":"견줄 수 없다","mis":"M5-2-u4-X18"}],"explanation":["두 곱을 각각 계산해요.","0.7 × 9 = 6.3, 1.6 × 4 = 6.4예요.","6.4 > 6.3이므로 1.6 × 4가 더 커요."]},{"stem":"4.2 × 3과 2.9 × 4 가운데 곱이 더 큰 것은 어느 것인가요?","options":[{"t":"4.2 × 3","correct":true},{"t":"2.9 × 4","mis":"M5-2-u4-X07"},{"t":"두 곱이 같다","mis":"M5-2-u4-X13"},{"t":"견줄 수 없다","mis":"M5-2-u4-X18"}],"explanation":["두 곱을 각각 계산해요.","4.2 × 3 = 12.6, 2.9 × 4 = 11.6이에요.","12.6 > 11.6이므로 4.2 × 3이 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#7','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C1',3,'ox','auto','3.4의 ⟨1/10⟩은 34예요.',ARRAY['M5-2-u4-X10']::text[],true,'{"seq":7,"concept":"M5-2-u4-C1","difficulty":3,"kind":"ox","stem":"3.4의 ⟨1/10⟩은 34예요.","answer":"X","reason_options":[{"t":"⟨1/10⟩ 하면 소수점이 왼쪽으로 한 자리 옮겨져 0.34이므로","correct":true},{"t":"⟨1/10⟩ 하면 소수점이 오른쪽으로 옮겨지므로","mis":"M5-2-u4-X10"}],"mis":"M5-2-u4-X10","explanation":["⟨1/10⟩ 하면 소수점이 왼쪽으로 한 자리 옮겨져요.","3.4의 ⟨1/10⟩은 0.34예요.","34는 3.4의 10배예요."],"variant_rule":{"alt":[{"stem":"0.34의 100배는 3.4예요.","answer":"X","reason_options":[{"t":"100배 하면 소수점이 오른쪽으로 두 자리 옮겨져 34이므로","correct":true},{"t":"100배든 10배든 한 자리만 옮기므로","mis":"M5-2-u4-X11"}],"explanation":["100배는 10배를 두 번 한 것이에요.","소수점이 오른쪽으로 두 자리 옮겨져요.","0.34 × 100 = 34예요."]},{"stem":"3.2 m와 1.5 m의 차이는 곱셈으로 구해요.","answer":"X","reason_options":[{"t":"길이의 차이는 뺄셈 3.2 − 1.5로 구하므로","correct":true},{"t":"두 수가 나오면 언제나 곱하므로","mis":"M5-2-u4-X18"}],"explanation":["차이는 뺄셈으로 구해요.","3.2 − 1.5 = 1.7이에요.","곱셈은 같은 양이 여러 개일 때 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#8','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',4,'sa','auto','우유 7.5 L가 필요해요. 한 병에 1.2 L인 우유를 적어도 몇 병 사야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u4-C2","difficulty":4,"kind":"sa","stem":"우유 7.5 L가 필요해요. 한 병에 1.2 L인 우유를 적어도 몇 병 사야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["1.2 × 6 = 7.2 < 7.5 — 모자라요.","1.2 × 7 = 8.4 > 7.5 — 넉넉해요.","그래서 적어도 7병을 사야 해요."],"mis":"M5-2-u4-X14","variant_rule":{"alt":[{"stem":"주스 4.5 L가 필요해요. 한 병에 0.6 L인 주스를 적어도 몇 병 사야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["0.6 × 7 = 4.2 < 4.5 — 모자라요.","0.6 × 8 = 4.8 > 4.5 — 넉넉해요.","그래서 적어도 8병을 사야 해요."]},{"stem":"물 10 L가 필요해요. 한 병에 1.5 L인 물를 적어도 몇 병 사야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["1.5 × 6 = 9 < 10 — 모자라요.","1.5 × 7 = 10.5 > 10 — 넉넉해요.","그래서 적어도 7병을 사야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#9','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',4,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":4,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.4 × 7","r":"2.8"},{"l":"1.6 × 5","r":"8"},{"l":"2.3 × 4","r":"9.2"}],"mis":"M5-2-u4-X02","explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.4 × 7 = 2.8 · 1.6 × 5 = 8이에요.","2.3 × 4 = 9.2예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.9 × 3","r":"2.7"},{"l":"1.5 × 6","r":"9"},{"l":"3.2 × 5","r":"16"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.9 × 3 = 2.7 · 1.5 × 6 = 9예요.","3.2 × 5 = 16이에요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.6 × 8","r":"4.8"},{"l":"2.4 × 3","r":"7.2"},{"l":"1.7 × 4","r":"6.8"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.6 × 8 = 4.8 · 2.4 × 3 = 7.2예요.","1.7 × 4 = 6.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L02_challenge#10','math',5,2,'u4','L02','g5_2_math_u4_L02_challenge','lesson_challenge','M5-2-u4-C2',4,'essay','teacher','1.2 × 4를 분수의 곱셈과 자연수의 곱셈 두 가지 방법으로 계산하고, 곱을 48로 쓰면 안 되는 까닭을 어림을 이용해 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C2","difficulty":4,"kind":"essay","stem":"1.2 × 4를 분수의 곱셈과 자연수의 곱셈 두 가지 방법으로 계산하고, 곱을 48로 쓰면 안 되는 까닭을 어림을 이용해 설명해 보세요.","answer_guide":{"answer":"예: 분수로 — 1.2 = ⟨12/10⟩이므로 ⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이다. 자연수로 — 12 × 4 = 48이고 1.2는 12의 ⟨1/10⟩배이므로 곱도 48의 ⟨1/10⟩배인 4.8이다. 1.2는 1과 2 사이의 수이므로 1.2 × 4는 1 × 4 = 4와 2 × 4 = 8 사이에 있어야 해서 48은 너무 크다.","scoring_points":["분수의 곱셈으로 4.8을 구했는가","자연수의 곱셈과 ⟨1/10⟩배로 4.8을 구했는가","곱이 4와 8 사이여야 해서 48은 틀렸다고 설명했는가"]},"explanation":["⟨12/10⟩ × 4 = ⟨48/10⟩ = 4.8이에요.","12 × 4 = 48의 ⟨1/10⟩배는 4.8이에요.","곱은 4와 8 사이에 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#1','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',1,'sa','auto','0.24 × 3을 자연수의 곱셈을 이용해 계산하려고 해요. 24 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C3","difficulty":1,"kind":"sa","stem":"0.24 × 3을 자연수의 곱셈을 이용해 계산하려고 해요. 24 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","24 × 3 = 72예요.","그래서 0.24 × 3 = 0.72예요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"1.35 × 4를 자연수의 곱셈을 이용해 계산하려고 해요. 135 × 4는 얼마인가요? 숫자로 쓰세요.","answer":["540"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","135 × 4 = 540이에요.","그래서 1.35 × 4 = 5.4예요."]},{"stem":"2.17 × 6을 자연수의 곱셈을 이용해 계산하려고 해요. 217 × 6은 얼마인가요? 숫자로 쓰세요.","answer":["1302"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","217 × 6 = 1302예요.","그래서 2.17 × 6 = 13.02예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#2','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',1,'mc','auto','0.24 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],true,'{"seq":2,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"0.24 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨24/100⟩ × 3","correct":true},{"t":"⟨24/1000⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨1/24⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨24/100⟩ × ⟨3/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.24 = ⟨24/100⟩예요.","⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72예요."],"variant_rule":{"alt":[{"stem":"0.36 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨36/100⟩ × 4","correct":true},{"t":"⟨36/1000⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/36⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨36/100⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.36 = ⟨36/100⟩이에요.","⟨36/100⟩ × 4 = ⟨144/100⟩ = 1.44예요."]},{"stem":"1.25 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨125/100⟩ × 3","correct":true},{"t":"⟨125/1000⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨1/125⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨125/100⟩ × ⟨3/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.25 = ⟨125/100⟩예요.","⟨125/100⟩ × 3 = ⟨375/100⟩ = 3.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#3','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',1,'ox','auto','0.24 × 3 = 0.72예요.',ARRAY['M5-2-u4-X02']::text[],true,'{"seq":3,"concept":"M5-2-u4-C3","difficulty":1,"kind":"ox","stem":"0.24 × 3 = 0.72예요.","answer":"O","reason_options":[{"t":"24 × 3 = 72의 ⟨1/100⟩배이므로","correct":true},{"t":"24 × 3 = 72의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"mis":"M5-2-u4-X02","explanation":["24 × 3 = 72예요.","0.24는 24의 ⟨1/100⟩배예요.","0.24 × 3 = 0.72 — 맞아요."],"variant_rule":{"alt":[{"stem":"0.24는 ⟨24/100⟩와 같아요.","answer":"O","reason_options":[{"t":"소수 두 자리 수는 분모가 100인 분수로 나타내므로","correct":true},{"t":"소수는 분모가 언제나 10이므로","mis":"M5-2-u4-X08"}],"explanation":["0.01이 24개이면 0.24예요.","⟨1/100⟩이 24개이면 ⟨24/100⟩예요.","0.24 = ⟨24/100⟩ — 맞아요."]},{"stem":"5.40은 끝자리 0을 생략해 5.4로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"소수의 끝자리 0은 생략해도 크기가 같으므로","correct":true},{"t":"끝자리 0을 생략하면 0.54가 되므로","mis":"M5-2-u4-X04"}],"explanation":["5.40은 5와 0.4와 0.00을 더한 수예요.","끝자리 0은 크기를 바꾸지 않아요.","5.40 = 5.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#4','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',1,'mc','auto','24 × 3 = 72예요. 이것을 이용하여 0.24 × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X01']::text[],true,'{"seq":4,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"24 × 3 = 72예요. 이것을 이용하여 0.24 × 3을 계산하면 얼마인가요?","options":[{"t":"0.72","correct":true},{"t":"0.072","mis":"M5-2-u4-X02"},{"t":"7.2","mis":"M5-2-u4-X02"},{"t":"72","mis":"M5-2-u4-X01"}],"explanation":["0.24는 24의 ⟨1/100⟩배예요.","곱도 72의 ⟨1/100⟩배가 돼요.","0.24 × 3 = 0.72예요."],"variant_rule":{"alt":[{"stem":"135 × 4 = 540이에요. 이것을 이용하여 1.35 × 4를 계산하면 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"0.54","mis":"M5-2-u4-X02"},{"t":"54","mis":"M5-2-u4-X02"},{"t":"540","mis":"M5-2-u4-X01"}],"explanation":["1.35는 135의 ⟨1/100⟩배예요.","곱도 540의 ⟨1/100⟩배가 돼요.","1.35 × 4 = 5.4예요."]},{"stem":"312 × 5 = 1560이에요. 이것을 이용하여 3.12 × 5를 계산하면 얼마인가요?","options":[{"t":"15.6","correct":true},{"t":"1.56","mis":"M5-2-u4-X02"},{"t":"156","mis":"M5-2-u4-X02"},{"t":"1560","mis":"M5-2-u4-X01"}],"explanation":["3.12는 312의 ⟨1/100⟩배예요.","곱도 1560의 ⟨1/100⟩배가 돼요.","3.12 × 5 = 15.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#5','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'mc','auto','0.24 × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"0.24 × 3을 계산하면 얼마인가요?","options":[{"t":"0.72","correct":true},{"t":"72","mis":"M5-2-u4-X01"},{"t":"7.2","mis":"M5-2-u4-X02"},{"t":"0.072","mis":"M5-2-u4-X02"}],"explanation":["24 × 3 = 72예요.","0.24는 24의 ⟨1/100⟩배이므로 곱도 72의 ⟨1/100⟩배예요.","0.24 × 3 = 0.72예요."],"variant_rule":{"alt":[{"stem":"1.35 × 4를 계산하면 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"540","mis":"M5-2-u4-X01"},{"t":"54","mis":"M5-2-u4-X02"},{"t":"0.54","mis":"M5-2-u4-X02"}],"explanation":["135 × 4 = 540이에요.","1.35는 135의 ⟨1/100⟩배이므로 곱도 540의 ⟨1/100⟩배예요.","1.35 × 4 = 5.4예요."]},{"stem":"2.59 × 13을 계산하면 얼마인가요?","options":[{"t":"33.67","correct":true},{"t":"3367","mis":"M5-2-u4-X01"},{"t":"336.7","mis":"M5-2-u4-X02"},{"t":"3.367","mis":"M5-2-u4-X02"}],"explanation":["259 × 13 = 3367이에요.","2.59는 259의 ⟨1/100⟩배이므로 곱도 3367의 ⟨1/100⟩배예요.","2.59 × 13 = 33.67이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#6','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'mc','auto','4.37 × 5에서 4.37을 4로 어림하면 어림한 값은 얼마쯤인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X05']::text[],true,'{"seq":6,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"4.37 × 5에서 4.37을 4로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"20","correct":true},{"t":"200","mis":"M5-2-u4-X02"},{"t":"25","mis":"M5-2-u4-X13"},{"t":"9","mis":"M5-2-u4-X05"}],"explanation":["4.37을 계산하기 쉬운 수 4로 어림해요.","4 × 5 = 20이에요.","실제 곱 4.37 × 5 = 21.85와 비슷해요 — 소수점 위치를 점검할 수 있어요."],"variant_rule":{"alt":[{"stem":"1.98 × 6에서 1.98을 2로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"12","correct":true},{"t":"120","mis":"M5-2-u4-X02"},{"t":"18","mis":"M5-2-u4-X13"},{"t":"8","mis":"M5-2-u4-X05"}],"explanation":["1.98을 계산하기 쉬운 수 2로 어림해요.","2 × 6 = 12예요.","실제 곱 1.98 × 6 = 11.88과 비슷해요 — 소수점 위치를 점검할 수 있어요."]},{"stem":"3.06 × 8에서 3.06을 3으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"24","correct":true},{"t":"240","mis":"M5-2-u4-X02"},{"t":"32","mis":"M5-2-u4-X13"},{"t":"11","mis":"M5-2-u4-X05"}],"explanation":["3.06을 계산하기 쉬운 수 3으로 어림해요.","3 × 8 = 24예요.","실제 곱 3.06 × 8 = 24.48과 비슷해요 — 소수점 위치를 점검할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#7','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'mc','auto','우리 학교 운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달렸다면 모두 몇 km를 달렸나요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"우리 학교 운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달렸다면 모두 몇 km를 달렸나요?","options":[{"t":"0.72 km","correct":true},{"t":"72 km","mis":"M5-2-u4-X01"},{"t":"0.072 km","mis":"M5-2-u4-X02"},{"t":"7.2 km","mis":"M5-2-u4-X02"}],"explanation":["식은 0.24 × 3이에요.","24 × 3 = 72이고 0.24는 24의 ⟨1/100⟩배예요.","곱도 ⟨1/100⟩배 — 0.24 × 3 = 0.72, 0.72 km예요."],"variant_rule":{"alt":[{"stem":"망고주스 한 잔에 망고가 0.35 kg 필요해요. 주스 6잔을 만들려면 망고가 몇 kg 필요한가요?","options":[{"t":"2.1 kg","correct":true},{"t":"210 kg","mis":"M5-2-u4-X01"},{"t":"0.21 kg","mis":"M5-2-u4-X02"},{"t":"21 kg","mis":"M5-2-u4-X02"}],"explanation":["식은 0.35 × 6이에요.","35 × 6 = 210이고 0.35는 35의 ⟨1/100⟩배예요.","곱도 ⟨1/100⟩배 — 0.35 × 6 = 2.1, 2.1 kg이에요."]},{"stem":"클립 한 개의 무게는 0.45 g이에요. 클립 8개의 무게는 몇 g인가요?","options":[{"t":"3.6 g","correct":true},{"t":"360 g","mis":"M5-2-u4-X01"},{"t":"0.36 g","mis":"M5-2-u4-X02"},{"t":"36 g","mis":"M5-2-u4-X02"}],"explanation":["식은 0.45 × 8이에요.","45 × 8 = 360이고 0.45는 45의 ⟨1/100⟩배예요.","곱도 ⟨1/100⟩배 — 0.45 × 8 = 3.6, 3.6 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#8','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'ox','auto','4.37 × 5는 20보다 조금 커요.',ARRAY['M5-2-u4-X07']::text[],true,'{"seq":8,"concept":"M5-2-u4-C3","difficulty":2,"kind":"ox","stem":"4.37 × 5는 20보다 조금 커요.","answer":"O","reason_options":[{"t":"4.37을 4로 어림하면 4 × 5 = 20이고 4.37은 4보다 조금 크므로","correct":true},{"t":"4.37에 소수점이 있어 곱이 20보다 작으므로","mis":"M5-2-u4-X07"}],"mis":"M5-2-u4-X07","explanation":["4.37을 4로 어림하면 4 × 5 = 20이에요.","4.37은 4보다 조금 커요.","4.37 × 5 = 21.85 — 20보다 조금 커요."],"variant_rule":{"alt":[{"stem":"1.35 × 4 = 0.540이에요.","answer":"X","reason_options":[{"t":"1.35는 1보다 커서 곱은 4보다 커야 하고 바른 곱은 5.4이므로","correct":true},{"t":"135 × 4 = 540의 ⟨1/1000⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["1 × 4 = 4니 곱은 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배는 5.40이에요.","끝자리 0을 생략하면 5.4예요."]},{"stem":"2.59 × 13 = 336.7이에요.","answer":"X","reason_options":[{"t":"259 × 13 = 3367의 ⟨1/100⟩배인 33.67이므로","correct":true},{"t":"259 × 13 = 3367의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["259 × 13 = 3367이에요.","2.59는 259의 ⟨1/100⟩배예요.","2.59 × 13 = 33.67이에요 — 3 × 13 = 39쯤과도 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#9','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',2,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u4-C3","difficulty":2,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.24 × 3","r":"0.72"},{"l":"1.35 × 4","r":"5.4"},{"l":"0.18 × 5","r":"0.9"}],"mis":"M5-2-u4-X02","explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.24 × 3 = 0.72 · 1.35 × 4 = 5.4예요.","0.18 × 5 = 0.9예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.45 × 6","r":"2.7"},{"l":"1.12 × 5","r":"5.6"},{"l":"2.06 × 3","r":"6.18"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.45 × 6 = 2.7 · 1.12 × 5 = 5.6이에요.","2.06 × 3 = 6.18이에요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.75 × 4","r":"3"},{"l":"3.14 × 2","r":"6.28"},{"l":"0.08 × 9","r":"0.72"}],"explanation":["자연수끼리 곱한 뒤 곱해지는 수의 소수점 자리만큼 소수점을 찍어요.","0.75 × 4 = 3 · 3.14 × 2 = 6.28이에요.","0.08 × 9 = 0.72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_basic#10','math',5,2,'u4','L03','g5_2_math_u4_L03_basic','lesson_basic','M5-2-u4-C3',3,'mc','auto','망고주스 한 잔에 망고가 0.35 kg 필요해요. 망고 2 kg으로 주스 6잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X14']::text[],true,'{"seq":10,"concept":"M5-2-u4-C3","difficulty":3,"kind":"mc","stem":"망고주스 한 잔에 망고가 0.35 kg 필요해요. 망고 2 kg으로 주스 6잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?","options":[{"t":"만들 수 없다 — 0.4 × 6 = 2.4 kg쯤 필요하다","correct":true},{"t":"만들 수 있다 — 6은 2의 3배다","mis":"M5-2-u4-X18"},{"t":"만들 수 있다 — 0.4 × 10 = 4이다","mis":"M5-2-u4-X14"},{"t":"알 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.35를 0.4로 어림해요.","0.4 × 6 = 2.4(kg)쯤 필요해요.","정확히는 0.35 × 6 = 2.1(kg) — 가진 망고 2 kg보다 많아요."],"variant_rule":{"alt":[{"stem":"망고주스 한 잔에 망고가 0.42 kg 필요해요. 망고 1.9 kg으로 주스 5잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?","options":[{"t":"만들 수 없다 — 0.4 × 5 = 2 kg쯤 필요하다","correct":true},{"t":"만들 수 있다 — 한 잔에 1 kg도 안 든다","mis":"M5-2-u4-X18"},{"t":"만들 수 있다 — 0.4 × 10 = 4이다","mis":"M5-2-u4-X14"},{"t":"알 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.42를 0.4로 어림해요.","0.4 × 5 = 2(kg)쯤 필요해요.","정확히는 0.42 × 5 = 2.1(kg) — 가진 망고 1.9 kg보다 많아요."]},{"stem":"망고주스 한 잔에 망고가 0.28 kg 필요해요. 망고 3 kg으로 주스 9잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?","options":[{"t":"만들 수 있다 — 0.3 × 9 = 2.7 kg쯤이면 된다","correct":true},{"t":"만들 수 없다 — 망고가 3 kg뿐이다","mis":"M5-2-u4-X18"},{"t":"만들 수 없다 — 9잔은 너무 많다","mis":"M5-2-u4-X18"},{"t":"알 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.28을 0.3으로 어림해요.","0.3 × 9 = 2.7(kg)쯤 필요해요.","정확히는 0.28 × 9 = 2.52(kg) — 가진 망고로 충분해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#1','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',2,'mc','auto','1.35 × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"1.35 × 4를 계산하면 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"540","mis":"M5-2-u4-X01"},{"t":"54","mis":"M5-2-u4-X02"},{"t":"0.54","mis":"M5-2-u4-X02"}],"explanation":["135 × 4 = 540이에요.","1.35는 135의 ⟨1/100⟩배이므로 곱도 540의 ⟨1/100⟩배예요.","1.35 × 4 = 5.4예요."],"variant_rule":{"alt":[{"stem":"0.68 × 7을 계산하면 얼마인가요?","options":[{"t":"4.76","correct":true},{"t":"476","mis":"M5-2-u4-X01"},{"t":"47.6","mis":"M5-2-u4-X02"},{"t":"0.476","mis":"M5-2-u4-X02"}],"explanation":["68 × 7 = 476이에요.","0.68은 68의 ⟨1/100⟩배이므로 곱도 476의 ⟨1/100⟩배예요.","0.68 × 7 = 4.76이에요."]},{"stem":"4.37 × 5를 계산하면 얼마인가요?","options":[{"t":"21.85","correct":true},{"t":"2185","mis":"M5-2-u4-X01"},{"t":"218.5","mis":"M5-2-u4-X02"},{"t":"2.185","mis":"M5-2-u4-X02"}],"explanation":["437 × 5 = 2185예요.","4.37은 437의 ⟨1/100⟩배이므로 곱도 2185의 ⟨1/100⟩배예요.","4.37 × 5 = 21.85예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#2','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',2,'mc','auto','2.95 × 7에서 2.95를 3으로 어림하면 어림한 값은 얼마쯤인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X05']::text[],true,'{"seq":2,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"2.95 × 7에서 2.95를 3으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"21","correct":true},{"t":"210","mis":"M5-2-u4-X02"},{"t":"28","mis":"M5-2-u4-X13"},{"t":"10","mis":"M5-2-u4-X05"}],"explanation":["2.95를 계산하기 쉬운 수 3으로 어림해요.","3 × 7 = 21이에요.","실제 곱 2.95 × 7 = 20.65와 비슷해요 — 소수점 위치를 점검할 수 있어요."],"variant_rule":{"alt":[{"stem":"5.13 × 4에서 5.13을 5로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"20","correct":true},{"t":"200","mis":"M5-2-u4-X02"},{"t":"24","mis":"M5-2-u4-X13"},{"t":"9","mis":"M5-2-u4-X05"}],"explanation":["5.13을 계산하기 쉬운 수 5로 어림해요.","5 × 4 = 20이에요.","실제 곱 5.13 × 4 = 20.52와 비슷해요 — 소수점 위치를 점검할 수 있어요."]},{"stem":"0.98 × 9에서 0.98을 1로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"9","correct":true},{"t":"90","mis":"M5-2-u4-X02"},{"t":"18","mis":"M5-2-u4-X13"},{"t":"10","mis":"M5-2-u4-X05"}],"explanation":["0.98을 계산하기 쉬운 수 1로 어림해요.","1 × 9 = 9예요.","실제 곱 0.98 × 9 = 8.82와 비슷해요 — 소수점 위치를 점검할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#3','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'error','auto','수아는 1.35 × 4를 0.540으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X04']::text[],true,'{"seq":3,"concept":"M5-2-u4-C3","difficulty":3,"kind":"error","stem":"수아는 1.35 × 4를 0.540으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 5.4이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"135 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["1.35는 1보다 크므로 곱은 1 × 4 = 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배이므로 곱은 5.40이에요.","바른 곱은 5.4 — 0.540은 ⟨1/10⟩배 더 작게 쓴 거예요."],"variant_rule":{"alt":[{"stem":"민준은 2.46 × 3을 0.738로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 7.38이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"246 × 3을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["2.46은 2보다 크므로 곱은 2 × 3 = 6보다 커야 해요.","246 × 3 = 738의 ⟨1/100⟩배이므로 곱은 7.38이에요.","바른 곱은 7.38 — 0.738은 ⟨1/10⟩배 더 작게 쓴 거예요."]},{"stem":"가온은 0.75 × 6을 0.450으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 4.5이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"75 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["0.75 × 6을 어림하면 4.8쯤이에요.","75 × 6 = 450의 ⟨1/100⟩배이므로 곱은 4.50이에요.","바른 곱은 4.5 — 0.450은 ⟨1/10⟩배 더 작게 쓴 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#4','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'sa','auto','1.25 × □가 7보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u4-C3","difficulty":3,"kind":"sa","stem":"1.25 × □가 7보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1.25 × 5 = 6.25 < 7이에요.","1.25 × 6 = 7.5 > 7이에요.","그래서 가장 작은 자연수는 6이에요."],"mis":"M5-2-u4-X14","variant_rule":{"alt":[{"stem":"0.36 × □가 3보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["0.36 × 8 = 2.88 < 3이에요.","0.36 × 9 = 3.24 > 3이에요.","그래서 가장 작은 자연수는 9예요."]},{"stem":"2.15 × □가 10보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["2.15 × 4 = 8.6 < 10이에요.","2.15 × 5 = 10.75 > 10이에요.","그래서 가장 작은 자연수는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#5','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'mc','auto','벽 한 칸을 칠하는 데 페인트가 1.25 L 들어요. 벽 4칸을 칠하려면 페인트가 몇 L 필요한가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C3","difficulty":3,"kind":"mc","stem":"벽 한 칸을 칠하는 데 페인트가 1.25 L 들어요. 벽 4칸을 칠하려면 페인트가 몇 L 필요한가요?","options":[{"t":"5 L","correct":true},{"t":"500 L","mis":"M5-2-u4-X01"},{"t":"0.5 L","mis":"M5-2-u4-X02"},{"t":"50 L","mis":"M5-2-u4-X02"}],"explanation":["식은 1.25 × 4예요.","125 × 4 = 500이고 1.25는 125의 ⟨1/100⟩배예요.","곱도 ⟨1/100⟩배 — 1.25 × 4 = 5, 5 L예요."],"variant_rule":{"alt":[{"stem":"망고주스 한 잔에 망고가 0.48 kg 필요해요. 주스 5잔을 만들려면 망고가 몇 kg 필요한가요?","options":[{"t":"2.4 kg","correct":true},{"t":"240 kg","mis":"M5-2-u4-X01"},{"t":"0.24 kg","mis":"M5-2-u4-X02"},{"t":"24 kg","mis":"M5-2-u4-X02"}],"explanation":["식은 0.48 × 5예요.","48 × 5 = 240이고 0.48은 48의 ⟨1/100⟩배예요.","곱도 ⟨1/100⟩배 — 0.48 × 5 = 2.4, 2.4 kg이에요."]},{"stem":"클립 한 개의 무게는 0.75 g이에요. 클립 8개의 무게는 몇 g인가요?","options":[{"t":"6 g","correct":true},{"t":"600 g","mis":"M5-2-u4-X01"},{"t":"0.6 g","mis":"M5-2-u4-X02"},{"t":"60 g","mis":"M5-2-u4-X02"}],"explanation":["식은 0.75 × 8이에요.","75 × 8 = 600이고 0.75는 75의 ⟨1/100⟩배예요.","곱도 ⟨1/100⟩배 — 0.75 × 8 = 6, 6 g이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#6','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'ox','auto','1.35 × 4 = 0.540이에요.',ARRAY['M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C3","difficulty":3,"kind":"ox","stem":"1.35 × 4 = 0.540이에요.","answer":"X","reason_options":[{"t":"1.35는 1보다 커서 곱은 4보다 커야 하고 바른 곱은 5.4이므로","correct":true},{"t":"135 × 4 = 540의 ⟨1/1000⟩배이므로","mis":"M5-2-u4-X02"}],"mis":"M5-2-u4-X02","explanation":["1 × 4 = 4니 곱은 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배는 5.40이에요.","끝자리 0을 생략하면 5.4예요."],"variant_rule":{"alt":[{"stem":"2.59 × 13 = 336.7이에요.","answer":"X","reason_options":[{"t":"259 × 13 = 3367의 ⟨1/100⟩배인 33.67이므로","correct":true},{"t":"259 × 13 = 3367의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["259 × 13 = 3367이에요.","2.59는 259의 ⟨1/100⟩배예요.","2.59 × 13 = 33.67이에요 — 3 × 13 = 39쯤과도 맞아요."]},{"stem":"4.37 × 5는 20보다 조금 커요.","answer":"O","reason_options":[{"t":"4.37을 4로 어림하면 4 × 5 = 20이고 4.37은 4보다 조금 크므로","correct":true},{"t":"4.37에 소수점이 있어 곱이 20보다 작으므로","mis":"M5-2-u4-X07"}],"explanation":["4.37을 4로 어림하면 4 × 5 = 20이에요.","4.37은 4보다 조금 커요.","4.37 × 5 = 21.85 — 20보다 조금 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#7','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',3,'mc','auto','한 변의 길이가 1.25 cm인 정사각형의 둘레는 몇 cm인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X05','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C3","difficulty":3,"kind":"mc","stem":"한 변의 길이가 1.25 cm인 정사각형의 둘레는 몇 cm인가요?","options":[{"t":"5 cm","correct":true},{"t":"500 cm","mis":"M5-2-u4-X01"},{"t":"5.25 cm","mis":"M5-2-u4-X05"},{"t":"0.5 cm","mis":"M5-2-u4-X02"}],"explanation":["정사각형은 4개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 4예요.","1.25 × 4 = 5 — 둘레는 5 cm예요."],"variant_rule":{"alt":[{"stem":"한 변의 길이가 2.35 cm인 정삼각형의 둘레는 몇 cm인가요?","options":[{"t":"7.05 cm","correct":true},{"t":"705 cm","mis":"M5-2-u4-X01"},{"t":"5.35 cm","mis":"M5-2-u4-X05"},{"t":"0.705 cm","mis":"M5-2-u4-X02"}],"explanation":["정삼각형은 3개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 3이에요.","2.35 × 3 = 7.05 — 둘레는 7.05 cm예요."]},{"stem":"한 변의 길이가 0.85 cm인 정육각형의 둘레는 몇 cm인가요?","options":[{"t":"5.1 cm","correct":true},{"t":"510 cm","mis":"M5-2-u4-X01"},{"t":"6.85 cm","mis":"M5-2-u4-X05"},{"t":"0.51 cm","mis":"M5-2-u4-X02"}],"explanation":["정육각형은 6개의 변의 길이가 모두 같아요.","둘레 = 한 변의 길이 × 6이에요.","0.85 × 6 = 5.1 — 둘레는 5.1 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#8','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',4,'mc','auto','망고주스 한 잔에 망고가 0.46 kg 필요해요. 망고 4 kg으로 주스 8잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X14']::text[],true,'{"seq":8,"concept":"M5-2-u4-C3","difficulty":4,"kind":"mc","stem":"망고주스 한 잔에 망고가 0.46 kg 필요해요. 망고 4 kg으로 주스 8잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?","options":[{"t":"만들 수 있다 — 0.5 × 8 = 4 kg쯤이면 된다","correct":true},{"t":"만들 수 없다 — 망고가 4 kg뿐이다","mis":"M5-2-u4-X18"},{"t":"만들 수 없다 — 8잔은 너무 많다","mis":"M5-2-u4-X18"},{"t":"알 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.46을 0.5로 어림해요.","0.5 × 8 = 4(kg)쯤 필요해요.","정확히는 0.46 × 8 = 3.68(kg) — 가진 망고로 충분해요."],"variant_rule":{"alt":[{"stem":"망고주스 한 잔에 망고가 0.32 kg 필요해요. 망고 2 kg으로 주스 6잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?","options":[{"t":"만들 수 있다 — 0.3 × 6 = 1.8 kg쯤이면 된다","correct":true},{"t":"만들 수 없다 — 망고가 2 kg뿐이다","mis":"M5-2-u4-X18"},{"t":"만들 수 없다 — 6잔은 너무 많다","mis":"M5-2-u4-X18"},{"t":"알 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.32를 0.3으로 어림해요.","0.3 × 6 = 1.8(kg)쯤 필요해요.","정확히는 0.32 × 6 = 1.92(kg) — 가진 망고로 충분해요."]},{"stem":"망고주스 한 잔에 망고가 0.56 kg 필요해요. 망고 2 kg으로 주스 4잔을 만들 수 있는지 어림하여 판단하면 어느 것인가요?","options":[{"t":"만들 수 없다 — 0.6 × 4 = 2.4 kg쯤 필요하다","correct":true},{"t":"만들 수 있다 — 4는 2의 2배다","mis":"M5-2-u4-X18"},{"t":"만들 수 있다 — 0.6 × 10 = 6이다","mis":"M5-2-u4-X14"},{"t":"알 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.56을 0.6으로 어림해요.","0.6 × 4 = 2.4(kg)쯤 필요해요.","정확히는 0.56 × 4 = 2.24(kg) — 가진 망고 2 kg보다 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#9','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',4,'sa','auto','0.48 × □가 5보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u4-C3","difficulty":4,"kind":"sa","stem":"0.48 × □가 5보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["0.48 × 10 = 4.8 < 5예요.","0.48 × 11 = 5.28 > 5예요.","그래서 가장 작은 자연수는 11이에요."],"mis":"M5-2-u4-X14","variant_rule":{"alt":[{"stem":"1.36 × □가 9보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1.36 × 6 = 8.16 < 9예요.","1.36 × 7 = 9.52 > 9예요.","그래서 가장 작은 자연수는 7이에요."]},{"stem":"0.27 × □가 2보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["0.27 × 7 = 1.89 < 2예요.","0.27 × 8 = 2.16 > 2예요.","그래서 가장 작은 자연수는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L03_challenge#10','math',5,2,'u4','L03','g5_2_math_u4_L03_challenge','lesson_challenge','M5-2-u4-C3',4,'essay','teacher','어떤 친구가 1.35 × 4를 0.540으로 계산했어요. 어림을 이용해 잘못된 까닭을 쓰고 바르게 계산해 보세요. 끝자리 0은 어떻게 하면 되는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C3","difficulty":4,"kind":"essay","stem":"어떤 친구가 1.35 × 4를 0.540으로 계산했어요. 어림을 이용해 잘못된 까닭을 쓰고 바르게 계산해 보세요. 끝자리 0은 어떻게 하면 되는지도 쓰세요.","answer_guide":{"answer":"예: 1.35는 1보다 크므로 1.35 × 4는 1 × 4 = 4보다 커야 하는데 0.540은 4보다 작아 틀렸다. 135 × 4 = 540이고 1.35는 135의 ⟨1/100⟩배이므로 곱은 540의 ⟨1/100⟩배인 5.40이다. 끝자리 0은 생략하여 5.4로 쓸 수 있다.","scoring_points":["곱이 4보다 커야 한다고 어림으로 설명했는가","135 × 4 = 540의 ⟨1/100⟩배로 5.40을 구했는가","끝자리 0을 생략해 5.4로 쓸 수 있다고 했는가"]},"explanation":["1 × 4 = 4보다 커야 해요.","540의 ⟨1/100⟩배는 5.40이에요.","끝자리 0을 생략해 5.4로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#1','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'sa','auto','2 × 0.8을 그림으로 나타내려고 해요. 2를 똑같이 10칸으로 나누었을 때 몇 칸을 칠해야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C4","difficulty":1,"kind":"sa","stem":"2 × 0.8을 그림으로 나타내려고 해요. 2를 똑같이 10칸으로 나누었을 때 몇 칸을 칠해야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["0.8 = ⟨8/10⟩이에요.","2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이에요.","그래서 10칸 중 8칸을 칠해요 — 곱은 1.6이에요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"5 × 0.3을 그림으로 나타내려고 해요. 5를 똑같이 10칸으로 나누었을 때 몇 칸을 칠해야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.3 = ⟨3/10⟩이에요.","5 × 0.3은 5를 똑같이 10으로 나눈 것 중의 3이에요.","그래서 10칸 중 3칸을 칠해요 — 곱은 1.5예요."]},{"stem":"4 × 0.6을 그림으로 나타내려고 해요. 4를 똑같이 10칸으로 나누었을 때 몇 칸을 칠해야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["0.6 = ⟨6/10⟩이에요.","4 × 0.6은 4를 똑같이 10으로 나눈 것 중의 6이에요.","그래서 10칸 중 6칸을 칠해요 — 곱은 2.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#2','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'mc','auto','6 × 0.9는 6보다 큰가요, 작은가요?',ARRAY['M5-2-u4-X06','M5-2-u4-X07']::text[],true,'{"seq":2,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"6 × 0.9는 6보다 큰가요, 작은가요?","options":[{"t":"작다 — 6의 ⟨9/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 6을 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.9가 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.9를 1과 견주어요.","0.9는 1보다 작으니 곱은 6보다 작아요.","실제로 6 × 0.9 = 5.4예요."],"variant_rule":{"alt":[{"stem":"3 × 2.1은 3보다 큰가요, 작은가요?","options":[{"t":"크다 — 2.1이 1보다 크다","correct":true},{"t":"작다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"},{"t":"같다 — 3을 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"작다 — 2.1에 소수점이 있다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 2.1을 1과 견주어요.","2.1은 1보다 크니 곱은 3보다 커요.","실제로 3 × 2.1 = 6.3이에요."]},{"stem":"8 × 0.4는 8보다 큰가요, 작은가요?","options":[{"t":"작다 — 8의 ⟨4/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 8을 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.4가 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.4를 1과 견주어요.","0.4는 1보다 작으니 곱은 8보다 작아요.","실제로 8 × 0.4 = 3.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#3','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'ox','auto','2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이에요.',ARRAY['M5-2-u4-X06']::text[],true,'{"seq":3,"concept":"M5-2-u4-C4","difficulty":1,"kind":"ox","stem":"2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이에요.","answer":"O","reason_options":[{"t":"0.8 = ⟨8/10⟩이므로","correct":true},{"t":"0.8을 곱하면 2가 8배가 되므로","mis":"M5-2-u4-X06"}],"mis":"M5-2-u4-X06","explanation":["0.8 = ⟨8/10⟩이에요.","2의 ⟨8/10⟩은 2를 10으로 나눈 것 중의 8이에요.","2 × 0.8 = 1.6이에요."],"variant_rule":{"alt":[{"stem":"6 × 0.9는 6보다 커요.","answer":"X","reason_options":[{"t":"0.9가 1보다 작아 곱은 6보다 작으므로","correct":true},{"t":"곱하면 언제나 커지므로","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.9는 1보다 작아요.","그러니 곱은 6보다 작아요.","6 × 0.9 = 5.4예요."]},{"stem":"7 × 1.6과 1.6 × 7의 곱은 같아요.","answer":"O","reason_options":[{"t":"두 수의 자리를 바꾸어 곱해도 곱은 같으므로","correct":true},{"t":"곱하는 수가 소수이면 자리를 바꿀 때 곱이 달라지므로","mis":"M5-2-u4-X18"}],"explanation":["7 × 1.6 = 11.2예요.","1.6 × 7 = 11.2예요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#4','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',1,'mc','auto','2 × 0.8을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03','M5-2-u4-X17']::text[],true,'{"seq":4,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"2 × 0.8을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"2 × ⟨8/10⟩","correct":true},{"t":"2 × ⟨8/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨2/10⟩ × ⟨8/10⟩","mis":"M5-2-u4-X03"},{"t":"2 + ⟨8/10⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.8 = ⟨8/10⟩이에요.","2 × ⟨8/10⟩ = ⟨16/10⟩ = 1.6이에요."],"variant_rule":{"alt":[{"stem":"7 × 0.6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 × ⟨6/10⟩","correct":true},{"t":"7 × ⟨6/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨7/10⟩ × ⟨6/10⟩","mis":"M5-2-u4-X03"},{"t":"7 + ⟨6/10⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.6 = ⟨6/10⟩이에요.","7 × ⟨6/10⟩ = ⟨42/10⟩ = 4.2예요."]},{"stem":"3 × 1.4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3 × ⟨14/10⟩","correct":true},{"t":"3 × ⟨14/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨3/10⟩ × ⟨14/10⟩","mis":"M5-2-u4-X03"},{"t":"3 + ⟨14/10⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.4 = ⟨14/10⟩예요.","3 × ⟨14/10⟩ = ⟨42/10⟩ = 4.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#5','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','2 × 0.8을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"2 × 0.8을 계산하면 얼마인가요?","options":[{"t":"1.6","correct":true},{"t":"16","mis":"M5-2-u4-X01"},{"t":"0.16","mis":"M5-2-u4-X02"},{"t":"160","mis":"M5-2-u4-X02"}],"explanation":["2 × 8 = 16이에요.","0.8은 8의 ⟨1/10⟩배이므로 곱도 16의 ⟨1/10⟩배예요.","2 × 0.8 = 1.6이에요."],"variant_rule":{"alt":[{"stem":"7 × 1.6을 계산하면 얼마인가요?","options":[{"t":"11.2","correct":true},{"t":"112","mis":"M5-2-u4-X01"},{"t":"1.12","mis":"M5-2-u4-X02"},{"t":"1120","mis":"M5-2-u4-X02"}],"explanation":["7 × 16 = 112예요.","1.6은 16의 ⟨1/10⟩배이므로 곱도 112의 ⟨1/10⟩배예요.","7 × 1.6 = 11.2예요."]},{"stem":"9 × 0.4를 계산하면 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"36","mis":"M5-2-u4-X01"},{"t":"0.36","mis":"M5-2-u4-X02"},{"t":"360","mis":"M5-2-u4-X02"}],"explanation":["9 × 4 = 36이에요.","0.4는 4의 ⟨1/10⟩배이므로 곱도 36의 ⟨1/10⟩배예요.","9 × 0.4 = 3.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#6','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','우리 반이 어제 남긴 음식은 2 kg이었는데, 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식은 몇 kg인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"우리 반이 어제 남긴 음식은 2 kg이었는데, 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식은 몇 kg인가요?","options":[{"t":"1.6 kg","correct":true},{"t":"2.8 kg","mis":"M5-2-u4-X17"},{"t":"16 kg","mis":"M5-2-u4-X01"},{"t":"0.16 kg","mis":"M5-2-u4-X02"}],"explanation":["「2의 0.8배」는 2 × 0.8이에요.","2 × 8 = 16의 ⟨1/10⟩배예요.","2 × 0.8 = 1.6 — 1.6 kg이에요."],"variant_rule":{"alt":[{"stem":"작년 쌀 생산량은 35 t이에요. 올해 생산량이 작년의 1.2배라면 올해 생산량은 몇 t인가요?","options":[{"t":"42 t","correct":true},{"t":"36.2 t","mis":"M5-2-u4-X17"},{"t":"420 t","mis":"M5-2-u4-X01"},{"t":"4.2 t","mis":"M5-2-u4-X02"}],"explanation":["「35의 1.2배」는 35 × 1.2예요.","35 × 12 = 420의 ⟨1/10⟩배예요.","35 × 1.2 = 42 — 42 t이에요."]},{"stem":"지난달 화분의 키는 15 cm였어요. 이번 달에는 지난달의 1.4배가 되었어요. 이번 달 화분의 키는 몇 cm인가요?","options":[{"t":"21 cm","correct":true},{"t":"16.4 cm","mis":"M5-2-u4-X17"},{"t":"210 cm","mis":"M5-2-u4-X01"},{"t":"2.1 cm","mis":"M5-2-u4-X02"}],"explanation":["「15의 1.4배」는 15 × 1.4예요.","15 × 14 = 210의 ⟨1/10⟩배예요.","15 × 1.4 = 21 — 21 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#7','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','7 × 1.6과 계산 결과가 같은 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X17','M5-2-u4-X02']::text[],true,'{"seq":7,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"7 × 1.6과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"1.6 × 7","correct":true},{"t":"7 × 16","mis":"M5-2-u4-X01"},{"t":"1.6 + 7","mis":"M5-2-u4-X17"},{"t":"0.16 × 7","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","7 × 1.6 = 11.2예요.","1.6 × 7 = 11.2 — 그래서 같아요."],"variant_rule":{"alt":[{"stem":"8 × 0.3과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"0.3 × 8","correct":true},{"t":"8 × 3","mis":"M5-2-u4-X01"},{"t":"0.3 + 8","mis":"M5-2-u4-X17"},{"t":"0.03 × 8","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","8 × 0.3 = 2.4예요.","0.3 × 8 = 2.4 — 그래서 같아요."]},{"stem":"5 × 2.4와 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"2.4 × 5","correct":true},{"t":"5 × 24","mis":"M5-2-u4-X01"},{"t":"2.4 + 5","mis":"M5-2-u4-X17"},{"t":"0.24 × 5","mis":"M5-2-u4-X02"}],"explanation":["두 수의 자리를 바꾸어 곱해도 곱은 같아요.","5 × 2.4 = 12예요.","2.4 × 5 = 12 — 그래서 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#8','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'ox','auto','3의 2.1배는 6보다 커요.',ARRAY['M5-2-u4-X07']::text[],true,'{"seq":8,"concept":"M5-2-u4-C4","difficulty":2,"kind":"ox","stem":"3의 2.1배는 6보다 커요.","answer":"O","reason_options":[{"t":"2.1은 2보다 커서 곱이 3 × 2 = 6보다 크므로","correct":true},{"t":"2.1에 소수점이 있어 곱이 작아지므로","mis":"M5-2-u4-X07"}],"mis":"M5-2-u4-X07","explanation":["3 × 2 = 6이에요.","2.1은 2보다 조금 커요.","3 × 2.1 = 6.3 — 6보다 커요."],"variant_rule":{"alt":[{"stem":"4 kg의 0.5배는 4.5 kg이에요.","answer":"X","reason_options":[{"t":"몇 배는 곱셈이라 4 × 0.5 = 2(kg)이므로","correct":true},{"t":"몇 배는 두 수를 더하는 것이므로","mis":"M5-2-u4-X17"}],"explanation":["「몇 배」는 곱셈으로 구해요.","4 × 0.5 = 2예요.","4.5 kg은 두 수를 더한 틀린 답이에요."]},{"stem":"7 × 1.6은 7에 7 × 0.6을 더한 것과 같아요.","answer":"O","reason_options":[{"t":"1.6 = 1 + 0.6이라 7의 1배와 7의 0.6배를 더하면 되므로","correct":true},{"t":"1.6은 1과 6으로 가르므로","mis":"M5-2-u4-X01"}],"explanation":["1.6 = 1 + 0.6이에요.","7 × 1 = 7, 7 × 0.6 = 4.2예요.","7 + 4.2 = 11.2 = 7 × 1.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#9','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',2,'mc','auto','어림하여 계산 결과가 5보다 큰 것을 고르세요.',ARRAY['M5-2-u4-X07','M5-2-u4-X06']::text[],true,'{"seq":9,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"어림하여 계산 결과가 5보다 큰 것을 고르세요.","options":[{"t":"5 × 1.2","correct":true},{"t":"5 × 0.9","mis":"M5-2-u4-X07"},{"t":"5 × 0.7","mis":"M5-2-u4-X07"},{"t":"5 × 1","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수가 1보다 크면 곱이 커지고, 1보다 작으면 작아지며, 1이면 그대로예요.","1보다 큰 곱하는 수는 1.2뿐이에요.","5 × 1.2 = 6이에요."],"variant_rule":{"alt":[{"stem":"어림하여 계산 결과가 8보다 큰 것을 고르세요.","options":[{"t":"8 × 1.01","correct":true},{"t":"8 × 1","mis":"M5-2-u4-X06"},{"t":"8 × 0.5","mis":"M5-2-u4-X07"},{"t":"8 × 0.99","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수가 1보다 크면 곱이 커지고, 1보다 작으면 작아지며, 1이면 그대로예요.","1보다 큰 곱하는 수는 1.01뿐이에요.","8 × 1.01 = 8.08이에요."]},{"stem":"어림하여 계산 결과가 6보다 작은 것을 고르세요.","options":[{"t":"6 × 0.8","correct":true},{"t":"6 × 1.3","mis":"M5-2-u4-X07"},{"t":"6 × 1","mis":"M5-2-u4-X06"},{"t":"6 × 2.5","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수가 1보다 크면 곱이 커지고, 1보다 작으면 작아지며, 1이면 그대로예요.","1보다 작은 곱하는 수는 0.8뿐이에요.","6 × 0.8 = 4.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_basic#10','math',5,2,'u4','L04','g5_2_math_u4_L04_basic','lesson_basic','M5-2-u4-C4',3,'mc','auto','높이가 20 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 첫 번째로 꺼낸 인형의 높이는 몇 cm인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":10,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"높이가 20 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 첫 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"16 cm","correct":true},{"t":"19.2 cm","mis":"M5-2-u4-X17"},{"t":"160 cm","mis":"M5-2-u4-X02"},{"t":"12.8 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 20 × 0.8 = 16(cm)예요.","0.8은 1보다 작으니 20 cm보다 작아야 해요.","그래서 16 cm예요."],"variant_rule":{"alt":[{"stem":"높이가 15 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.6배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"5.4 cm","correct":true},{"t":"13.8 cm","mis":"M5-2-u4-X17"},{"t":"54 cm","mis":"M5-2-u4-X02"},{"t":"9 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 15 × 0.6 = 9(cm)예요.","두 번째 인형은 9 × 0.6 = 5.4(cm)예요.","그래서 5.4 cm예요."]},{"stem":"높이가 25 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.8배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"16 cm","correct":true},{"t":"23.4 cm","mis":"M5-2-u4-X17"},{"t":"160 cm","mis":"M5-2-u4-X02"},{"t":"20 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 25 × 0.8 = 20(cm)예요.","두 번째 인형은 20 × 0.8 = 16(cm)예요.","그래서 16 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#1','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',2,'mc','auto','12 × 0.7을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"12 × 0.7을 계산하면 얼마인가요?","options":[{"t":"8.4","correct":true},{"t":"84","mis":"M5-2-u4-X01"},{"t":"0.84","mis":"M5-2-u4-X02"},{"t":"840","mis":"M5-2-u4-X02"}],"explanation":["12 × 7 = 84예요.","0.7은 7의 ⟨1/10⟩배이므로 곱도 84의 ⟨1/10⟩배예요.","12 × 0.7 = 8.4예요."],"variant_rule":{"alt":[{"stem":"23 × 1.8을 계산하면 얼마인가요?","options":[{"t":"41.4","correct":true},{"t":"414","mis":"M5-2-u4-X01"},{"t":"4.14","mis":"M5-2-u4-X02"},{"t":"4140","mis":"M5-2-u4-X02"}],"explanation":["23 × 18 = 414예요.","1.8은 18의 ⟨1/10⟩배이므로 곱도 414의 ⟨1/10⟩배예요.","23 × 1.8 = 41.4예요."]},{"stem":"45 × 0.6을 계산하면 얼마인가요?","options":[{"t":"27","correct":true},{"t":"270","mis":"M5-2-u4-X01"},{"t":"2.7","mis":"M5-2-u4-X02"},{"t":"2700","mis":"M5-2-u4-X02"}],"explanation":["45 × 6 = 270이에요.","0.6은 6의 ⟨1/10⟩배이므로 곱도 270의 ⟨1/10⟩배예요.","45 × 0.6 = 27이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#2','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',2,'mc','auto','7 × 1.6 = 7 × 1 + 7 × □에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":2,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"7 × 1.6 = 7 × 1 + 7 × □에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0.6","correct":true},{"t":"6","mis":"M5-2-u4-X01"},{"t":"0.06","mis":"M5-2-u4-X02"},{"t":"1.6","mis":"M5-2-u4-X18"}],"explanation":["1.6 = 1 + 0.6이에요.","7의 1배와 7의 0.6배를 더하면 돼요.","7 × 1 + 7 × 0.6 = 7 + 4.2 = 11.2예요."],"variant_rule":{"alt":[{"stem":"9 × 2.3 = 9 × 2 + 9 × □에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0.3","correct":true},{"t":"3","mis":"M5-2-u4-X01"},{"t":"0.03","mis":"M5-2-u4-X02"},{"t":"2.3","mis":"M5-2-u4-X18"}],"explanation":["2.3 = 2 + 0.3이에요.","9의 2배와 9의 0.3배를 더하면 돼요.","9 × 2 + 9 × 0.3 = 18 + 2.7 = 20.7이에요."]},{"stem":"12 × 1.5 = 12 × 1 + 12 × □에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0.5","correct":true},{"t":"5","mis":"M5-2-u4-X01"},{"t":"0.05","mis":"M5-2-u4-X02"},{"t":"1.5","mis":"M5-2-u4-X18"}],"explanation":["1.5 = 1 + 0.5예요.","12의 1배와 12의 0.5배를 더하면 돼요.","12 × 1 + 12 × 0.5 = 12 + 6 = 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#3','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'error','auto','수아는 6 × 0.9를 54로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X13','M5-2-u4-X06']::text[],true,'{"seq":3,"concept":"M5-2-u4-C4","difficulty":3,"kind":"error","stem":"수아는 6 × 0.9를 54로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 5.4이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"6 × 9를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"바르게 계산했다 — 곱하면 커진다","mis":"M5-2-u4-X06"}],"explanation":["6 × 9 = 54는 맞아요.","0.9는 9의 ⟨1/10⟩배이므로 곱도 ⟨1/10⟩배예요.","바른 곱은 6 × 0.9 = 5.4예요."],"variant_rule":{"alt":[{"stem":"민준은 8 × 1.4를 112로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 11.2이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"8 × 14를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"바르게 계산했다 — 곱하면 커진다","mis":"M5-2-u4-X06"}],"explanation":["8 × 14 = 112는 맞아요.","1.4는 14의 ⟨1/10⟩배이므로 곱도 ⟨1/10⟩배예요.","바른 곱은 8 × 1.4 = 11.2예요."]},{"stem":"가온은 15 × 0.6을 90으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 9이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"15 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"바르게 계산했다 — 곱하면 커진다","mis":"M5-2-u4-X06"}],"explanation":["15 × 6 = 90은 맞아요.","0.6은 6의 ⟨1/10⟩배이므로 곱도 ⟨1/10⟩배예요.","바른 곱은 15 × 0.6 = 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#4','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'mc','auto','4 × 0.6, 6 × 0.4, 4 × 0.4 가운데 계산 결과가 같은 두 식은 어느 것인가요?',ARRAY['M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":4,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"4 × 0.6, 6 × 0.4, 4 × 0.4 가운데 계산 결과가 같은 두 식은 어느 것인가요?","options":[{"t":"4 × 0.6과 6 × 0.4","correct":true},{"t":"4 × 0.6과 4 × 0.4","mis":"M5-2-u4-X13"},{"t":"6 × 0.4와 4 × 0.4","mis":"M5-2-u4-X13"},{"t":"세 식이 모두 다르다","mis":"M5-2-u4-X18"}],"explanation":["세 식을 각각 계산해요.","4 × 0.6 = 2.4, 6 × 0.4 = 2.4, 4 × 0.4 = 1.6이에요.","곱이 2.4로 같은 것은 4 × 0.6과 6 × 0.4예요."],"variant_rule":{"alt":[{"stem":"3 × 1.2, 2 × 1.8, 9 × 0.3 가운데 계산 결과가 같은 두 식은 어느 것인가요?","options":[{"t":"3 × 1.2와 2 × 1.8","correct":true},{"t":"3 × 1.2와 9 × 0.3","mis":"M5-2-u4-X13"},{"t":"2 × 1.8과 9 × 0.3","mis":"M5-2-u4-X13"},{"t":"세 식이 모두 다르다","mis":"M5-2-u4-X18"}],"explanation":["세 식을 각각 계산해요.","3 × 1.2 = 3.6, 2 × 1.8 = 3.6, 9 × 0.3 = 2.7이에요.","곱이 3.6으로 같은 것은 3 × 1.2와 2 × 1.8이에요."]},{"stem":"5 × 0.8, 8 × 0.5, 2 × 1.5 가운데 계산 결과가 같은 두 식은 어느 것인가요?","options":[{"t":"5 × 0.8과 8 × 0.5","correct":true},{"t":"5 × 0.8과 2 × 1.5","mis":"M5-2-u4-X13"},{"t":"8 × 0.5와 2 × 1.5","mis":"M5-2-u4-X13"},{"t":"세 식이 모두 다르다","mis":"M5-2-u4-X18"}],"explanation":["세 식을 각각 계산해요.","5 × 0.8 = 4, 8 × 0.5 = 4, 2 × 1.5 = 3이에요.","곱이 4로 같은 것은 5 × 0.8과 8 × 0.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#5','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'mc','auto','지난주에 아낀 물은 45 L예요. 이번 주에는 지난주의 1.3배를 아꼈어요. 이번 주에 아낀 물은 몇 L인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"지난주에 아낀 물은 45 L예요. 이번 주에는 지난주의 1.3배를 아꼈어요. 이번 주에 아낀 물은 몇 L인가요?","options":[{"t":"58.5 L","correct":true},{"t":"46.3 L","mis":"M5-2-u4-X17"},{"t":"585 L","mis":"M5-2-u4-X01"},{"t":"5.85 L","mis":"M5-2-u4-X02"}],"explanation":["「45의 1.3배」는 45 × 1.3이에요.","45 × 13 = 585의 ⟨1/10⟩배예요.","45 × 1.3 = 58.5 — 58.5 L예요."],"variant_rule":{"alt":[{"stem":"우리 반이 어제 남긴 음식은 3 kg이었는데, 오늘은 어제의 0.6배가 되었어요. 오늘 남긴 음식은 몇 kg인가요?","options":[{"t":"1.8 kg","correct":true},{"t":"3.6 kg","mis":"M5-2-u4-X17"},{"t":"18 kg","mis":"M5-2-u4-X01"},{"t":"0.18 kg","mis":"M5-2-u4-X02"}],"explanation":["「3의 0.6배」는 3 × 0.6이에요.","3 × 6 = 18의 ⟨1/10⟩배예요.","3 × 0.6 = 1.8 — 1.8 kg이에요."]},{"stem":"작년 쌀 생산량은 28 t이에요. 올해 생산량이 작년의 0.9배라면 올해 생산량은 몇 t인가요?","options":[{"t":"25.2 t","correct":true},{"t":"28.9 t","mis":"M5-2-u4-X17"},{"t":"252 t","mis":"M5-2-u4-X01"},{"t":"2.52 t","mis":"M5-2-u4-X02"}],"explanation":["「28의 0.9배」는 28 × 0.9예요.","28 × 9 = 252의 ⟨1/10⟩배예요.","28 × 0.9 = 25.2 — 25.2 t이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#6','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'ox','auto','6 × 0.9는 6보다 커요.',ARRAY['M5-2-u4-X06']::text[],true,'{"seq":6,"concept":"M5-2-u4-C4","difficulty":3,"kind":"ox","stem":"6 × 0.9는 6보다 커요.","answer":"X","reason_options":[{"t":"0.9가 1보다 작아 곱은 6보다 작으므로","correct":true},{"t":"곱하면 언제나 커지므로","mis":"M5-2-u4-X06"}],"mis":"M5-2-u4-X06","explanation":["곱하는 수 0.9는 1보다 작아요.","그러니 곱은 6보다 작아요.","6 × 0.9 = 5.4예요."],"variant_rule":{"alt":[{"stem":"3의 2.1배는 6보다 커요.","answer":"O","reason_options":[{"t":"2.1은 2보다 커서 곱이 3 × 2 = 6보다 크므로","correct":true},{"t":"2.1에 소수점이 있어 곱이 작아지므로","mis":"M5-2-u4-X07"}],"explanation":["3 × 2 = 6이에요.","2.1은 2보다 조금 커요.","3 × 2.1 = 6.3 — 6보다 커요."]},{"stem":"4 kg의 0.5배는 4.5 kg이에요.","answer":"X","reason_options":[{"t":"몇 배는 곱셈이라 4 × 0.5 = 2(kg)이므로","correct":true},{"t":"몇 배는 두 수를 더하는 것이므로","mis":"M5-2-u4-X17"}],"explanation":["「몇 배」는 곱셈으로 구해요.","4 × 0.5 = 2예요.","4.5 kg은 두 수를 더한 틀린 답이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#7','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',3,'mc','auto','어림하여 계산 결과가 7보다 큰 것을 고르세요.',ARRAY['M5-2-u4-X07','M5-2-u4-X06']::text[],true,'{"seq":7,"concept":"M5-2-u4-C4","difficulty":3,"kind":"mc","stem":"어림하여 계산 결과가 7보다 큰 것을 고르세요.","options":[{"t":"7 × 1.05","correct":true},{"t":"7 × 0.8","mis":"M5-2-u4-X07"},{"t":"7 × 0.95","mis":"M5-2-u4-X07"},{"t":"7 × 1","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수가 1보다 크면 곱이 커지고, 1보다 작으면 작아지며, 1이면 그대로예요.","1보다 큰 곱하는 수는 1.05뿐이에요.","7 × 1.05 = 7.35예요."],"variant_rule":{"alt":[{"stem":"어림하여 계산 결과가 9보다 작은 것을 고르세요.","options":[{"t":"9 × 0.6","correct":true},{"t":"9 × 1.1","mis":"M5-2-u4-X07"},{"t":"9 × 1","mis":"M5-2-u4-X06"},{"t":"9 × 2.3","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수가 1보다 크면 곱이 커지고, 1보다 작으면 작아지며, 1이면 그대로예요.","1보다 작은 곱하는 수는 0.6뿐이에요.","9 × 0.6 = 5.4예요."]},{"stem":"어림하여 계산 결과가 4보다 작은 것을 고르세요.","options":[{"t":"4 × 0.4","correct":true},{"t":"4 × 1.5","mis":"M5-2-u4-X07"},{"t":"4 × 1","mis":"M5-2-u4-X06"},{"t":"4 × 3.2","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수가 1보다 크면 곱이 커지고, 1보다 작으면 작아지며, 1이면 그대로예요.","1보다 작은 곱하는 수는 0.4뿐이에요.","4 × 0.4 = 1.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#8','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',4,'mc','auto','높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.7배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":8,"concept":"M5-2-u4-C4","difficulty":4,"kind":"mc","stem":"높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.7배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"14.7 cm","correct":true},{"t":"28.6 cm","mis":"M5-2-u4-X17"},{"t":"147 cm","mis":"M5-2-u4-X02"},{"t":"21 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 30 × 0.7 = 21(cm)예요.","두 번째 인형은 21 × 0.7 = 14.7(cm)예요.","그래서 14.7 cm예요."],"variant_rule":{"alt":[{"stem":"높이가 40 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.6배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"14.4 cm","correct":true},{"t":"38.8 cm","mis":"M5-2-u4-X17"},{"t":"144 cm","mis":"M5-2-u4-X02"},{"t":"24 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 40 × 0.6 = 24(cm)예요.","두 번째 인형은 24 × 0.6 = 14.4(cm)예요.","그래서 14.4 cm예요."]},{"stem":"높이가 20 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.9배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"16.2 cm","correct":true},{"t":"18.2 cm","mis":"M5-2-u4-X17"},{"t":"162 cm","mis":"M5-2-u4-X02"},{"t":"18 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 20 × 0.9 = 18(cm)예요.","두 번째 인형은 18 × 0.9 = 16.2(cm)예요.","그래서 16.2 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#9','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',4,'mc','auto','6 × 1.5, 3 × 2.5, 5 × 1.8 가운데 계산 결과가 같은 두 식은 어느 것인가요?',ARRAY['M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":9,"concept":"M5-2-u4-C4","difficulty":4,"kind":"mc","stem":"6 × 1.5, 3 × 2.5, 5 × 1.8 가운데 계산 결과가 같은 두 식은 어느 것인가요?","options":[{"t":"6 × 1.5와 5 × 1.8","correct":true},{"t":"6 × 1.5와 3 × 2.5","mis":"M5-2-u4-X13"},{"t":"3 × 2.5와 5 × 1.8","mis":"M5-2-u4-X13"},{"t":"세 식이 모두 다르다","mis":"M5-2-u4-X18"}],"explanation":["세 식을 각각 계산해요.","6 × 1.5 = 9, 3 × 2.5 = 7.5, 5 × 1.8 = 9예요.","곱이 9로 같은 것은 6 × 1.5와 5 × 1.8이에요."],"variant_rule":{"alt":[{"stem":"12 × 0.5, 4 × 1.6, 8 × 0.8 가운데 계산 결과가 같은 두 식은 어느 것인가요?","options":[{"t":"4 × 1.6과 8 × 0.8","correct":true},{"t":"12 × 0.5와 4 × 1.6","mis":"M5-2-u4-X13"},{"t":"12 × 0.5와 8 × 0.8","mis":"M5-2-u4-X13"},{"t":"세 식이 모두 다르다","mis":"M5-2-u4-X18"}],"explanation":["세 식을 각각 계산해요.","12 × 0.5 = 6, 4 × 1.6 = 6.4, 8 × 0.8 = 6.4예요.","곱이 6.4로 같은 것은 4 × 1.6과 8 × 0.8이에요."]},{"stem":"7 × 0.4, 4 × 0.7, 2 × 1.3 가운데 계산 결과가 같은 두 식은 어느 것인가요?","options":[{"t":"7 × 0.4와 4 × 0.7","correct":true},{"t":"7 × 0.4와 2 × 1.3","mis":"M5-2-u4-X13"},{"t":"4 × 0.7과 2 × 1.3","mis":"M5-2-u4-X13"},{"t":"세 식이 모두 다르다","mis":"M5-2-u4-X18"}],"explanation":["세 식을 각각 계산해요.","7 × 0.4 = 2.8, 4 × 0.7 = 2.8, 2 × 1.3 = 2.6이에요.","곱이 2.8로 같은 것은 7 × 0.4와 4 × 0.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L04_challenge#10','math',5,2,'u4','L04','g5_2_math_u4_L04_challenge','lesson_challenge','M5-2-u4-C4',4,'essay','teacher','어제 남긴 음식은 2 kg이었는데 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식이 2 kg보다 많을지 적을지 먼저 판단하고, 2 × 0.8을 「2를 똑같이 10으로 나눈 것」으로 설명하며 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C4","difficulty":4,"kind":"essay","stem":"어제 남긴 음식은 2 kg이었는데 오늘은 어제의 0.8배가 되었어요. 오늘 남긴 음식이 2 kg보다 많을지 적을지 먼저 판단하고, 2 × 0.8을 「2를 똑같이 10으로 나눈 것」으로 설명하며 계산해 보세요.","answer_guide":{"answer":"예: 곱하는 수 0.8이 1보다 작으므로 오늘 남긴 음식은 2 kg보다 적다. 0.8 = ⟨8/10⟩이므로 2 × 0.8은 2를 똑같이 10으로 나눈 것 중의 8이다. 2 × ⟨8/10⟩ = ⟨16/10⟩ = 1.6이므로 오늘 남긴 음식은 1.6 kg이다.","scoring_points":["0.8이 1보다 작아 2 kg보다 적다고 판단했는가","2를 10으로 나눈 것 중의 8로 설명했는가","1.6 kg을 구했는가"]},"explanation":["0.8은 1보다 작아요 — 곱은 2보다 작아요.","2의 ⟨8/10⟩ — 10으로 나눈 것 중의 8이에요.","2 × 0.8 = 1.6(kg)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#1','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'sa','auto','6 × 0.38을 자연수의 곱셈을 이용해 계산하려고 해요. 6 × 38은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C5","difficulty":1,"kind":"sa","stem":"6 × 0.38을 자연수의 곱셈을 이용해 계산하려고 해요. 6 × 38은 얼마인가요? 숫자로 쓰세요.","answer":["228"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","6 × 38 = 228이에요.","그래서 6 × 0.38 = 2.28이에요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"8 × 3.16을 자연수의 곱셈을 이용해 계산하려고 해요. 8 × 316은 얼마인가요? 숫자로 쓰세요.","answer":["2528"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","8 × 316 = 2528이에요.","그래서 8 × 3.16 = 25.28이에요."]},{"stem":"4 × 0.25를 자연수의 곱셈을 이용해 계산하려고 해요. 4 × 25는 얼마인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","4 × 25 = 100이에요.","그래서 4 × 0.25 = 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#2','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'mc','auto','6 × 0.38을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03','M5-2-u4-X17']::text[],true,'{"seq":2,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"6 × 0.38을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"6 × ⟨38/100⟩","correct":true},{"t":"6 × ⟨38/1000⟩","mis":"M5-2-u4-X08"},{"t":"⟨6/10⟩ × ⟨38/100⟩","mis":"M5-2-u4-X03"},{"t":"6 + ⟨38/100⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.38 = ⟨38/100⟩이에요.","6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이에요."],"variant_rule":{"alt":[{"stem":"3 × 0.45를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3 × ⟨45/100⟩","correct":true},{"t":"3 × ⟨45/1000⟩","mis":"M5-2-u4-X08"},{"t":"⟨3/10⟩ × ⟨45/100⟩","mis":"M5-2-u4-X03"},{"t":"3 + ⟨45/100⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.45 = ⟨45/100⟩예요.","3 × ⟨45/100⟩ = ⟨135/100⟩ = 1.35예요."]},{"stem":"7 × 1.25를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"7 × ⟨125/100⟩","correct":true},{"t":"7 × ⟨125/1000⟩","mis":"M5-2-u4-X08"},{"t":"⟨7/10⟩ × ⟨125/100⟩","mis":"M5-2-u4-X03"},{"t":"7 + ⟨125/100⟩","mis":"M5-2-u4-X17"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.25 = ⟨125/100⟩예요.","7 × ⟨125/100⟩ = ⟨875/100⟩ = 8.75예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#3','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'ox','auto','6 × 0.38은 6보다 작아요.',ARRAY['M5-2-u4-X06']::text[],true,'{"seq":3,"concept":"M5-2-u4-C5","difficulty":1,"kind":"ox","stem":"6 × 0.38은 6보다 작아요.","answer":"O","reason_options":[{"t":"0.38은 1보다 작으므로","correct":true},{"t":"곱하면 늘 커지므로","mis":"M5-2-u4-X06"}],"mis":"M5-2-u4-X06","explanation":["곱하는 수 0.38을 1과 견주어요.","1보다 작으니 곱은 6보다 작아요.","6 × 0.38 = 2.28이에요."],"variant_rule":{"alt":[{"stem":"6 × 0.38 = 6 × ⟨38/100⟩로 계산할 수 있어요.","answer":"O","reason_options":[{"t":"0.38 = ⟨38/100⟩이므로","correct":true},{"t":"0.38은 ⟨38/10⟩이므로","mis":"M5-2-u4-X08"}],"explanation":["소수 두 자리 수는 분모가 100인 분수예요.","6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이에요.","그래서 맞아요."]},{"stem":"8 × 3.16과 3.16 × 8의 곱은 같아요.","answer":"O","reason_options":[{"t":"두 수의 자리를 바꾸어 곱해도 곱이 같으므로","correct":true},{"t":"앞의 수가 자연수일 때만 곱을 구할 수 있으므로","mis":"M5-2-u4-X18"}],"explanation":["8 × 3.16 = 25.28이에요.","3.16 × 8 = 25.28이에요.","그래서 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#4','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',1,'mc','auto','8 × 3.16에서 3.16을 3으로 어림하면 어림한 값은 얼마쯤인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X05']::text[],true,'{"seq":4,"concept":"M5-2-u4-C5","difficulty":1,"kind":"mc","stem":"8 × 3.16에서 3.16을 3으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"24","correct":true},{"t":"240","mis":"M5-2-u4-X02"},{"t":"32","mis":"M5-2-u4-X13"},{"t":"11","mis":"M5-2-u4-X05"}],"explanation":["3.16을 계산하기 쉬운 수 3으로 어림해요.","8 × 3 = 24예요.","실제 곱 8 × 3.16 = 25.28과 비슷해요."],"variant_rule":{"alt":[{"stem":"5 × 2.04에서 2.04를 2로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"10","correct":true},{"t":"100","mis":"M5-2-u4-X02"},{"t":"15","mis":"M5-2-u4-X13"},{"t":"7","mis":"M5-2-u4-X05"}],"explanation":["2.04를 계산하기 쉬운 수 2로 어림해요.","5 × 2 = 10이에요.","실제 곱 5 × 2.04 = 10.2와 비슷해요."]},{"stem":"9 × 0.98에서 0.98을 1로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"9","correct":true},{"t":"90","mis":"M5-2-u4-X02"},{"t":"18","mis":"M5-2-u4-X13"},{"t":"10","mis":"M5-2-u4-X05"}],"explanation":["0.98을 계산하기 쉬운 수 1로 어림해요.","9 × 1 = 9예요.","실제 곱 9 × 0.98 = 8.82와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#5','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','6 × 0.38을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"6 × 0.38을 계산하면 얼마인가요?","options":[{"t":"2.28","correct":true},{"t":"228","mis":"M5-2-u4-X01"},{"t":"22.8","mis":"M5-2-u4-X02"},{"t":"0.228","mis":"M5-2-u4-X02"}],"explanation":["6 × 38 = 228이에요.","0.38은 38의 ⟨1/100⟩배이므로 곱도 228의 ⟨1/100⟩배예요.","6 × 0.38 = 2.28이에요."],"variant_rule":{"alt":[{"stem":"8 × 3.16을 계산하면 얼마인가요?","options":[{"t":"25.28","correct":true},{"t":"2528","mis":"M5-2-u4-X01"},{"t":"252.8","mis":"M5-2-u4-X02"},{"t":"2.528","mis":"M5-2-u4-X02"}],"explanation":["8 × 316 = 2528이에요.","3.16은 316의 ⟨1/100⟩배이므로 곱도 2528의 ⟨1/100⟩배예요.","8 × 3.16 = 25.28이에요."]},{"stem":"12 × 0.25를 계산하면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"300","mis":"M5-2-u4-X01"},{"t":"30","mis":"M5-2-u4-X02"},{"t":"0.3","mis":"M5-2-u4-X02"}],"explanation":["12 × 25 = 300이에요.","0.25는 25의 ⟨1/100⟩배이므로 곱도 300의 ⟨1/100⟩배예요.","12 × 0.25 = 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#6','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','화성에서 잰 무게는 지구에서 잰 무게의 0.38배라고 해요. 지구에서 6 kg인 강아지를 화성에서 재면 몇 kg일까요?',ARRAY['M5-2-u4-X02','M5-2-u4-X01','M5-2-u4-X17']::text[],true,'{"seq":6,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"화성에서 잰 무게는 지구에서 잰 무게의 0.38배라고 해요. 지구에서 6 kg인 강아지를 화성에서 재면 몇 kg일까요?","options":[{"t":"2.28 kg","correct":true},{"t":"22.8 kg","mis":"M5-2-u4-X02"},{"t":"228 kg","mis":"M5-2-u4-X01"},{"t":"6.38 kg","mis":"M5-2-u4-X17"}],"explanation":["「6의 0.38배」이므로 식은 6 × 0.38이에요.","6 × 38 = 228의 ⟨1/100⟩배예요.","6 × 0.38 = 2.28 — 2.28 kg이에요 (1보다 작은 수를 곱해 작아졌어요)."],"variant_rule":{"alt":[{"stem":"80 cm 높이에서 떨어뜨린 공이 떨어진 높이의 0.65배만큼 튀어 올랐어요. 튀어 오른 높이는 몇 cm인가요?","options":[{"t":"52 cm","correct":true},{"t":"520 cm","mis":"M5-2-u4-X02"},{"t":"5200 cm","mis":"M5-2-u4-X01"},{"t":"80.65 cm","mis":"M5-2-u4-X17"}],"explanation":["「80의 0.65배」이므로 식은 80 × 0.65예요.","80 × 65 = 5200의 ⟨1/100⟩배예요.","80 × 0.65 = 52 — 52 cm예요 (1보다 작은 수를 곱해 작아졌어요)."]},{"stem":"천을 빨았더니 길이가 처음의 0.95배가 되었어요. 처음 길이가 120 cm인 천은 빨고 나서 몇 cm가 되었나요?","options":[{"t":"114 cm","correct":true},{"t":"1140 cm","mis":"M5-2-u4-X02"},{"t":"11400 cm","mis":"M5-2-u4-X01"},{"t":"120.95 cm","mis":"M5-2-u4-X17"}],"explanation":["「120의 0.95배」이므로 식은 120 × 0.95예요.","120 × 95 = 11400의 ⟨1/100⟩배예요.","120 × 0.95 = 114 — 114 cm예요 (1보다 작은 수를 곱해 작아졌어요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#7','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','가로가 4 m, 세로가 2.35 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":7,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"가로가 4 m, 세로가 2.35 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"9.4 m²","correct":true},{"t":"940 m²","mis":"M5-2-u4-X01"},{"t":"0.94 m²","mis":"M5-2-u4-X02"},{"t":"12.7 m²","mis":"M5-2-u4-X18"}],"explanation":["직사각형의 넓이 = 가로 × 세로예요.","4 × 235 = 940이에요.","4 × 2.35 = 9.4 — 넓이는 9.4 m²예요."],"variant_rule":{"alt":[{"stem":"가로가 7 m, 세로가 1.25 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"8.75 m²","correct":true},{"t":"875 m²","mis":"M5-2-u4-X01"},{"t":"0.875 m²","mis":"M5-2-u4-X02"},{"t":"16.5 m²","mis":"M5-2-u4-X18"}],"explanation":["직사각형의 넓이 = 가로 × 세로예요.","7 × 125 = 875예요.","7 × 1.25 = 8.75 — 넓이는 8.75 m²예요."]},{"stem":"가로가 3 m, 세로가 4.08 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"12.24 m²","correct":true},{"t":"1224 m²","mis":"M5-2-u4-X01"},{"t":"1.224 m²","mis":"M5-2-u4-X02"},{"t":"14.16 m²","mis":"M5-2-u4-X18"}],"explanation":["직사각형의 넓이 = 가로 × 세로예요.","3 × 408 = 1224예요.","3 × 4.08 = 12.24 — 넓이는 12.24 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#8','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'ox','auto','6 × 0.38 = 22.8이에요.',ARRAY['M5-2-u4-X02']::text[],true,'{"seq":8,"concept":"M5-2-u4-C5","difficulty":2,"kind":"ox","stem":"6 × 0.38 = 22.8이에요.","answer":"X","reason_options":[{"t":"6 × 38 = 228의 ⟨1/100⟩배인 2.28이므로","correct":true},{"t":"6 × 38 = 228의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"mis":"M5-2-u4-X02","explanation":["6 × 38 = 228이에요.","0.38은 38의 ⟨1/100⟩배예요.","6 × 0.38 = 2.28 — 22.8은 6보다 커서 틀려요."],"variant_rule":{"alt":[{"stem":"8 × 3.16을 어림하면 24쯤이에요.","answer":"O","reason_options":[{"t":"3.16을 3으로 어림하면 8 × 3 = 24이므로","correct":true},{"t":"3.16을 4로 어림해야 하므로","mis":"M5-2-u4-X14"}],"explanation":["3.16은 3에 가까워요.","8 × 3 = 24예요.","8 × 3.16 = 25.28 — 24와 비슷해요."]},{"stem":"12 × 2.5 = 3이에요.","answer":"X","reason_options":[{"t":"12 × 25 = 300의 ⟨1/10⟩배인 30이므로","correct":true},{"t":"12 × 25 = 300의 ⟨1/100⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["12 × 25 = 300이에요.","2.5는 25의 ⟨1/10⟩배예요.","12 × 2.5 = 30 — 2.5가 1보다 크니 12보다 커야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#9','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',2,'mc','auto','달에서 잰 무게는 지구에서 잰 무게의 0.17배쯤이라고 해요. 지구에서 18 kg인 가방을 달에서 재면 몇 kg쯤일까요?',ARRAY['M5-2-u4-X02','M5-2-u4-X01','M5-2-u4-X17']::text[],true,'{"seq":9,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"달에서 잰 무게는 지구에서 잰 무게의 0.17배쯤이라고 해요. 지구에서 18 kg인 가방을 달에서 재면 몇 kg쯤일까요?","options":[{"t":"3.06 kg","correct":true},{"t":"30.6 kg","mis":"M5-2-u4-X02"},{"t":"306 kg","mis":"M5-2-u4-X01"},{"t":"18.17 kg","mis":"M5-2-u4-X17"}],"explanation":["「18의 0.17배」이므로 식은 18 × 0.17이에요.","18 × 17 = 306의 ⟨1/100⟩배예요.","18 × 0.17 = 3.06 — 3.06 kg이에요 (1보다 작은 수를 곱해 작아졌어요)."],"variant_rule":{"alt":[{"stem":"화성에서 잰 무게는 지구에서 잰 무게의 0.38배라고 해요. 지구에서 25 kg인 강아지를 화성에서 재면 몇 kg일까요?","options":[{"t":"9.5 kg","correct":true},{"t":"95 kg","mis":"M5-2-u4-X02"},{"t":"950 kg","mis":"M5-2-u4-X01"},{"t":"25.38 kg","mis":"M5-2-u4-X17"}],"explanation":["「25의 0.38배」이므로 식은 25 × 0.38이에요.","25 × 38 = 950의 ⟨1/100⟩배예요.","25 × 0.38 = 9.5 — 9.5 kg이에요 (1보다 작은 수를 곱해 작아졌어요)."]},{"stem":"60 cm 높이에서 떨어뜨린 공이 떨어진 높이의 0.45배만큼 튀어 올랐어요. 튀어 오른 높이는 몇 cm인가요?","options":[{"t":"27 cm","correct":true},{"t":"270 cm","mis":"M5-2-u4-X02"},{"t":"2700 cm","mis":"M5-2-u4-X01"},{"t":"60.45 cm","mis":"M5-2-u4-X17"}],"explanation":["「60의 0.45배」이므로 식은 60 × 0.45예요.","60 × 45 = 2700의 ⟨1/100⟩배예요.","60 × 0.45 = 27 — 27 cm예요 (1보다 작은 수를 곱해 작아졌어요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_basic#10','math',5,2,'u4','L05','g5_2_math_u4_L05_basic','lesson_basic','M5-2-u4-C5',3,'mc','auto','수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":10,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"29.58","correct":true},{"t":"2958","mis":"M5-2-u4-X01"},{"t":"295.8","mis":"M5-2-u4-X02"},{"t":"2.958","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 87이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.34가 돼요.","87 × 0.34 = 29.58이에요."],"variant_rule":{"alt":[{"stem":"수 카드 2, 0, 9, 5, 6을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"24","correct":true},{"t":"2400","mis":"M5-2-u4-X01"},{"t":"240","mis":"M5-2-u4-X02"},{"t":"2.4","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 96이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.25가 돼요.","96 × 0.25 = 24예요."]},{"stem":"수 카드 1, 6, 0, 4, 8을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"12.04","correct":true},{"t":"1204","mis":"M5-2-u4-X01"},{"t":"120.4","mis":"M5-2-u4-X02"},{"t":"1.204","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 86이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.14가 돼요.","86 × 0.14 = 12.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#1','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',2,'mc','auto','15 × 0.24를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"15 × 0.24를 계산하면 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"360","mis":"M5-2-u4-X01"},{"t":"36","mis":"M5-2-u4-X02"},{"t":"0.36","mis":"M5-2-u4-X02"}],"explanation":["15 × 24 = 360이에요.","0.24는 24의 ⟨1/100⟩배이므로 곱도 360의 ⟨1/100⟩배예요.","15 × 0.24 = 3.6이에요."],"variant_rule":{"alt":[{"stem":"7 × 2.35를 계산하면 얼마인가요?","options":[{"t":"16.45","correct":true},{"t":"1645","mis":"M5-2-u4-X01"},{"t":"164.5","mis":"M5-2-u4-X02"},{"t":"1.645","mis":"M5-2-u4-X02"}],"explanation":["7 × 235 = 1645예요.","2.35는 235의 ⟨1/100⟩배이므로 곱도 1645의 ⟨1/100⟩배예요.","7 × 2.35 = 16.45예요."]},{"stem":"9 × 1.07을 계산하면 얼마인가요?","options":[{"t":"9.63","correct":true},{"t":"963","mis":"M5-2-u4-X01"},{"t":"96.3","mis":"M5-2-u4-X02"},{"t":"0.963","mis":"M5-2-u4-X02"}],"explanation":["9 × 107 = 963이에요.","1.07은 107의 ⟨1/100⟩배이므로 곱도 963의 ⟨1/100⟩배예요.","9 × 1.07 = 9.63이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#2','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',2,'mc','auto','12 × 0.49에서 0.49를 0.5로 어림하면 어림한 값은 얼마쯤인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X05']::text[],true,'{"seq":2,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"12 × 0.49에서 0.49를 0.5로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"6","correct":true},{"t":"60","mis":"M5-2-u4-X02"},{"t":"18","mis":"M5-2-u4-X13"},{"t":"12.5","mis":"M5-2-u4-X05"}],"explanation":["0.49를 계산하기 쉬운 수 0.5로 어림해요.","12 × 0.5 = 6이에요.","실제 곱 12 × 0.49 = 5.88과 비슷해요."],"variant_rule":{"alt":[{"stem":"7 × 5.92에서 5.92를 6으로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"42","correct":true},{"t":"420","mis":"M5-2-u4-X02"},{"t":"49","mis":"M5-2-u4-X13"},{"t":"13","mis":"M5-2-u4-X05"}],"explanation":["5.92를 계산하기 쉬운 수 6으로 어림해요.","7 × 6 = 42예요.","실제 곱 7 × 5.92 = 41.44와 비슷해요."]},{"stem":"30 × 0.21에서 0.21을 0.2로 어림하면 어림한 값은 얼마쯤인가요?","options":[{"t":"6","correct":true},{"t":"60","mis":"M5-2-u4-X02"},{"t":"36","mis":"M5-2-u4-X13"},{"t":"30.2","mis":"M5-2-u4-X05"}],"explanation":["0.21을 계산하기 쉬운 수 0.2로 어림해요.","30 × 0.2 = 6이에요.","실제 곱 30 × 0.21 = 6.3과 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#3','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'error','auto','수아는 6 × 0.38을 22.8로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X06']::text[],true,'{"seq":3,"concept":"M5-2-u4-C5","difficulty":3,"kind":"error","stem":"수아는 6 × 0.38을 22.8로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 2.28이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"6 × 38을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.38은 38의 ⟨1/100⟩배이므로 곱도 6 × 38 = 228의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 6보다 작아야 하는데 22.8은 6보다 커요.","바른 곱은 2.28이에요."],"variant_rule":{"alt":[{"stem":"민준은 9 × 0.45를 40.5로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 4.05이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"9 × 45를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.45는 45의 ⟨1/100⟩배이므로 곱도 9 × 45 = 405의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 9보다 작아야 하는데 40.5는 9보다 커요.","바른 곱은 4.05예요."]},{"stem":"가온은 5 × 0.84를 42로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 4.2이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"5 × 84를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.84는 84의 ⟨1/100⟩배이므로 곱도 5 × 84 = 420의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 5보다 작아야 하는데 42는 5보다 커요.","바른 곱은 4.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#4','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'mc','auto','1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?',ARRAY['M5-2-u4-X16','M5-2-u4-X18']::text[],true,'{"seq":4,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?","options":[{"t":"390 km","correct":true},{"t":"338 km","mis":"M5-2-u4-X16"},{"t":"260 km","mis":"M5-2-u4-X18"},{"t":"290 km","mis":"M5-2-u4-X16"}],"explanation":["30분은 1시간의 ⟨30/60⟩이라 0.5시간이에요.","1시간 30분 = 1.5시간이에요.","260 × 1.5 = 390 — 390 km예요."],"variant_rule":{"alt":[{"stem":"1시간에 180 km를 가는 고속 열차가 같은 빠르기로 2시간 15분 동안 가는 거리는 몇 km인가요?","options":[{"t":"405 km","correct":true},{"t":"387 km","mis":"M5-2-u4-X16"},{"t":"360 km","mis":"M5-2-u4-X18"},{"t":"375 km","mis":"M5-2-u4-X16"}],"explanation":["15분은 1시간의 ⟨15/60⟩라 0.25시간이에요.","2시간 15분 = 2.25시간이에요.","180 × 2.25 = 405 — 405 km예요."]},{"stem":"1시간에 240 km를 가는 고속 열차가 같은 빠르기로 1시간 45분 동안 가는 거리는 몇 km인가요?","options":[{"t":"420 km","correct":true},{"t":"348 km","mis":"M5-2-u4-X16"},{"t":"240 km","mis":"M5-2-u4-X18"},{"t":"285 km","mis":"M5-2-u4-X16"}],"explanation":["45분은 1시간의 ⟨45/60⟩라 0.75시간이에요.","1시간 45분 = 1.75시간이에요.","240 × 1.75 = 420 — 420 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#5','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'mc','auto','가로가 12 m, 세로가 3.75 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":5,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"가로가 12 m, 세로가 3.75 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"45 m²","correct":true},{"t":"4500 m²","mis":"M5-2-u4-X01"},{"t":"4.5 m²","mis":"M5-2-u4-X02"},{"t":"31.5 m²","mis":"M5-2-u4-X18"}],"explanation":["직사각형의 넓이 = 가로 × 세로예요.","12 × 375 = 4500이에요.","12 × 3.75 = 45 — 넓이는 45 m²예요."],"variant_rule":{"alt":[{"stem":"가로가 8 m, 세로가 6.25 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"50 m²","correct":true},{"t":"5000 m²","mis":"M5-2-u4-X01"},{"t":"5 m²","mis":"M5-2-u4-X02"},{"t":"28.5 m²","mis":"M5-2-u4-X18"}],"explanation":["직사각형의 넓이 = 가로 × 세로예요.","8 × 625 = 5000이에요.","8 × 6.25 = 50 — 넓이는 50 m²예요."]},{"stem":"가로가 15 m, 세로가 2.08 m인 직사각형 모양 텃밭의 넓이는 몇 m²인가요?","options":[{"t":"31.2 m²","correct":true},{"t":"3120 m²","mis":"M5-2-u4-X01"},{"t":"3.12 m²","mis":"M5-2-u4-X02"},{"t":"34.16 m²","mis":"M5-2-u4-X18"}],"explanation":["직사각형의 넓이 = 가로 × 세로예요.","15 × 208 = 3120이에요.","15 × 2.08 = 31.2 — 넓이는 31.2 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#6','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'ox','auto','6 × 0.38 = 22.8이에요.',ARRAY['M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C5","difficulty":3,"kind":"ox","stem":"6 × 0.38 = 22.8이에요.","answer":"X","reason_options":[{"t":"6 × 38 = 228의 ⟨1/100⟩배인 2.28이므로","correct":true},{"t":"6 × 38 = 228의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X02"}],"mis":"M5-2-u4-X02","explanation":["6 × 38 = 228이에요.","0.38은 38의 ⟨1/100⟩배예요.","6 × 0.38 = 2.28 — 22.8은 6보다 커서 틀려요."],"variant_rule":{"alt":[{"stem":"12 × 2.5 = 3이에요.","answer":"X","reason_options":[{"t":"12 × 25 = 300의 ⟨1/10⟩배인 30이므로","correct":true},{"t":"12 × 25 = 300의 ⟨1/100⟩배이므로","mis":"M5-2-u4-X02"}],"explanation":["12 × 25 = 300이에요.","2.5는 25의 ⟨1/10⟩배예요.","12 × 2.5 = 30 — 2.5가 1보다 크니 12보다 커야 해요."]},{"stem":"8 × 3.16을 어림하면 24쯤이에요.","answer":"O","reason_options":[{"t":"3.16을 3으로 어림하면 8 × 3 = 24이므로","correct":true},{"t":"3.16을 4로 어림해야 하므로","mis":"M5-2-u4-X14"}],"explanation":["3.16은 3에 가까워요.","8 × 3 = 24예요.","8 × 3.16 = 25.28 — 24와 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#7','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',3,'mc','auto','천을 빨았더니 길이가 처음의 0.96배가 되었어요. 처음 길이가 85 cm인 천은 빨고 나서 몇 cm가 되었나요?',ARRAY['M5-2-u4-X02','M5-2-u4-X01','M5-2-u4-X17']::text[],true,'{"seq":7,"concept":"M5-2-u4-C5","difficulty":3,"kind":"mc","stem":"천을 빨았더니 길이가 처음의 0.96배가 되었어요. 처음 길이가 85 cm인 천은 빨고 나서 몇 cm가 되었나요?","options":[{"t":"81.6 cm","correct":true},{"t":"816 cm","mis":"M5-2-u4-X02"},{"t":"8160 cm","mis":"M5-2-u4-X01"},{"t":"85.96 cm","mis":"M5-2-u4-X17"}],"explanation":["「85의 0.96배」이므로 식은 85 × 0.96이에요.","85 × 96 = 8160의 ⟨1/100⟩배예요.","85 × 0.96 = 81.6 — 81.6 cm예요 (1보다 작은 수를 곱해 작아졌어요)."],"variant_rule":{"alt":[{"stem":"달에서 잰 무게는 지구에서 잰 무게의 0.17배쯤이라고 해요. 지구에서 42 kg인 가방을 달에서 재면 몇 kg쯤일까요?","options":[{"t":"7.14 kg","correct":true},{"t":"71.4 kg","mis":"M5-2-u4-X02"},{"t":"714 kg","mis":"M5-2-u4-X01"},{"t":"42.17 kg","mis":"M5-2-u4-X17"}],"explanation":["「42의 0.17배」이므로 식은 42 × 0.17이에요.","42 × 17 = 714의 ⟨1/100⟩배예요.","42 × 0.17 = 7.14 — 7.14 kg이에요 (1보다 작은 수를 곱해 작아졌어요)."]},{"stem":"150 cm 높이에서 떨어뜨린 공이 떨어진 높이의 0.64배만큼 튀어 올랐어요. 튀어 오른 높이는 몇 cm인가요?","options":[{"t":"96 cm","correct":true},{"t":"960 cm","mis":"M5-2-u4-X02"},{"t":"9600 cm","mis":"M5-2-u4-X01"},{"t":"150.64 cm","mis":"M5-2-u4-X17"}],"explanation":["「150의 0.64배」이므로 식은 150 × 0.64예요.","150 × 64 = 9600의 ⟨1/100⟩배예요.","150 × 0.64 = 96 — 96 cm예요 (1보다 작은 수를 곱해 작아졌어요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#8','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',4,'mc','auto','수 카드 0, 7, 5, 9, 1을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":8,"concept":"M5-2-u4-C5","difficulty":4,"kind":"mc","stem":"수 카드 0, 7, 5, 9, 1을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"14.55","correct":true},{"t":"1455","mis":"M5-2-u4-X01"},{"t":"145.5","mis":"M5-2-u4-X02"},{"t":"1.455","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 97이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.15가 돼요.","97 × 0.15 = 14.55예요."],"variant_rule":{"alt":[{"stem":"수 카드 7, 0, 1, 8, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"11.31","correct":true},{"t":"1131","mis":"M5-2-u4-X01"},{"t":"113.1","mis":"M5-2-u4-X02"},{"t":"1.131","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 87이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.13이 돼요.","87 × 0.13 = 11.31이에요."]},{"stem":"수 카드 4, 0, 6, 2, 9를 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들었어요. 두 수의 곱은 얼마인가요?","options":[{"t":"23.04","correct":true},{"t":"2304","mis":"M5-2-u4-X01"},{"t":"230.4","mis":"M5-2-u4-X02"},{"t":"2.304","mis":"M5-2-u4-X02"}],"explanation":["가장 큰 두 자리 수는 큰 카드 둘로 96이에요.","남은 카드 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.24가 돼요.","96 × 0.24 = 23.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#9','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',4,'sa','auto','0.75 × □가 8보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u4-C5","difficulty":4,"kind":"sa","stem":"0.75 × □가 8보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["0.75 × 10 = 7.5 < 8이에요.","0.75 × 11 = 8.25 > 8이에요.","그래서 가장 작은 자연수는 11이에요."],"mis":"M5-2-u4-X14","variant_rule":{"alt":[{"stem":"1.15 × □가 9보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["1.15 × 7 = 8.05 < 9예요.","1.15 × 8 = 9.2 > 9예요.","그래서 가장 작은 자연수는 8이에요."]},{"stem":"0.64 × □가 5보다 클 때, □ 안에 들어갈 수 있는 가장 작은 자연수는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["0.64 × 7 = 4.48 < 5예요.","0.64 × 8 = 5.12 > 5예요.","그래서 가장 작은 자연수는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L05_challenge#10','math',5,2,'u4','L05','g5_2_math_u4_L05_challenge','lesson_challenge','M5-2-u4-C5',4,'essay','teacher','화성에서 잰 무게는 지구에서 잰 무게의 0.38배예요. 지구에서 6 kg인 강아지의 화성 몸무게를 친구가 22.8 kg이라고 했어요. 친구의 답이 틀린 까닭을 쓰고, 두 가지 방법으로 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C5","difficulty":4,"kind":"essay","stem":"화성에서 잰 무게는 지구에서 잰 무게의 0.38배예요. 지구에서 6 kg인 강아지의 화성 몸무게를 친구가 22.8 kg이라고 했어요. 친구의 답이 틀린 까닭을 쓰고, 두 가지 방법으로 바르게 계산해 보세요.","answer_guide":{"answer":"예: 0.38은 1보다 작으므로 곱은 6보다 작아야 하는데 22.8은 6보다 커서 틀렸다. 분수로 — 6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이다. 자연수로 — 6 × 38 = 228이고 0.38은 38의 ⟨1/100⟩배이므로 곱은 228의 ⟨1/100⟩배인 2.28이다. 화성에서 강아지의 몸무게는 2.28 kg이다.","scoring_points":["곱이 6보다 작아야 해서 22.8은 틀렸다고 했는가","분수의 곱셈으로 2.28을 구했는가","자연수의 곱셈과 ⟨1/100⟩배로 2.28을 구했는가"]},"explanation":["0.38 < 1이니 곱은 6보다 작아요.","6 × ⟨38/100⟩ = ⟨228/100⟩ = 2.28이에요.","228의 ⟨1/100⟩배 — 2.28 kg이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#1','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',1,'mc','auto','넓이가 1인 정사각형 모눈종이를 가로·세로 10칸씩 똑같이 나누었어요. 한 칸의 넓이는 얼마인가요?',ARRAY['M5-2-u4-X09','M5-2-u4-X12','M5-2-u4-X18']::text[],true,'{"seq":1,"concept":"M5-2-u4-C6","difficulty":1,"kind":"mc","stem":"넓이가 1인 정사각형 모눈종이를 가로·세로 10칸씩 똑같이 나누었어요. 한 칸의 넓이는 얼마인가요?","options":[{"t":"0.01","correct":true},{"t":"0.1","mis":"M5-2-u4-X09"},{"t":"0.001","mis":"M5-2-u4-X12"},{"t":"10","mis":"M5-2-u4-X18"}],"explanation":["가로·세로 10칸씩이면 모두 10 × 10 = 100칸이에요.","한 칸은 100칸 중의 1칸 — ⟨1/100⟩이에요.","⟨1/100⟩ = 0.01이에요."],"variant_rule":{"alt":[{"stem":"넓이가 1 m²인 정사각형 벽를 가로·세로 10칸씩 똑같이 나누었어요. 한 칸의 넓이는 얼마인가요?","options":[{"t":"0.01 m²","correct":true},{"t":"0.1 m²","mis":"M5-2-u4-X09"},{"t":"0.001 m²","mis":"M5-2-u4-X12"},{"t":"10 m²","mis":"M5-2-u4-X18"}],"explanation":["가로·세로 10칸씩이면 모두 10 × 10 = 100칸이에요.","한 칸은 100칸 중의 1칸 — ⟨1/100⟩이에요.","⟨1/100⟩ = 0.01이에요."]},{"stem":"넓이가 1인 정사각형 색종이를 가로·세로 10칸씩 똑같이 나누었어요. 한 칸의 넓이는 얼마인가요?","options":[{"t":"0.01","correct":true},{"t":"0.1","mis":"M5-2-u4-X09"},{"t":"0.001","mis":"M5-2-u4-X12"},{"t":"10","mis":"M5-2-u4-X18"}],"explanation":["가로·세로 10칸씩이면 모두 10 × 10 = 100칸이에요.","한 칸은 100칸 중의 1칸 — ⟨1/100⟩이에요.","⟨1/100⟩ = 0.01이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#2','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',1,'sa','auto','전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.6 × 0.9를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C6","difficulty":1,"kind":"sa","stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.6 × 0.9를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["가로 6칸, 세로 9칸을 칠해요.","칠한 칸은 6 × 9 = 54칸이에요.","한 칸이 0.01이므로 0.6 × 0.9 = 0.54예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.3 × 0.7을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["가로 3칸, 세로 7칸을 칠해요.","칠한 칸은 3 × 7 = 21칸이에요.","한 칸이 0.01이므로 0.3 × 0.7 = 0.21이에요."]},{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.5 × 0.8을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["가로 5칸, 세로 8칸을 칠해요.","칠한 칸은 5 × 8 = 40칸이에요.","한 칸이 0.01이므로 0.5 × 0.8 = 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#3','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',1,'ox','auto','0.6 × 0.9 = 0.54예요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":3,"concept":"M5-2-u4-C6","difficulty":1,"kind":"ox","stem":"0.6 × 0.9 = 0.54예요.","answer":"O","reason_options":[{"t":"0.01인 칸이 6 × 9 = 54칸이므로","correct":true},{"t":"6 × 9 = 54의 ⟨1/10⟩배이므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["모눈 한 칸은 0.01이에요.","가로 6칸, 세로 9칸 — 6 × 9 = 54칸이에요.","0.6 × 0.9 = 0.54 — 맞아요."],"variant_rule":{"alt":[{"stem":"1을 100칸으로 나눈 모눈에서 한 칸은 0.01이에요.","answer":"O","reason_options":[{"t":"100칸 중의 1칸은 ⟨1/100⟩ = 0.01이므로","correct":true},{"t":"한 줄이 10칸이니 한 칸은 0.1이므로","mis":"M5-2-u4-X09"}],"explanation":["전체 1을 100칸으로 나누었어요.","한 칸은 ⟨1/100⟩이에요.","⟨1/100⟩ = 0.01 — 맞아요."]},{"stem":"0.6 × 0.8은 0.6보다 작아요.","answer":"O","reason_options":[{"t":"곱하는 수 0.8이 1보다 작으므로","correct":true},{"t":"두 수를 곱하면 늘 커지므로","mis":"M5-2-u4-X06"}],"explanation":["0.8은 1보다 작아요.","그러니 곱은 0.6보다 작아요.","0.6 × 0.8 = 0.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#4','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',1,'sa','auto','0.6 × 0.9의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u4-C6","difficulty":1,"kind":"sa","stem":"0.6 × 0.9의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["0.6은 0.1이 6개, 0.9는 0.1이 9개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 6 × 9 = 54개예요.","0.6 × 0.9 = 0.54예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"0.2 × 0.6의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["0.2는 0.1이 2개, 0.6은 0.1이 6개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 2 × 6 = 12개예요.","0.2 × 0.6 = 0.12예요."]},{"stem":"0.7 × 0.5의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["0.7은 0.1이 7개, 0.5는 0.1이 5개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 7 × 5 = 35개예요.","0.7 × 0.5 = 0.35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#5','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','0.6 × 0.9를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"0.6 × 0.9를 계산하면 얼마인가요?","options":[{"t":"0.54","correct":true},{"t":"5.4","mis":"M5-2-u4-X03"},{"t":"54","mis":"M5-2-u4-X01"},{"t":"0.054","mis":"M5-2-u4-X02"}],"explanation":["6 × 9 = 54예요.","0.6은 6의 ⟨1/10⟩배, 0.9는 9의 ⟨1/10⟩배예요.","그래서 곱은 54의 ⟨1/100⟩배인 0.54예요."],"variant_rule":{"alt":[{"stem":"1.9 × 3.6을 계산하면 얼마인가요?","options":[{"t":"6.84","correct":true},{"t":"68.4","mis":"M5-2-u4-X03"},{"t":"684","mis":"M5-2-u4-X01"},{"t":"0.684","mis":"M5-2-u4-X02"}],"explanation":["19 × 36 = 684예요.","1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","그래서 곱은 684의 ⟨1/100⟩배인 6.84예요."]},{"stem":"2.4 × 1.5를 계산하면 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"36","mis":"M5-2-u4-X03"},{"t":"360","mis":"M5-2-u4-X01"},{"t":"0.36","mis":"M5-2-u4-X02"}],"explanation":["24 × 15 = 360이에요.","2.4는 24의 ⟨1/10⟩배, 1.5는 15의 ⟨1/10⟩배예요.","그래서 곱은 360의 ⟨1/100⟩배인 3.60이에요 — 끝자리 0은 생략해 3.6으로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#6','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','1.9 × 3.6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08']::text[],true,'{"seq":6,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"1.9 × 3.6을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨19/10⟩ × ⟨36/10⟩","correct":true},{"t":"⟨19/100⟩ × ⟨36/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/19⟩ × ⟨36/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨19/10⟩ × ⟨36/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.9 = ⟨19/10⟩ · 3.6 = ⟨36/10⟩이에요.","⟨19/10⟩ × ⟨36/10⟩ = ⟨684/100⟩ = 6.84예요."],"variant_rule":{"alt":[{"stem":"0.6 × 0.9를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨6/10⟩ × ⟨9/10⟩","correct":true},{"t":"⟨6/100⟩ × ⟨9/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/6⟩ × ⟨9/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨6/10⟩ × ⟨9/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.6 = ⟨6/10⟩ · 0.9 = ⟨9/10⟩예요.","⟨6/10⟩ × ⟨9/10⟩ = ⟨54/100⟩ = 0.54예요."]},{"stem":"2.3 × 1.4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨23/10⟩ × ⟨14/10⟩","correct":true},{"t":"⟨23/100⟩ × ⟨14/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/23⟩ × ⟨14/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨23/10⟩ × ⟨14/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","2.3 = ⟨23/10⟩ · 1.4 = ⟨14/10⟩예요.","⟨23/10⟩ × ⟨14/10⟩ = ⟨322/100⟩ = 3.22예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#7','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','도서관 벽화를 나누어 그려요. 내가 맡은 곳은 가로 0.6 m, 세로 0.9 m인 직사각형이에요. 그려야 할 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X18','M5-2-u4-X01']::text[],true,'{"seq":7,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"도서관 벽화를 나누어 그려요. 내가 맡은 곳은 가로 0.6 m, 세로 0.9 m인 직사각형이에요. 그려야 할 넓이는 몇 m²인가요?","options":[{"t":"0.54 m²","correct":true},{"t":"5.4 m²","mis":"M5-2-u4-X03"},{"t":"3 m²","mis":"M5-2-u4-X18"},{"t":"54 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 0.6 × 0.9예요.","6 × 9 = 54이고 두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배예요.","0.6 × 0.9 = 0.54 — 0.54 m²예요."],"variant_rule":{"alt":[{"stem":"배드민턴 경기장은 가로 6.1 m, 세로 13.4 m인 직사각형이에요. 경기장의 넓이는 몇 m²인가요?","options":[{"t":"81.74 m²","correct":true},{"t":"817.4 m²","mis":"M5-2-u4-X03"},{"t":"39 m²","mis":"M5-2-u4-X18"},{"t":"8174 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 6.1 × 13.4예요.","61 × 134 = 8174이고 두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배예요.","6.1 × 13.4 = 81.74 — 81.74 m²예요."]},{"stem":"가로 2.5 m, 세로 1.8 m인 직사각형 모양 돗자리의 넓이는 몇 m²인가요?","options":[{"t":"4.5 m²","correct":true},{"t":"45 m²","mis":"M5-2-u4-X03"},{"t":"8.6 m²","mis":"M5-2-u4-X18"},{"t":"450 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 2.5 × 1.8이에요.","25 × 18 = 450이고 두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배예요.","2.5 × 1.8 = 4.5 — 4.5 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#8','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'ox','auto','1.9 × 3.6 = 68.4예요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":8,"concept":"M5-2-u4-C6","difficulty":2,"kind":"ox","stem":"1.9 × 3.6 = 68.4예요.","answer":"X","reason_options":[{"t":"두 수가 모두 ⟨1/10⟩배라 곱은 684의 ⟨1/100⟩배인 6.84이므로","correct":true},{"t":"한 수만 ⟨1/10⟩배로 보면 되므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["19 × 36 = 684예요.","곱은 ⟨1/10⟩ × ⟨1/10⟩ = ⟨1/100⟩배예요.","1.9 × 3.6 = 6.84예요."],"variant_rule":{"alt":[{"stem":"1.9 × 3.6 = ⟨19/10⟩ × ⟨36/10⟩ = ⟨684/100⟩예요.","answer":"O","reason_options":[{"t":"분모끼리 10 × 10 = 100, 분자끼리 19 × 36 = 684이므로","correct":true},{"t":"분모는 곱하지 않고 10 그대로 두므로","mis":"M5-2-u4-X08"}],"explanation":["1.9 = ⟨19/10⟩, 3.6 = ⟨36/10⟩이에요.","분모끼리·분자끼리 곱해요.","⟨684/100⟩ = 6.84예요."]},{"stem":"0.2 × 1.5의 곱은 0.1이 3개예요.","answer":"O","reason_options":[{"t":"0.2 × 1.5 = 0.3이므로","correct":true},{"t":"2 × 15 = 30이므로 0.1이 30개이므로","mis":"M5-2-u4-X09"}],"explanation":["2 × 15 = 30이에요.","곱은 30의 ⟨1/100⟩배 — 0.30 = 0.3이에요.","0.3은 0.1이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#9','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',2,'mc','auto','빨간색 끈은 1.5 m예요. 노란색 끈이 빨간색 끈의 1.2배라면 노란색 끈은 몇 m인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X03','M5-2-u4-X01']::text[],true,'{"seq":9,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"빨간색 끈은 1.5 m예요. 노란색 끈이 빨간색 끈의 1.2배라면 노란색 끈은 몇 m인가요?","options":[{"t":"1.8 m","correct":true},{"t":"2.7 m","mis":"M5-2-u4-X17"},{"t":"18 m","mis":"M5-2-u4-X03"},{"t":"180 m","mis":"M5-2-u4-X01"}],"explanation":["「1.5의 1.2배」는 곱셈 1.5 × 1.2예요.","15 × 12 = 180이에요.","1.5 × 1.2 = 1.8 — 노란색 끈은 1.8 m예요."],"variant_rule":{"alt":[{"stem":"빨간색 끈은 2.4 m예요. 노란색 끈이 빨간색 끈의 0.5배라면 노란색 끈은 몇 m인가요?","options":[{"t":"1.2 m","correct":true},{"t":"2.9 m","mis":"M5-2-u4-X17"},{"t":"12 m","mis":"M5-2-u4-X03"},{"t":"120 m","mis":"M5-2-u4-X01"}],"explanation":["「2.4의 0.5배」는 곱셈 2.4 × 0.5예요.","24 × 5 = 120이에요.","2.4 × 0.5 = 1.2 — 노란색 끈은 1.2 m예요."]},{"stem":"빨간색 끈은 3.6 m예요. 노란색 끈이 빨간색 끈의 1.5배라면 노란색 끈은 몇 m인가요?","options":[{"t":"5.4 m","correct":true},{"t":"5.1 m","mis":"M5-2-u4-X17"},{"t":"54 m","mis":"M5-2-u4-X03"},{"t":"540 m","mis":"M5-2-u4-X01"}],"explanation":["「3.6의 1.5배」는 곱셈 3.6 × 1.5예요.","36 × 15 = 540이에요.","3.6 × 1.5 = 5.4 — 노란색 끈은 5.4 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_basic#10','math',5,2,'u4','L06','g5_2_math_u4_L06_basic','lesson_basic','M5-2-u4-C6',3,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u4-C6","difficulty":3,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.6 × 0.9","r":"0.54"},{"l":"1.9 × 3.6","r":"6.84"},{"l":"0.2 × 0.4","r":"0.08"}],"mis":"M5-2-u4-X03","explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","0.6 × 0.9 = 0.54 · 1.9 × 3.6 = 6.84예요.","0.2 × 0.4 = 0.08이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.3 × 0.7","r":"0.21"},{"l":"2.4 × 1.5","r":"3.6"},{"l":"1.2 × 1.2","r":"1.44"}],"explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","0.3 × 0.7 = 0.21 · 2.4 × 1.5 = 3.6이에요.","1.2 × 1.2 = 1.44예요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.8 × 0.5","r":"0.4"},{"l":"3.1 × 2.2","r":"6.82"},{"l":"0.7 × 0.7","r":"0.49"}],"explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","0.8 × 0.5 = 0.4 · 3.1 × 2.2 = 6.82예요.","0.7 × 0.7 = 0.49예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#1','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',2,'mc','auto','3.4 × 2.7을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"3.4 × 2.7을 계산하면 얼마인가요?","options":[{"t":"9.18","correct":true},{"t":"91.8","mis":"M5-2-u4-X03"},{"t":"918","mis":"M5-2-u4-X01"},{"t":"0.918","mis":"M5-2-u4-X02"}],"explanation":["34 × 27 = 918이에요.","3.4는 34의 ⟨1/10⟩배, 2.7은 27의 ⟨1/10⟩배예요.","그래서 곱은 918의 ⟨1/100⟩배인 9.18이에요."],"variant_rule":{"alt":[{"stem":"0.8 × 0.7을 계산하면 얼마인가요?","options":[{"t":"0.56","correct":true},{"t":"5.6","mis":"M5-2-u4-X03"},{"t":"56","mis":"M5-2-u4-X01"},{"t":"0.056","mis":"M5-2-u4-X02"}],"explanation":["8 × 7 = 56이에요.","0.8은 8의 ⟨1/10⟩배, 0.7은 7의 ⟨1/10⟩배예요.","그래서 곱은 56의 ⟨1/100⟩배인 0.56이에요."]},{"stem":"5.2 × 1.3을 계산하면 얼마인가요?","options":[{"t":"6.76","correct":true},{"t":"67.6","mis":"M5-2-u4-X03"},{"t":"676","mis":"M5-2-u4-X01"},{"t":"0.676","mis":"M5-2-u4-X02"}],"explanation":["52 × 13 = 676이에요.","5.2는 52의 ⟨1/10⟩배, 1.3은 13의 ⟨1/10⟩배예요.","그래서 곱은 676의 ⟨1/100⟩배인 6.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#2','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',2,'sa','auto','1.9 × 3.6을 자연수의 곱셈을 이용해 계산하려고 해요. 19 × 36은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C6","difficulty":2,"kind":"sa","stem":"1.9 × 3.6을 자연수의 곱셈을 이용해 계산하려고 해요. 19 × 36은 얼마인가요? 숫자로 쓰세요.","answer":["684"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","19 × 36 = 684예요.","그래서 1.9 × 3.6 = 6.84예요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"2.8 × 4.5를 자연수의 곱셈을 이용해 계산하려고 해요. 28 × 45는 얼마인가요? 숫자로 쓰세요.","answer":["1260"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","28 × 45 = 1260이에요.","그래서 2.8 × 4.5 = 12.6이에요."]},{"stem":"6.4 × 0.9를 자연수의 곱셈을 이용해 계산하려고 해요. 64 × 9는 얼마인가요? 숫자로 쓰세요.","answer":["576"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","64 × 9 = 576이에요.","그래서 6.4 × 0.9 = 5.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#3','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'error','auto','수아는 1.9 × 3.6을 68.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":3,"concept":"M5-2-u4-C6","difficulty":3,"kind":"error","stem":"수아는 1.9 × 3.6을 68.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 684의 ⟨1/100⟩배인 6.84이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"19 × 36을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","곱은 19 × 36 = 684의 ⟨1/100⟩배여야 해요.","바른 곱은 6.84예요."],"variant_rule":{"alt":[{"stem":"민준은 75.9 × 0.6을 455.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 4554의 ⟨1/100⟩배인 45.54이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"759 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["75.9는 759의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배예요.","곱은 759 × 6 = 4554의 ⟨1/100⟩배여야 해요.","바른 곱은 45.54예요."]},{"stem":"가온은 2.6 × 4.3을 111.8로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 1118의 ⟨1/100⟩배인 11.18이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"26 × 43을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["2.6은 26의 ⟨1/10⟩배, 4.3은 43의 ⟨1/10⟩배예요.","곱은 26 × 43 = 1118의 ⟨1/100⟩배여야 해요.","바른 곱은 11.18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#4','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'mc','auto','배드민턴 경기장은 가로 6.1 m, 세로 13.4 m인 직사각형이에요. 경기장의 넓이는 몇 m²인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X18','M5-2-u4-X01']::text[],true,'{"seq":4,"concept":"M5-2-u4-C6","difficulty":3,"kind":"mc","stem":"배드민턴 경기장은 가로 6.1 m, 세로 13.4 m인 직사각형이에요. 경기장의 넓이는 몇 m²인가요?","options":[{"t":"81.74 m²","correct":true},{"t":"817.4 m²","mis":"M5-2-u4-X03"},{"t":"39 m²","mis":"M5-2-u4-X18"},{"t":"8174 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 6.1 × 13.4예요.","61 × 134 = 8174이고 두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배예요.","6.1 × 13.4 = 81.74 — 81.74 m²예요."],"variant_rule":{"alt":[{"stem":"가로 1.8 m, 세로 0.9 m인 직사각형 모양 게시판의 넓이는 몇 m²인가요?","options":[{"t":"1.62 m²","correct":true},{"t":"16.2 m²","mis":"M5-2-u4-X03"},{"t":"5.4 m²","mis":"M5-2-u4-X18"},{"t":"162 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 1.8 × 0.9예요.","18 × 9 = 162이고 두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배예요.","1.8 × 0.9 = 1.62 — 1.62 m²예요."]},{"stem":"도서관 벽화를 나누어 그려요. 내가 맡은 곳은 가로 2.5 m, 세로 1.6 m인 직사각형이에요. 그려야 할 넓이는 몇 m²인가요?","options":[{"t":"4 m²","correct":true},{"t":"40 m²","mis":"M5-2-u4-X03"},{"t":"8.2 m²","mis":"M5-2-u4-X18"},{"t":"400 m²","mis":"M5-2-u4-X01"}],"explanation":["직사각형의 넓이 = 가로 × 세로이므로 2.5 × 1.6이에요.","25 × 16 = 400이고 두 수가 모두 ⟨1/10⟩배라 곱은 ⟨1/100⟩배예요.","2.5 × 1.6 = 4 — 4 m²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#5','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'mc','auto','빨간색 끈은 2.4 m예요. 노란색 끈이 빨간색 끈의 1.5배라면 노란색 끈은 몇 m인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X03','M5-2-u4-X01']::text[],true,'{"seq":5,"concept":"M5-2-u4-C6","difficulty":3,"kind":"mc","stem":"빨간색 끈은 2.4 m예요. 노란색 끈이 빨간색 끈의 1.5배라면 노란색 끈은 몇 m인가요?","options":[{"t":"3.6 m","correct":true},{"t":"3.9 m","mis":"M5-2-u4-X17"},{"t":"36 m","mis":"M5-2-u4-X03"},{"t":"360 m","mis":"M5-2-u4-X01"}],"explanation":["「2.4의 1.5배」는 곱셈 2.4 × 1.5예요.","24 × 15 = 360이에요.","2.4 × 1.5 = 3.6 — 노란색 끈은 3.6 m예요."],"variant_rule":{"alt":[{"stem":"빨간색 끈은 1.8 m예요. 노란색 끈이 빨간색 끈의 0.6배라면 노란색 끈은 몇 m인가요?","options":[{"t":"1.08 m","correct":true},{"t":"2.4 m","mis":"M5-2-u4-X17"},{"t":"10.8 m","mis":"M5-2-u4-X03"},{"t":"108 m","mis":"M5-2-u4-X01"}],"explanation":["「1.8의 0.6배」는 곱셈 1.8 × 0.6이에요.","18 × 6 = 108이에요.","1.8 × 0.6 = 1.08 — 노란색 끈은 1.08 m예요."]},{"stem":"빨간색 끈은 3.5 m예요. 노란색 끈이 빨간색 끈의 2.4배라면 노란색 끈은 몇 m인가요?","options":[{"t":"8.4 m","correct":true},{"t":"5.9 m","mis":"M5-2-u4-X17"},{"t":"84 m","mis":"M5-2-u4-X03"},{"t":"840 m","mis":"M5-2-u4-X01"}],"explanation":["「3.5의 2.4배」는 곱셈 3.5 × 2.4예요.","35 × 24 = 840이에요.","3.5 × 2.4 = 8.4 — 노란색 끈은 8.4 m예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#6','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'ox','auto','1.9 × 3.6 = 68.4예요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":6,"concept":"M5-2-u4-C6","difficulty":3,"kind":"ox","stem":"1.9 × 3.6 = 68.4예요.","answer":"X","reason_options":[{"t":"두 수가 모두 ⟨1/10⟩배라 곱은 684의 ⟨1/100⟩배인 6.84이므로","correct":true},{"t":"한 수만 ⟨1/10⟩배로 보면 되므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["19 × 36 = 684예요.","곱은 ⟨1/10⟩ × ⟨1/10⟩ = ⟨1/100⟩배예요.","1.9 × 3.6 = 6.84예요."],"variant_rule":{"alt":[{"stem":"0.6 × 0.8은 0.6보다 작아요.","answer":"O","reason_options":[{"t":"곱하는 수 0.8이 1보다 작으므로","correct":true},{"t":"두 수를 곱하면 늘 커지므로","mis":"M5-2-u4-X06"}],"explanation":["0.8은 1보다 작아요.","그러니 곱은 0.6보다 작아요.","0.6 × 0.8 = 0.48이에요."]},{"stem":"0.2 × 1.5의 곱은 0.1이 3개예요.","answer":"O","reason_options":[{"t":"0.2 × 1.5 = 0.3이므로","correct":true},{"t":"2 × 15 = 30이므로 0.1이 30개이므로","mis":"M5-2-u4-X09"}],"explanation":["2 × 15 = 30이에요.","곱은 30의 ⟨1/100⟩배 — 0.30 = 0.3이에요.","0.3은 0.1이 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#7','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',3,'sa','auto','1.2 × 0.3의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C6","difficulty":3,"kind":"sa","stem":"1.2 × 0.3의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["1.2는 0.1이 12개, 0.3은 0.1이 3개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 12 × 3 = 36개예요.","1.2 × 0.3 = 0.36이에요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"0.4 × 1.5의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["0.4는 0.1이 4개, 1.5는 0.1이 15개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 4 × 15 = 60개예요.","0.4 × 1.5 = 0.6이에요."]},{"stem":"2.1 × 0.8의 곱은 0.01이 몇 개인가요? 숫자로 쓰세요.","answer":["168"],"explanation":["2.1은 0.1이 21개, 0.8은 0.1이 8개예요.","0.1 × 0.1 = 0.01이므로 곱은 0.01이 21 × 8 = 168개예요.","2.1 × 0.8 = 1.68이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#8','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',4,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u4-C6","difficulty":4,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"1.3 × 0.6","r":"0.78"},{"l":"0.9 × 2.4","r":"2.16"},{"l":"3.2 × 1.5","r":"4.8"}],"mis":"M5-2-u4-X03","explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","1.3 × 0.6 = 0.78 · 0.9 × 2.4 = 2.16이에요.","3.2 × 1.5 = 4.8이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"2.5 × 0.4","r":"1"},{"l":"1.4 × 1.4","r":"1.96"},{"l":"0.6 × 3.5","r":"2.1"}],"explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","2.5 × 0.4 = 1 · 1.4 × 1.4 = 1.96이에요.","0.6 × 3.5 = 2.1이에요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"4.5 × 0.2","r":"0.9"},{"l":"1.1 × 1.9","r":"2.09"},{"l":"2.7 × 0.3","r":"0.81"}],"explanation":["자연수끼리 곱한 뒤 두 수의 소수점 아래 자릿수의 합만큼 소수점을 찍어요.","4.5 × 0.2 = 0.9 · 1.1 × 1.9 = 2.09예요.","2.7 × 0.3 = 0.81이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#9','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',4,'error','auto','여울은 4.5 × 2.8을 126으로 계산했어요. 바르게 고친 설명은 어느 것인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":9,"concept":"M5-2-u4-C6","difficulty":4,"kind":"error","stem":"여울은 4.5 × 2.8을 126으로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 1260의 ⟨1/100⟩배인 12.6이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"45 × 28을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["4.5는 45의 ⟨1/10⟩배, 2.8은 28의 ⟨1/10⟩배예요.","곱은 45 × 28 = 1260의 ⟨1/100⟩배여야 해요.","바른 곱은 12.6이에요."],"variant_rule":{"alt":[{"stem":"수아는 0.6 × 0.5를 3으로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 30의 ⟨1/100⟩배인 0.3이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"6 × 5를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["0.6은 6의 ⟨1/10⟩배, 0.5는 5의 ⟨1/10⟩배예요.","곱은 6 × 5 = 30의 ⟨1/100⟩배여야 해요.","바른 곱은 0.3이에요."]},{"stem":"민준은 3.2 × 1.4를 44.8로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 448의 ⟨1/100⟩배인 4.48이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"32 × 14를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["3.2는 32의 ⟨1/10⟩배, 1.4는 14의 ⟨1/10⟩배예요.","곱은 32 × 14 = 448의 ⟨1/100⟩배여야 해요.","바른 곱은 4.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L06_challenge#10','math',5,2,'u4','L06','g5_2_math_u4_L06_challenge','lesson_challenge','M5-2-u4-C6',4,'essay','teacher','가로 0.6 m, 세로 0.9 m인 직사각형 벽화의 넓이를 넓이 모델(넓이 1인 정사각형을 가로·세로 10칸씩 나눈 모눈)로 설명하며 구해 보세요. 한 칸의 넓이와 칠한 칸 수를 꼭 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C6","difficulty":4,"kind":"essay","stem":"가로 0.6 m, 세로 0.9 m인 직사각형 벽화의 넓이를 넓이 모델(넓이 1인 정사각형을 가로·세로 10칸씩 나눈 모눈)로 설명하며 구해 보세요. 한 칸의 넓이와 칠한 칸 수를 꼭 쓰세요.","answer_guide":{"answer":"예: 넓이 1인 정사각형을 가로·세로 10칸씩 나누면 모두 100칸이고 한 칸의 넓이는 ⟨1/100⟩ = 0.01이다. 가로 6칸, 세로 9칸을 칠하면 6 × 9 = 54칸이다. 0.01이 54칸이므로 0.6 × 0.9 = 0.54이고 벽화의 넓이는 0.54 m²이다.","scoring_points":["한 칸의 넓이가 0.01임을 밝혔는가","칠한 칸 6 × 9 = 54칸을 구했는가","0.54 m²를 구했는가"]},"explanation":["100칸 중의 1칸 — 한 칸은 0.01이에요.","6 × 9 = 54칸이에요.","0.6 × 0.9 = 0.54(m²)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#1','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'sa','auto','0.47 × 0.3의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C7","difficulty":1,"kind":"sa","stem":"0.47 × 0.3의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.47은 소수 두 자리, 0.3은 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 0.47 × 0.3 = 0.141 — 소수 세 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"2.5 × 1.89의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["2.5는 소수 한 자리, 1.89는 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 2 = 3이에요.","실제로 2.5 × 1.89 = 4.725 — 소수 세 자리 수예요."]},{"stem":"1.23 × 0.4의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1.23은 소수 두 자리, 0.4는 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 1.23 × 0.4 = 0.492 — 소수 세 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#2','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'mc','auto','0.47 × 0.3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08']::text[],true,'{"seq":2,"concept":"M5-2-u4-C7","difficulty":1,"kind":"mc","stem":"0.47 × 0.3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨47/100⟩ × ⟨3/10⟩","correct":true},{"t":"⟨47/1000⟩ × ⟨3/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/47⟩ × ⟨3/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨47/100⟩ × ⟨3/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.47 = ⟨47/100⟩ · 0.3 = ⟨3/10⟩이에요.","⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩ = 0.141이에요."],"variant_rule":{"alt":[{"stem":"1.23 × 0.4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨123/100⟩ × ⟨4/10⟩","correct":true},{"t":"⟨123/1000⟩ × ⟨4/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/123⟩ × ⟨4/10⟩","mis":"M5-2-u4-X08"},{"t":"⟨123/100⟩ × ⟨4/100⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.23 = ⟨123/100⟩ · 0.4 = ⟨4/10⟩예요.","⟨123/100⟩ × ⟨4/10⟩ = ⟨492/1000⟩ = 0.492예요."]},{"stem":"2.5 × 0.18을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨25/10⟩ × ⟨18/100⟩","correct":true},{"t":"⟨25/100⟩ × ⟨18/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨1/25⟩ × ⟨18/100⟩","mis":"M5-2-u4-X08"},{"t":"⟨25/10⟩ × ⟨18/1000⟩","mis":"M5-2-u4-X08"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","2.5 = ⟨25/10⟩ · 0.18 = ⟨18/100⟩이에요.","⟨25/10⟩ × ⟨18/100⟩ = ⟨450/1000⟩ = 0.45예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#3','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'ox','auto','0.47 × 0.3 = 0.141이에요.',ARRAY['M5-2-u4-X03']::text[],true,'{"seq":3,"concept":"M5-2-u4-C7","difficulty":1,"kind":"ox","stem":"0.47 × 0.3 = 0.141이에요.","answer":"O","reason_options":[{"t":"47 × 3 = 141의 ⟨1/1000⟩배이므로","correct":true},{"t":"47 × 3 = 141의 ⟨1/100⟩배이므로","mis":"M5-2-u4-X03"}],"mis":"M5-2-u4-X03","explanation":["47 × 3 = 141이에요.","0.47은 ⟨1/100⟩배, 0.3은 ⟨1/10⟩배 — 곱은 ⟨1/1000⟩배예요.","0.47 × 0.3 = 0.141 — 맞아요."],"variant_rule":{"alt":[{"stem":"0.32 × 4.5의 곱 1.440은 1.44로 쓸 수 있어요.","answer":"O","reason_options":[{"t":"끝자리 0은 생략해도 크기가 같으므로","correct":true},{"t":"끝자리 0을 생략하면 0.144가 되므로","mis":"M5-2-u4-X04"}],"explanation":["32 × 45 = 1440이에요.","곱은 ⟨1/1000⟩배인 1.440이에요.","끝자리 0을 생략해 1.44로 써요."]},{"stem":"2.5 × 1.89의 곱은 소수 세 자리 수예요.","answer":"O","reason_options":[{"t":"소수 한 자리 수와 두 자리 수의 곱이라 1 + 2 = 3자리이므로","correct":true},{"t":"자릿수가 더 많은 1.89만 세어 두 자리이므로","mis":"M5-2-u4-X03"}],"explanation":["2.5는 한 자리, 1.89는 두 자리예요.","1 + 2 = 3 — 소수 세 자리 수예요.","2.5 × 1.89 = 4.725예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#4','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',1,'sa','auto','0.47 × 0.3을 자연수의 곱셈을 이용해 계산하려고 해요. 47 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u4-C7","difficulty":1,"kind":"sa","stem":"0.47 × 0.3을 자연수의 곱셈을 이용해 계산하려고 해요. 47 × 3은 얼마인가요? 숫자로 쓰세요.","answer":["141"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","47 × 3 = 141이에요.","그래서 0.47 × 0.3 = 0.141이에요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"3.2 × 0.71을 자연수의 곱셈을 이용해 계산하려고 해요. 32 × 71은 얼마인가요? 숫자로 쓰세요.","answer":["2272"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","32 × 71 = 2272예요.","그래서 3.2 × 0.71 = 2.272예요."]},{"stem":"25.2 × 1.4를 자연수의 곱셈을 이용해 계산하려고 해요. 252 × 14는 얼마인가요? 숫자로 쓰세요.","answer":["3528"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","252 × 14 = 3528이에요.","그래서 25.2 × 1.4 = 35.28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#5','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','0.47 × 0.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"0.47 × 0.3을 계산하면 얼마인가요?","options":[{"t":"0.141","correct":true},{"t":"1.41","mis":"M5-2-u4-X03"},{"t":"141","mis":"M5-2-u4-X01"},{"t":"0.0141","mis":"M5-2-u4-X02"}],"explanation":["47 × 3 = 141이에요.","0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배예요.","그래서 곱은 141의 ⟨1/1000⟩배인 0.141이에요."],"variant_rule":{"alt":[{"stem":"3.2 × 0.71을 계산하면 얼마인가요?","options":[{"t":"2.272","correct":true},{"t":"22.72","mis":"M5-2-u4-X03"},{"t":"2272","mis":"M5-2-u4-X01"},{"t":"0.2272","mis":"M5-2-u4-X02"}],"explanation":["32 × 71 = 2272예요.","3.2는 32의 ⟨1/10⟩배, 0.71은 71의 ⟨1/100⟩배예요.","그래서 곱은 2272의 ⟨1/1000⟩배인 2.272예요."]},{"stem":"1.23 × 0.4를 계산하면 얼마인가요?","options":[{"t":"0.492","correct":true},{"t":"4.92","mis":"M5-2-u4-X03"},{"t":"492","mis":"M5-2-u4-X01"},{"t":"0.0492","mis":"M5-2-u4-X02"}],"explanation":["123 × 4 = 492예요.","1.23은 123의 ⟨1/100⟩배, 0.4는 4의 ⟨1/10⟩배예요.","그래서 곱은 492의 ⟨1/1000⟩배인 0.492예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#6','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','해달 인형의 길이는 0.47 m예요. 물고기 인형의 길이는 해달 인형의 0.3배라고 해요. 물고기 인형의 길이는 몇 m인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X17','M5-2-u4-X01']::text[],true,'{"seq":6,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"해달 인형의 길이는 0.47 m예요. 물고기 인형의 길이는 해달 인형의 0.3배라고 해요. 물고기 인형의 길이는 몇 m인가요?","options":[{"t":"0.141 m","correct":true},{"t":"1.41 m","mis":"M5-2-u4-X03"},{"t":"0.77 m","mis":"M5-2-u4-X17"},{"t":"141 m","mis":"M5-2-u4-X01"}],"explanation":["「0.47의 0.3배」는 0.47 × 0.3이에요.","47 × 3 = 141이고 곱은 그 ⟨1/1000⟩배예요.","0.47 × 0.3 = 0.141 — 0.141 m예요."],"variant_rule":{"alt":[{"stem":"사과즙을 1.6 L 만들고, 배즙은 사과즙의 0.75배만큼 만들었어요. 배즙은 몇 L인가요?","options":[{"t":"1.2 L","correct":true},{"t":"12 L","mis":"M5-2-u4-X03"},{"t":"2.35 L","mis":"M5-2-u4-X17"},{"t":"1200 L","mis":"M5-2-u4-X01"}],"explanation":["「1.6의 0.75배」는 1.6 × 0.75예요.","16 × 75 = 1200이고 곱은 그 ⟨1/1000⟩배예요.","1.6 × 0.75 = 1.2 — 1.2 L예요."]},{"stem":"작년에 병뚜껑을 2.45 kg 모았어요. 올해는 작년의 1.2배를 모았다면 올해 모은 병뚜껑은 몇 kg인가요?","options":[{"t":"2.94 kg","correct":true},{"t":"29.4 kg","mis":"M5-2-u4-X03"},{"t":"3.65 kg","mis":"M5-2-u4-X17"},{"t":"2940 kg","mis":"M5-2-u4-X01"}],"explanation":["「2.45의 1.2배」는 2.45 × 1.2예요.","245 × 12 = 2940이고 곱은 그 ⟨1/1000⟩배예요.","2.45 × 1.2 = 2.94 — 2.94 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#7','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','계산하지 않고 어림하여 알맞은 말을 고르세요. 3.2 × 0.71은 2.1보다 …',ARRAY['M5-2-u4-X07','M5-2-u4-X14']::text[],true,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 3.2 × 0.71은 2.1보다 …","options":[{"t":"크다 — 3.2는 3보다, 0.71은 0.7보다 크다","correct":true},{"t":"작다 — 0.71이 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 3 × 0.7 = 2.1이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["3 × 0.7 = 2.1을 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 2.1보다 커요.","실제로 3.2 × 0.71 = 2.272예요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 0.89 × 0.6은 0.54보다 …","options":[{"t":"작다 — 0.89는 0.9보다 작다","correct":true},{"t":"크다 — 두 수를 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 0.9 × 0.6 = 0.54이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.9 × 0.6 = 0.54를 기준으로 삼아요.","0.89가 0.9보다 작으니 곱도 0.54보다 작아요.","실제로 0.89 × 0.6 = 0.534예요."]},{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 5.1 × 1.12는 5보다 …","options":[{"t":"크다 — 5.1은 5보다, 1.12는 1보다 크다","correct":true},{"t":"작다 — 1.12가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 5 × 1 = 5이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["5 × 1 = 5를 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 5보다 커요.","실제로 5.1 × 1.12 = 5.712예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#8','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'ox','auto','3.2 × 0.71은 2.1보다 커요.',ARRAY['M5-2-u4-X07']::text[],true,'{"seq":8,"concept":"M5-2-u4-C7","difficulty":2,"kind":"ox","stem":"3.2 × 0.71은 2.1보다 커요.","answer":"O","reason_options":[{"t":"3 × 0.7 = 2.1이고 두 수가 모두 조금씩 더 크므로","correct":true},{"t":"0.71이 1보다 작아 곱이 2.1보다 작으므로","mis":"M5-2-u4-X07"}],"mis":"M5-2-u4-X07","explanation":["3 × 0.7 = 2.1이 기준이에요.","3.2 > 3이고 0.71 > 0.7이에요.","3.2 × 0.71 = 2.272 — 2.1보다 커요."],"variant_rule":{"alt":[{"stem":"0.89 × 0.6은 0.54보다 커요.","answer":"X","reason_options":[{"t":"0.9 × 0.6 = 0.54이고 0.89는 0.9보다 작으므로","correct":true},{"t":"0.89가 0.6보다 크므로","mis":"M5-2-u4-X07"}],"explanation":["0.9 × 0.6 = 0.54가 기준이에요.","0.89 < 0.9예요.","0.89 × 0.6 = 0.534 — 0.54보다 작아요."]},{"stem":"5.1 × 1.12는 5쯤이에요.","answer":"O","reason_options":[{"t":"5.1을 5로, 1.12를 1로 어림하면 5 × 1 = 5이므로","correct":true},{"t":"5.1 × 1.12는 51 × 112와 같으므로","mis":"M5-2-u4-X01"}],"explanation":["5.1은 5에, 1.12는 1에 가까워요.","5 × 1 = 5예요.","5.1 × 1.12 = 5.712 — 5쯤이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#9','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',2,'mc','auto','0.32 × 4.5를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X04']::text[],true,'{"seq":9,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"0.32 × 4.5를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"1.44","correct":true},{"t":"0.144","mis":"M5-2-u4-X02"},{"t":"14.4","mis":"M5-2-u4-X02"},{"t":"1.4","mis":"M5-2-u4-X04"}],"explanation":["32 × 45 = 1440이에요.","두 수의 소수점 아래 자릿수의 합은 3 — 곱은 1.440이에요.","끝자리 0을 생략하면 1.44예요."],"variant_rule":{"alt":[{"stem":"1.25 × 0.4를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"0.5","correct":true},{"t":"0.05","mis":"M5-2-u4-X02"},{"t":"5","mis":"M5-2-u4-X02"},{"t":"50","mis":"M5-2-u4-X02"}],"explanation":["125 × 4 = 500이에요.","두 수의 소수점 아래 자릿수의 합은 3 — 곱은 0.500이에요.","끝자리 0을 생략하면 0.5예요."]},{"stem":"2.4 × 0.35를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"0.84","correct":true},{"t":"0.084","mis":"M5-2-u4-X02"},{"t":"8.4","mis":"M5-2-u4-X02"},{"t":"0.8","mis":"M5-2-u4-X04"}],"explanation":["24 × 35 = 840이에요.","두 수의 소수점 아래 자릿수의 합은 3 — 곱은 0.840이에요.","끝자리 0을 생략하면 0.84예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_basic#10','math',5,2,'u4','L07','g5_2_math_u4_L07_basic','lesson_basic','M5-2-u4-C7',3,'sa','auto','□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 1.□ × 4가 6보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u4-C7","difficulty":3,"kind":"sa","stem":"□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 1.□ × 4가 6보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["1.4 × 4 = 5.6 < 6이에요.","1.5 × 4 = 6 — 6보다 작지 않아요.","□는 1, 2, 3, 4 — 모두 4개예요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 4.□ × 3이 14보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["4.6 × 3 = 13.8 < 14예요.","4.7 × 3 = 14.1 > 14예요.","□는 1, 2, 3, 4, 5, 6 — 모두 6개예요."]},{"stem":"□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 3.□ × 5가 17보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["3.3 × 5 = 16.5 < 17이에요.","3.4 × 5 = 17 — 17보다 작지 않아요.","□는 1, 2, 3 — 모두 3개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#1','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',2,'mc','auto','25.2 × 1.4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"25.2 × 1.4를 계산하면 얼마인가요?","options":[{"t":"35.28","correct":true},{"t":"352.8","mis":"M5-2-u4-X03"},{"t":"3528","mis":"M5-2-u4-X01"},{"t":"3.528","mis":"M5-2-u4-X02"}],"explanation":["252 × 14 = 3528이에요.","25.2는 252의 ⟨1/10⟩배, 1.4는 14의 ⟨1/10⟩배예요.","그래서 곱은 3528의 ⟨1/100⟩배인 35.28이에요."],"variant_rule":{"alt":[{"stem":"0.68 × 2.5를 계산하면 얼마인가요?","options":[{"t":"1.7","correct":true},{"t":"17","mis":"M5-2-u4-X03"},{"t":"1700","mis":"M5-2-u4-X01"},{"t":"0.17","mis":"M5-2-u4-X02"}],"explanation":["68 × 25 = 1700이에요.","0.68은 68의 ⟨1/100⟩배, 2.5는 25의 ⟨1/10⟩배예요.","그래서 곱은 1700의 ⟨1/1000⟩배인 1.700이에요 — 끝자리 0은 생략해 1.7로 써요."]},{"stem":"4.6 × 0.25를 계산하면 얼마인가요?","options":[{"t":"1.15","correct":true},{"t":"11.5","mis":"M5-2-u4-X03"},{"t":"1150","mis":"M5-2-u4-X01"},{"t":"0.115","mis":"M5-2-u4-X02"}],"explanation":["46 × 25 = 1150이에요.","4.6은 46의 ⟨1/10⟩배, 0.25는 25의 ⟨1/100⟩배예요.","그래서 곱은 1150의 ⟨1/1000⟩배인 1.150이에요 — 끝자리 0은 생략해 1.15로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#2','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',2,'sa','auto','3.7 × 0.25의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C7","difficulty":2,"kind":"sa","stem":"3.7 × 0.25의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["3.7은 소수 한 자리, 0.25는 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 2 = 3이에요.","실제로 3.7 × 0.25 = 0.925 — 소수 세 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"0.47 × 0.83의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.47은 소수 두 자리, 0.83은 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 2 = 4예요.","실제로 0.47 × 0.83 = 0.3901 — 소수 네 자리 수예요."]},{"stem":"3.7 × 2.9의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["3.7은 소수 한 자리, 2.9는 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 1 = 2예요.","실제로 3.7 × 2.9 = 10.73 — 소수 두 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#3','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'error','auto','수아는 0.47 × 0.3을 1.41로 계산했어요. 바르게 고친 설명은 어느 것인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":3,"concept":"M5-2-u4-C7","difficulty":3,"kind":"error","stem":"수아는 0.47 × 0.3을 1.41로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 141의 ⟨1/1000⟩배인 0.141이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"47 × 3을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배예요.","곱은 47 × 3 = 141의 ⟨1/1000⟩배여야 해요.","바른 곱은 0.141이에요."],"variant_rule":{"alt":[{"stem":"민준은 3.25 × 1.4를 45.5로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 4550의 ⟨1/1000⟩배인 4.55이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"325 × 14를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["3.25는 325의 ⟨1/100⟩배, 1.4는 14의 ⟨1/10⟩배예요.","곱은 325 × 14 = 4550의 ⟨1/1000⟩배여야 해요.","바른 곱은 4.55예요."]},{"stem":"가온은 0.68 × 2.5를 17로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 1700의 ⟨1/1000⟩배인 1.7이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"68 × 25를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["0.68은 68의 ⟨1/100⟩배, 2.5는 25의 ⟨1/10⟩배예요.","곱은 68 × 25 = 1700의 ⟨1/1000⟩배여야 해요.","바른 곱은 1.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#4','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'mc','auto','계산하지 않고 어림하여 알맞은 말을 고르세요. 3.08 × 4.2는 12보다 …',ARRAY['M5-2-u4-X07','M5-2-u4-X14']::text[],true,'{"seq":4,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 3.08 × 4.2는 12보다 …","options":[{"t":"크다 — 3.08은 3보다, 4.2는 4보다 크다","correct":true},{"t":"작다 — 4.2가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 3 × 4 = 12이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["3 × 4 = 12를 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 12보다 커요.","실제로 3.08 × 4.2 = 12.936이에요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 0.48 × 5는 2.5보다 …","options":[{"t":"작다 — 0.48은 0.5보다 작다","correct":true},{"t":"크다 — 두 수를 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 0.5 × 5 = 2.5이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.5 × 5 = 2.5를 기준으로 삼아요.","0.48이 0.5보다 작으니 곱도 2.5보다 작아요.","실제로 0.48 × 5 = 2.4예요."]},{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 5.97 × 2는 12보다 …","options":[{"t":"작다 — 5.97은 6보다 작다","correct":true},{"t":"크다 — 두 수를 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 6 × 2 = 12이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["6 × 2 = 12를 기준으로 삼아요.","5.97이 6보다 작으니 곱도 12보다 작아요.","실제로 5.97 × 2 = 11.94예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#5','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'mc','auto','고무나무의 높이는 2.52 m예요. 몬스테라의 높이는 고무나무의 1.4배예요. 몬스테라의 높이는 몇 m인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X17','M5-2-u4-X01']::text[],true,'{"seq":5,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"고무나무의 높이는 2.52 m예요. 몬스테라의 높이는 고무나무의 1.4배예요. 몬스테라의 높이는 몇 m인가요?","options":[{"t":"3.528 m","correct":true},{"t":"35.28 m","mis":"M5-2-u4-X03"},{"t":"3.92 m","mis":"M5-2-u4-X17"},{"t":"3528 m","mis":"M5-2-u4-X01"}],"explanation":["「2.52의 1.4배」는 2.52 × 1.4예요.","252 × 14 = 3528이고 곱은 그 ⟨1/1000⟩배예요.","2.52 × 1.4 = 3.528 — 3.528 m예요."],"variant_rule":{"alt":[{"stem":"사과즙을 2.4 L 만들고, 배즙은 사과즙의 0.85배만큼 만들었어요. 배즙은 몇 L인가요?","options":[{"t":"2.04 L","correct":true},{"t":"20.4 L","mis":"M5-2-u4-X03"},{"t":"3.25 L","mis":"M5-2-u4-X17"},{"t":"2040 L","mis":"M5-2-u4-X01"}],"explanation":["「2.4의 0.85배」는 2.4 × 0.85예요.","24 × 85 = 2040이고 곱은 그 ⟨1/1000⟩배예요.","2.4 × 0.85 = 2.04 — 2.04 L예요."]},{"stem":"작년에 병뚜껑을 12.5 kg 모았어요. 올해는 작년의 0.36배를 모았다면 올해 모은 병뚜껑은 몇 kg인가요?","options":[{"t":"4.5 kg","correct":true},{"t":"45 kg","mis":"M5-2-u4-X03"},{"t":"12.86 kg","mis":"M5-2-u4-X17"},{"t":"4500 kg","mis":"M5-2-u4-X01"}],"explanation":["「12.5의 0.36배」는 12.5 × 0.36이에요.","125 × 36 = 4500이고 곱은 그 ⟨1/1000⟩배예요.","12.5 × 0.36 = 4.5 — 4.5 kg이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#6','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'ox','auto','3.2 × 0.71은 2.1보다 커요.',ARRAY['M5-2-u4-X07']::text[],true,'{"seq":6,"concept":"M5-2-u4-C7","difficulty":3,"kind":"ox","stem":"3.2 × 0.71은 2.1보다 커요.","answer":"O","reason_options":[{"t":"3 × 0.7 = 2.1이고 두 수가 모두 조금씩 더 크므로","correct":true},{"t":"0.71이 1보다 작아 곱이 2.1보다 작으므로","mis":"M5-2-u4-X07"}],"mis":"M5-2-u4-X07","explanation":["3 × 0.7 = 2.1이 기준이에요.","3.2 > 3이고 0.71 > 0.7이에요.","3.2 × 0.71 = 2.272 — 2.1보다 커요."],"variant_rule":{"alt":[{"stem":"0.89 × 0.6은 0.54보다 커요.","answer":"X","reason_options":[{"t":"0.9 × 0.6 = 0.54이고 0.89는 0.9보다 작으므로","correct":true},{"t":"0.89가 0.6보다 크므로","mis":"M5-2-u4-X07"}],"explanation":["0.9 × 0.6 = 0.54가 기준이에요.","0.89 < 0.9예요.","0.89 × 0.6 = 0.534 — 0.54보다 작아요."]},{"stem":"5.1 × 1.12는 5쯤이에요.","answer":"O","reason_options":[{"t":"5.1을 5로, 1.12를 1로 어림하면 5 × 1 = 5이므로","correct":true},{"t":"5.1 × 1.12는 51 × 112와 같으므로","mis":"M5-2-u4-X01"}],"explanation":["5.1은 5에, 1.12는 1에 가까워요.","5 × 1 = 5예요.","5.1 × 1.12 = 5.712 — 5쯤이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#7','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',3,'mc','auto','0.25 × 0.48을 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X04']::text[],true,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"0.25 × 0.48을 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"0.12","correct":true},{"t":"0.012","mis":"M5-2-u4-X02"},{"t":"1.2","mis":"M5-2-u4-X02"},{"t":"0.1","mis":"M5-2-u4-X04"}],"explanation":["25 × 48 = 1200이에요.","두 수의 소수점 아래 자릿수의 합은 4 — 곱은 0.1200이에요.","끝자리 0을 생략하면 0.12예요."],"variant_rule":{"alt":[{"stem":"4.8 × 0.15를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"0.72","correct":true},{"t":"0.072","mis":"M5-2-u4-X02"},{"t":"7.2","mis":"M5-2-u4-X02"},{"t":"0.7","mis":"M5-2-u4-X04"}],"explanation":["48 × 15 = 720이에요.","두 수의 소수점 아래 자릿수의 합은 3 — 곱은 0.720이에요.","끝자리 0을 생략하면 0.72예요."]},{"stem":"1.75 × 0.4를 계산하여 끝자리 0을 생략해 나타내면 어느 것인가요?","options":[{"t":"0.7","correct":true},{"t":"0.07","mis":"M5-2-u4-X02"},{"t":"7","mis":"M5-2-u4-X02"},{"t":"70","mis":"M5-2-u4-X02"}],"explanation":["175 × 4 = 700이에요.","두 수의 소수점 아래 자릿수의 합은 3 — 곱은 0.700이에요.","끝자리 0을 생략하면 0.7이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#8','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',4,'sa','auto','□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 2.□ × 6이 15보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u4-C7","difficulty":4,"kind":"sa","stem":"□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 2.□ × 6이 15보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["2.4 × 6 = 14.4 < 15예요.","2.5 × 6 = 15 — 15보다 작지 않아요.","□는 1, 2, 3, 4 — 모두 4개예요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 1.□ × 7이 12보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["1.7 × 7 = 11.9 < 12예요.","1.8 × 7 = 12.6 > 12예요.","□는 1, 2, 3, 4, 5, 6, 7 — 모두 7개예요."]},{"stem":"□ 안에 1부터 9까지의 자연수가 들어갈 수 있어요. 5.□ × 3이 17보다 작게 되는 □는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["5.6 × 3 = 16.8 < 17이에요.","5.7 × 3 = 17.1 > 17이에요.","□는 1, 2, 3, 4, 5, 6 — 모두 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#9','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',4,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u4-C7","difficulty":4,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.47 × 0.3","r":"0.141"},{"l":"2.5 × 1.89","r":"4.725"},{"l":"0.32 × 4.5","r":"1.44"}],"mis":"M5-2-u4-X03","explanation":["두 수의 소수점 아래 자릿수를 더한 만큼 곱의 소수점을 찍어요.","0.47 × 0.3 = 0.141 · 2.5 × 1.89 = 4.725예요.","0.32 × 4.5 = 1.44예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"1.23 × 0.4","r":"0.492"},{"l":"0.6 × 0.15","r":"0.09"},{"l":"3.2 × 0.71","r":"2.272"}],"explanation":["두 수의 소수점 아래 자릿수를 더한 만큼 곱의 소수점을 찍어요.","1.23 × 0.4 = 0.492 · 0.6 × 0.15 = 0.09예요.","3.2 × 0.71 = 2.272예요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.25 × 0.8","r":"0.2"},{"l":"5.1 × 1.12","r":"5.712"},{"l":"0.9 × 0.13","r":"0.117"}],"explanation":["두 수의 소수점 아래 자릿수를 더한 만큼 곱의 소수점을 찍어요.","0.25 × 0.8 = 0.2 · 5.1 × 1.12 = 5.712예요.","0.9 × 0.13 = 0.117이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L07_challenge#10','math',5,2,'u4','L07','g5_2_math_u4_L07_challenge','lesson_challenge','M5-2-u4-C7',4,'essay','teacher','해달 인형의 길이는 0.47 m이고 물고기 인형은 해달 인형의 0.3배예요. 물고기 인형의 길이를 분수의 곱셈과 자연수의 곱셈 두 가지로 구하고, 곱이 소수 몇 자리 수가 되는지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"해달 인형의 길이는 0.47 m이고 물고기 인형은 해달 인형의 0.3배예요. 물고기 인형의 길이를 분수의 곱셈과 자연수의 곱셈 두 가지로 구하고, 곱이 소수 몇 자리 수가 되는지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 분수로 — ⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩ = 0.141이다. 자연수로 — 47 × 3 = 141이고 0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배이므로 곱은 141의 ⟨1/1000⟩배인 0.141이다. 소수 두 자리 수와 한 자리 수를 곱했으므로 곱은 2 + 1 = 3, 소수 세 자리 수이다. 물고기 인형은 0.141 m이다.","scoring_points":["분수의 곱셈으로 0.141을 구했는가","자연수의 곱셈과 ⟨1/1000⟩배로 0.141을 구했는가","소수점 아래 자릿수 2 + 1 = 3이라고 설명했는가"]},"explanation":["⟨47/100⟩ × ⟨3/10⟩ = ⟨141/1000⟩이에요.","141의 ⟨1/1000⟩배는 0.141이에요.","2 + 1 = 3 — 소수 세 자리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#1','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'mc','auto','4.81 × 100을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"4.81 × 100을 계산하면 얼마인가요?","options":[{"t":"481","correct":true},{"t":"0.0481","mis":"M5-2-u4-X10"},{"t":"4810","mis":"M5-2-u4-X11"},{"t":"48.1","mis":"M5-2-u4-X11"}],"explanation":["100을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","100에는 0이 2개 — 오른쪽으로 두 자리예요.","4.81 × 100 = 481이에요."],"variant_rule":{"alt":[{"stem":"0.375 × 10을 계산하면 얼마인가요?","options":[{"t":"3.75","correct":true},{"t":"0.0375","mis":"M5-2-u4-X10"},{"t":"37.5","mis":"M5-2-u4-X11"},{"t":"0.375","mis":"M5-2-u4-X11"}],"explanation":["10을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","10에는 0이 1개 — 오른쪽으로 한 자리예요.","0.375 × 10 = 3.75예요."]},{"stem":"2.38 × 1000을 계산하면 얼마인가요?","options":[{"t":"2380","correct":true},{"t":"0.00238","mis":"M5-2-u4-X10"},{"t":"23800","mis":"M5-2-u4-X11"},{"t":"238","mis":"M5-2-u4-X11"}],"explanation":["1000을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","1000에는 0이 3개 — 오른쪽으로 세 자리예요.","2.38 × 1000 = 2380이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#2','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'mc','auto','4810 × 0.01을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":2,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"4810 × 0.01을 계산하면 얼마인가요?","options":[{"t":"48.1","correct":true},{"t":"481000","mis":"M5-2-u4-X10"},{"t":"4.81","mis":"M5-2-u4-X11"},{"t":"481","mis":"M5-2-u4-X11"}],"explanation":["0.01을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.01은 소수 두 자리 수 — 왼쪽으로 두 자리예요.","4810 × 0.01 = 48.1이에요."],"variant_rule":{"alt":[{"stem":"16 × 0.001을 계산하면 얼마인가요?","options":[{"t":"0.016","correct":true},{"t":"16000","mis":"M5-2-u4-X10"},{"t":"0.0016","mis":"M5-2-u4-X11"},{"t":"0.16","mis":"M5-2-u4-X11"}],"explanation":["0.001을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.001은 소수 세 자리 수 — 왼쪽으로 세 자리예요.","16 × 0.001 = 0.016이에요."]},{"stem":"375 × 0.1을 계산하면 얼마인가요?","options":[{"t":"37.5","correct":true},{"t":"3750","mis":"M5-2-u4-X10"},{"t":"3.75","mis":"M5-2-u4-X11"},{"t":"375","mis":"M5-2-u4-X11"}],"explanation":["0.1을 곱하면 소수점이 왼쪽으로 옮겨져요.","0.1은 소수 한 자리 수 — 왼쪽으로 한 자리예요.","375 × 0.1 = 37.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#3','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'ox','auto','4.81 × 100 = 481이에요.',ARRAY['M5-2-u4-X10']::text[],true,'{"seq":3,"concept":"M5-2-u4-C8","difficulty":1,"kind":"ox","stem":"4.81 × 100 = 481이에요.","answer":"O","reason_options":[{"t":"100을 곱하면 소수점이 오른쪽으로 두 자리 옮겨지므로","correct":true},{"t":"100을 곱하면 소수점이 왼쪽으로 옮겨지므로","mis":"M5-2-u4-X10"}],"mis":"M5-2-u4-X10","explanation":["100에는 0이 2개예요.","소수점을 오른쪽으로 두 자리 옮겨요.","4.81 × 100 = 481 — 맞아요."],"variant_rule":{"alt":[{"stem":"0.09 × 0.07 = 0.0063이에요.","answer":"O","reason_options":[{"t":"9 × 7 = 63에서 소수점을 왼쪽으로 네 자리 옮기고 빈 자리를 0으로 채우므로","correct":true},{"t":"소수 두 자리 수끼리 곱하면 소수 두 자리 수이므로","mis":"M5-2-u4-X03"}],"explanation":["9 × 7 = 63이에요.","2 + 2 = 4 — 왼쪽으로 네 자리, 빈 자리는 0이에요.","0.09 × 0.07 = 0.0063 — 맞아요."]},{"stem":"37 × 21 = 777이므로 3.7 × 2.1 = 7.77이에요.","answer":"O","reason_options":[{"t":"소수 한 자리 수끼리의 곱은 소수 두 자리 수이므로","correct":true},{"t":"두 수 가운데 한 수의 자릿수만 세면 되므로","mis":"M5-2-u4-X03"}],"explanation":["1 + 1 = 2 — 소수 두 자리 수예요.","777에서 소수점을 왼쪽으로 두 자리 옮겨요.","3.7 × 2.1 = 7.77 — 맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#4','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',1,'mc','auto','양치 컵을 쓰면 한 번 양치할 때 물 4.81 L를 아낄 수 있어요. 10번 양치하면 물을 몇 L 아낄 수 있나요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":4,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"양치 컵을 쓰면 한 번 양치할 때 물 4.81 L를 아낄 수 있어요. 10번 양치하면 물을 몇 L 아낄 수 있나요?","options":[{"t":"48.1 L","correct":true},{"t":"0.481 L","mis":"M5-2-u4-X10"},{"t":"4.81 L","mis":"M5-2-u4-X11"},{"t":"481 L","mis":"M5-2-u4-X11"}],"explanation":["같은 양을 10번 아끼니 4.81 × 10이에요.","10을 곱하면 소수점이 오른쪽으로 한 자리 옮겨져요.","4.81 × 10 = 48.1 — 48.1 L예요."],"variant_rule":{"alt":[{"stem":"양치 컵을 쓰면 한 번 양치할 때 물 0.25 L를 아낄 수 있어요. 100번 양치하면 물을 몇 L 아낄 수 있나요?","options":[{"t":"25 L","correct":true},{"t":"0.0025 L","mis":"M5-2-u4-X10"},{"t":"2.5 L","mis":"M5-2-u4-X11"},{"t":"250 L","mis":"M5-2-u4-X11"}],"explanation":["같은 양을 100번 아끼니 0.25 × 100이에요.","100을 곱하면 소수점이 오른쪽으로 두 자리 옮겨져요.","0.25 × 100 = 25 — 25 L예요."]},{"stem":"양치 컵을 쓰면 한 번 양치할 때 물 1.35 L를 아낄 수 있어요. 1000번 양치하면 물을 몇 L 아낄 수 있나요?","options":[{"t":"1350 L","correct":true},{"t":"0.00135 L","mis":"M5-2-u4-X10"},{"t":"135 L","mis":"M5-2-u4-X11"},{"t":"13500 L","mis":"M5-2-u4-X11"}],"explanation":["같은 양을 1000번 아끼니 1.35 × 1000이에요.","1000을 곱하면 소수점이 오른쪽으로 세 자리 옮겨져요.","1.35 × 1000 = 1350 — 1350 L예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#5','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'sa','auto','4810 × 0.01 = 48.1이에요. 4810의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u4-C8","difficulty":2,"kind":"sa","stem":"4810 × 0.01 = 48.1이에요. 4810의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["0.01은 소수 두 자리 수예요.","4810 × 0.01은 소수점을 왼쪽으로 2자리 옮겨요.","4810 → 48.1 — 2자리예요."],"mis":"M5-2-u4-X11","variant_rule":{"alt":[{"stem":"16 × 0.001 = 0.016이에요. 16의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.001은 소수 세 자리 수예요.","16 × 0.001은 소수점을 왼쪽으로 3자리 옮겨요.","16 → 0.016 — 3자리예요."]},{"stem":"375 × 0.1 = 37.5예요. 375의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["0.1은 소수 한 자리 수예요.","375 × 0.1은 소수점을 왼쪽으로 1자리 옮겨요.","375 → 37.5 — 1자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#6','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'mc','auto','49 × 32 = 1568이에요. 0.49 × 0.32를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"49 × 32 = 1568이에요. 0.49 × 0.32를 계산하면 얼마인가요?","options":[{"t":"0.1568","correct":true},{"t":"15.68","mis":"M5-2-u4-X03"},{"t":"1568","mis":"M5-2-u4-X01"},{"t":"1.568","mis":"M5-2-u4-X02"}],"explanation":["0.49와 0.32의 소수점 아래 자릿수는 2개와 2개예요.","2 + 2 = 4 — 1568에서 소수점을 왼쪽으로 네 자리 옮겨요.","0.49 × 0.32 = 0.1568이에요."],"variant_rule":{"alt":[{"stem":"138 × 46 = 6348이에요. 13.8 × 4.6을 계산하면 얼마인가요?","options":[{"t":"63.48","correct":true},{"t":"634.8","mis":"M5-2-u4-X03"},{"t":"6348","mis":"M5-2-u4-X01"},{"t":"6.348","mis":"M5-2-u4-X02"}],"explanation":["13.8과 4.6의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 6348에서 소수점을 왼쪽으로 두 자리 옮겨요.","13.8 × 4.6 = 63.48이에요."]},{"stem":"37 × 21 = 777이에요. 3.7 × 2.1을 계산하면 얼마인가요?","options":[{"t":"7.77","correct":true},{"t":"77.7","mis":"M5-2-u4-X03"},{"t":"777","mis":"M5-2-u4-X01"},{"t":"0.777","mis":"M5-2-u4-X02"}],"explanation":["3.7과 2.1의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 777에서 소수점을 왼쪽으로 두 자리 옮겨요.","3.7 × 2.1 = 7.77이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#7','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'sa','auto','49 × 32 = 1568이에요. 0.49 × 0.32의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C8","difficulty":2,"kind":"sa","stem":"49 × 32 = 1568이에요. 0.49 × 0.32의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.49는 소수 두 자리, 0.32는 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 2 = 4예요.","0.49 × 0.32 = 0.1568 — 소수 네 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"138 × 46 = 6348이에요. 1.38 × 4.6의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1.38은 소수 두 자리, 4.6은 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","1.38 × 4.6 = 6.348 — 소수 세 자리 수예요."]},{"stem":"9 × 7 = 63이에요. 0.9 × 0.07의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.9는 소수 한 자리, 0.07은 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 2 = 3이에요.","0.9 × 0.07 = 0.063 — 소수 세 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#8','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'ox','auto','4810 × 0.01 = 4.81이에요.',ARRAY['M5-2-u4-X11']::text[],true,'{"seq":8,"concept":"M5-2-u4-C8","difficulty":2,"kind":"ox","stem":"4810 × 0.01 = 4.81이에요.","answer":"X","reason_options":[{"t":"0.01을 곱하면 소수점이 왼쪽으로 두 자리 옮겨져 48.1이므로","correct":true},{"t":"0.01을 곱하면 소수점이 세 자리 옮겨지므로","mis":"M5-2-u4-X11"}],"mis":"M5-2-u4-X11","explanation":["0.01은 소수 두 자리 수예요.","왼쪽으로 두 자리 옮겨요.","4810 × 0.01 = 48.1이에요."],"variant_rule":{"alt":[{"stem":"2.38 × 1000 = 238이에요.","answer":"X","reason_options":[{"t":"1000을 곱하면 소수점이 오른쪽으로 세 자리 옮겨져 2380이므로","correct":true},{"t":"1000을 곱해도 두 자리만 옮기므로","mis":"M5-2-u4-X11"}],"explanation":["1000에는 0이 3개예요.","오른쪽으로 세 자리 — 빈 자리는 0이에요.","2.38 × 1000 = 2380이에요."]},{"stem":"16 × 0.001 = 0.16이에요.","answer":"X","reason_options":[{"t":"0.001을 곱하면 소수점이 왼쪽으로 세 자리 옮겨져 0.016이므로","correct":true},{"t":"0.001을 곱해도 두 자리만 옮기므로","mis":"M5-2-u4-X11"}],"explanation":["0.001은 소수 세 자리 수예요.","16 → 1.6 → 0.16 → 0.016이에요.","16 × 0.001 = 0.016이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#9','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',2,'mc','auto','0.09 × 0.07을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X12','M5-2-u4-X03','M5-2-u4-X11']::text[],true,'{"seq":9,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"0.09 × 0.07을 계산하면 얼마인가요?","options":[{"t":"0.0063","correct":true},{"t":"0.063","mis":"M5-2-u4-X12"},{"t":"0.63","mis":"M5-2-u4-X03"},{"t":"0.00063","mis":"M5-2-u4-X11"}],"explanation":["9 × 7 = 63이에요.","소수점 아래 자릿수가 2 + 2 = 4 — 63에서 왼쪽으로 네 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.0063이에요."],"variant_rule":{"alt":[{"stem":"0.04 × 0.2를 계산하면 얼마인가요?","options":[{"t":"0.008","correct":true},{"t":"0.08","mis":"M5-2-u4-X12"},{"t":"0.8","mis":"M5-2-u4-X03"},{"t":"0.0008","mis":"M5-2-u4-X11"}],"explanation":["4 × 2 = 8이에요.","소수점 아래 자릿수가 2 + 1 = 3 — 8에서 왼쪽으로 세 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.008이에요."]},{"stem":"0.05 × 0.03을 계산하면 얼마인가요?","options":[{"t":"0.0015","correct":true},{"t":"0.015","mis":"M5-2-u4-X12"},{"t":"0.15","mis":"M5-2-u4-X03"},{"t":"0.00015","mis":"M5-2-u4-X11"}],"explanation":["5 × 3 = 15예요.","소수점 아래 자릿수가 2 + 2 = 4 — 15에서 왼쪽으로 네 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.0015예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_basic#10','math',5,2,'u4','L08','g5_2_math_u4_L08_basic','lesson_basic','M5-2-u4-C8',3,'mc','auto','다을은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」, 봄은 「138 × 46 = 6348이니까 1.38 × 4.6 = 63.48」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.',ARRAY['M5-2-u4-X18','M5-2-u4-X03']::text[],true,'{"seq":10,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"다을은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」, 봄은 「138 × 46 = 6348이니까 1.38 × 4.6 = 63.48」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"봄 — 바른 곱은 6.348","correct":true},{"t":"다을 — 바른 곱은 1.568","mis":"M5-2-u4-X18"},{"t":"봄 — 바른 곱은 634.8","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["0.49 × 0.32의 소수점 아래 자릿수는 2 + 2 = 4예요.","1.38 × 4.6의 소수점 아래 자릿수는 2 + 1 = 3이에요.","봄의 말이 틀렸어요 — 바른 곱은 6.348이에요."],"variant_rule":{"alt":[{"stem":"다을은 「37 × 21 = 777이니까 3.7 × 2.1 = 77.7」, 봄은 「25 × 4 = 100이니까 0.25 × 0.4 = 0.1」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"다을 — 바른 곱은 7.77","correct":true},{"t":"봄 — 바른 곱은 1","mis":"M5-2-u4-X18"},{"t":"다을 — 바른 곱은 777","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["3.7 × 2.1의 소수점 아래 자릿수는 1 + 1 = 2예요.","0.25 × 0.4의 소수점 아래 자릿수는 2 + 1 = 3이에요.","다을의 말이 틀렸어요 — 바른 곱은 7.77이에요."]},{"stem":"다을은 「6 × 15 = 90이니까 0.6 × 0.15 = 0.09」, 봄은 「24 × 17 = 408이니까 2.4 × 1.7 = 40.8」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"봄 — 바른 곱은 4.08","correct":true},{"t":"다을 — 바른 곱은 0.9","mis":"M5-2-u4-X18"},{"t":"봄 — 바른 곱은 408","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["0.6 × 0.15의 소수점 아래 자릿수는 1 + 2 = 3이에요.","2.4 × 1.7의 소수점 아래 자릿수는 1 + 1 = 2예요.","봄의 말이 틀렸어요 — 바른 곱은 4.08이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#1','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',2,'mc','auto','259 × 13 = 3367이에요. 2.59 × 1.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":1,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"259 × 13 = 3367이에요. 2.59 × 1.3을 계산하면 얼마인가요?","options":[{"t":"3.367","correct":true},{"t":"33.67","mis":"M5-2-u4-X03"},{"t":"3367","mis":"M5-2-u4-X01"},{"t":"0.3367","mis":"M5-2-u4-X02"}],"explanation":["2.59와 1.3의 소수점 아래 자릿수는 2개와 1개예요.","2 + 1 = 3 — 3367에서 소수점을 왼쪽으로 세 자리 옮겨요.","2.59 × 1.3 = 3.367이에요."],"variant_rule":{"alt":[{"stem":"47 × 83 = 3901이에요. 0.47 × 0.83을 계산하면 얼마인가요?","options":[{"t":"0.3901","correct":true},{"t":"39.01","mis":"M5-2-u4-X03"},{"t":"3901","mis":"M5-2-u4-X01"},{"t":"3.901","mis":"M5-2-u4-X02"}],"explanation":["0.47과 0.83의 소수점 아래 자릿수는 2개와 2개예요.","2 + 2 = 4 — 3901에서 소수점을 왼쪽으로 네 자리 옮겨요.","0.47 × 0.83 = 0.3901이에요."]},{"stem":"152 × 6 = 912예요. 15.2 × 0.06을 계산하면 얼마인가요?","options":[{"t":"0.912","correct":true},{"t":"9.12","mis":"M5-2-u4-X03"},{"t":"912","mis":"M5-2-u4-X01"},{"t":"0.0912","mis":"M5-2-u4-X02"}],"explanation":["15.2와 0.06의 소수점 아래 자릿수는 1개와 2개예요.","1 + 2 = 3 — 912에서 소수점을 왼쪽으로 세 자리 옮겨요.","15.2 × 0.06 = 0.912예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#2','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',2,'mc','auto','375 × 0.01과 계산 결과가 같은 것은 어느 것인가요?',ARRAY['M5-2-u4-X11','M5-2-u4-X10']::text[],true,'{"seq":2,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"375 × 0.01과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"3750 × 0.001","correct":true},{"t":"37.5 × 0.01","mis":"M5-2-u4-X11"},{"t":"3.75 × 10","mis":"M5-2-u4-X10"},{"t":"375 × 0.001","mis":"M5-2-u4-X11"}],"explanation":["375 × 0.01 = 3.75예요.","3750 × 0.001 = 3.75예요.","곱해지는 수가 10배, 곱하는 수가 ⟨1/10⟩배라 곱은 같아요."],"variant_rule":{"alt":[{"stem":"4.6 × 0.1과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"46 × 0.01","correct":true},{"t":"0.46 × 0.1","mis":"M5-2-u4-X11"},{"t":"0.46 × 10","mis":"M5-2-u4-X10"},{"t":"4.6 × 0.01","mis":"M5-2-u4-X11"}],"explanation":["4.6 × 0.1 = 0.46이에요.","46 × 0.01 = 0.46이에요.","곱해지는 수가 10배, 곱하는 수가 ⟨1/10⟩배라 곱은 같아요."]},{"stem":"52 × 0.001과 계산 결과가 같은 것은 어느 것인가요?","options":[{"t":"520 × 0.0001","correct":true},{"t":"5.2 × 0.001","mis":"M5-2-u4-X11"},{"t":"0.052 × 10","mis":"M5-2-u4-X10"},{"t":"52 × 0.0001","mis":"M5-2-u4-X11"}],"explanation":["52 × 0.001 = 0.052예요.","520 × 0.0001 = 0.052예요.","곱해지는 수가 10배, 곱하는 수가 ⟨1/10⟩배라 곱은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#3','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'mc','auto','36 × 14 = 504를 이용해요. □ × 0.14 = 50.4에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M5-2-u4-X11','M5-2-u4-X10']::text[],true,'{"seq":3,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"36 × 14 = 504를 이용해요. □ × 0.14 = 50.4에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"360","correct":true},{"t":"36","mis":"M5-2-u4-X11"},{"t":"3.6","mis":"M5-2-u4-X10"},{"t":"3600","mis":"M5-2-u4-X11"}],"explanation":["0.14는 14의 ⟨1/100⟩배예요.","50.4는 504의 ⟨1/10⟩배라 □는 36의 10배여야 해요.","360 × 0.14 = 50.4 — □는 360이에요."],"variant_rule":{"alt":[{"stem":"52 × 17 = 884를 이용해요. □ × 0.17 = 88.4에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"520","correct":true},{"t":"52","mis":"M5-2-u4-X11"},{"t":"5.2","mis":"M5-2-u4-X10"},{"t":"5200","mis":"M5-2-u4-X11"}],"explanation":["0.17은 17의 ⟨1/100⟩배예요.","88.4는 884의 ⟨1/10⟩배라 □는 52의 10배여야 해요.","520 × 0.17 = 88.4 — □는 520이에요."]},{"stem":"23 × 45 = 1035를 이용해요. □ × 0.45 = 103.5에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"230","correct":true},{"t":"23","mis":"M5-2-u4-X11"},{"t":"2.3","mis":"M5-2-u4-X10"},{"t":"2300","mis":"M5-2-u4-X11"}],"explanation":["0.45는 45의 ⟨1/100⟩배예요.","103.5는 1035의 ⟨1/10⟩배라 □는 23의 10배여야 해요.","230 × 0.45 = 103.5 — □는 230이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#4','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'mc','auto','다을은 「26 × 35 = 910이니까 2.6 × 0.35 = 9.1」, 봄은 「8 × 45 = 360이니까 0.8 × 0.45 = 0.36」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.',ARRAY['M5-2-u4-X18','M5-2-u4-X03']::text[],true,'{"seq":4,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"다을은 「26 × 35 = 910이니까 2.6 × 0.35 = 9.1」, 봄은 「8 × 45 = 360이니까 0.8 × 0.45 = 0.36」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"다을 — 바른 곱은 0.91","correct":true},{"t":"봄 — 바른 곱은 3.6","mis":"M5-2-u4-X18"},{"t":"다을 — 바른 곱은 91","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["2.6 × 0.35의 소수점 아래 자릿수는 1 + 2 = 3이에요.","0.8 × 0.45의 소수점 아래 자릿수는 1 + 2 = 3이에요.","다을의 말이 틀렸어요 — 바른 곱은 0.91이에요."],"variant_rule":{"alt":[{"stem":"다을은 「7 × 3 = 21이니까 0.07 × 0.3 = 0.021」, 봄은 「54 × 23 = 1242이니까 5.4 × 2.3 = 124.2」라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"봄 — 바른 곱은 12.42","correct":true},{"t":"다을 — 바른 곱은 0.21","mis":"M5-2-u4-X18"},{"t":"봄 — 바른 곱은 1242","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["0.07 × 0.3의 소수점 아래 자릿수는 2 + 1 = 3이에요.","5.4 × 2.3의 소수점 아래 자릿수는 1 + 1 = 2예요.","봄의 말이 틀렸어요 — 바른 곱은 12.42예요."]},{"stem":"다을은 「125 × 6 = 750이니까 12.5 × 0.6 = 75」, 봄은 「14 × 5 = 70이니까 0.14 × 0.5 = 0.07」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"다을 — 바른 곱은 7.5","correct":true},{"t":"봄 — 바른 곱은 0.7","mis":"M5-2-u4-X18"},{"t":"다을 — 바른 곱은 750","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["12.5 × 0.6의 소수점 아래 자릿수는 1 + 1 = 2예요.","0.14 × 0.5의 소수점 아래 자릿수는 2 + 1 = 3이에요.","다을의 말이 틀렸어요 — 바른 곱은 7.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#5','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'sa','auto','52 × 0.001 = 0.052예요. 52의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u4-C8","difficulty":3,"kind":"sa","stem":"52 × 0.001 = 0.052예요. 52의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.001은 소수 세 자리 수예요.","52 × 0.001은 소수점을 왼쪽으로 3자리 옮겨요.","52 → 0.052 — 3자리예요."],"mis":"M5-2-u4-X11","variant_rule":{"alt":[{"stem":"7 × 0.01 = 0.07이에요. 7의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["0.01은 소수 두 자리 수예요.","7 × 0.01은 소수점을 왼쪽으로 2자리 옮겨요.","7 → 0.07 — 2자리예요."]},{"stem":"1250 × 0.1 = 125예요. 1250의 소수점을 왼쪽으로 몇 자리 옮긴 것인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["0.1은 소수 한 자리 수예요.","1250 × 0.1은 소수점을 왼쪽으로 1자리 옮겨요.","1250 → 125 — 1자리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#6','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'ox','auto','4810 × 0.01 = 4.81이에요.',ARRAY['M5-2-u4-X11']::text[],true,'{"seq":6,"concept":"M5-2-u4-C8","difficulty":3,"kind":"ox","stem":"4810 × 0.01 = 4.81이에요.","answer":"X","reason_options":[{"t":"0.01을 곱하면 소수점이 왼쪽으로 두 자리 옮겨져 48.1이므로","correct":true},{"t":"0.01을 곱하면 소수점이 세 자리 옮겨지므로","mis":"M5-2-u4-X11"}],"mis":"M5-2-u4-X11","explanation":["0.01은 소수 두 자리 수예요.","왼쪽으로 두 자리 옮겨요.","4810 × 0.01 = 48.1이에요."],"variant_rule":{"alt":[{"stem":"2.38 × 1000 = 238이에요.","answer":"X","reason_options":[{"t":"1000을 곱하면 소수점이 오른쪽으로 세 자리 옮겨져 2380이므로","correct":true},{"t":"1000을 곱해도 두 자리만 옮기므로","mis":"M5-2-u4-X11"}],"explanation":["1000에는 0이 3개예요.","오른쪽으로 세 자리 — 빈 자리는 0이에요.","2.38 × 1000 = 2380이에요."]},{"stem":"16 × 0.001 = 0.16이에요.","answer":"X","reason_options":[{"t":"0.001을 곱하면 소수점이 왼쪽으로 세 자리 옮겨져 0.016이므로","correct":true},{"t":"0.001을 곱해도 두 자리만 옮기므로","mis":"M5-2-u4-X11"}],"explanation":["0.001은 소수 세 자리 수예요.","16 → 1.6 → 0.16 → 0.016이에요.","16 × 0.001 = 0.016이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#7','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',3,'mc','auto','0.06 × 0.08을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X12','M5-2-u4-X03','M5-2-u4-X11']::text[],true,'{"seq":7,"concept":"M5-2-u4-C8","difficulty":3,"kind":"mc","stem":"0.06 × 0.08을 계산하면 얼마인가요?","options":[{"t":"0.0048","correct":true},{"t":"0.048","mis":"M5-2-u4-X12"},{"t":"0.48","mis":"M5-2-u4-X03"},{"t":"0.00048","mis":"M5-2-u4-X11"}],"explanation":["6 × 8 = 48이에요.","소수점 아래 자릿수가 2 + 2 = 4 — 48에서 왼쪽으로 네 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.0048이에요."],"variant_rule":{"alt":[{"stem":"0.15 × 0.04를 계산하면 얼마인가요?","options":[{"t":"0.006","correct":true},{"t":"0.06","mis":"M5-2-u4-X12"},{"t":"0.6","mis":"M5-2-u4-X03"},{"t":"0.0006","mis":"M5-2-u4-X11"}],"explanation":["15 × 4 = 60이에요.","소수점 아래 자릿수가 2 + 2 = 4 — 60에서 왼쪽으로 네 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.006이에요."]},{"stem":"0.03 × 0.07을 계산하면 얼마인가요?","options":[{"t":"0.0021","correct":true},{"t":"0.021","mis":"M5-2-u4-X12"},{"t":"0.21","mis":"M5-2-u4-X03"},{"t":"0.00021","mis":"M5-2-u4-X11"}],"explanation":["3 × 7 = 21이에요.","소수점 아래 자릿수가 2 + 2 = 4 — 21에서 왼쪽으로 네 자리 옮겨야 해요.","모자란 자리는 0으로 채워 0.0021이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#8','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',4,'match','auto','곱셈식과 그 곱을 바르게 이어 보세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u4-C8","difficulty":4,"kind":"match","stem":"곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"4.81 × 10","r":"48.1"},{"l":"4.81 × 100","r":"481"},{"l":"4810 × 0.001","r":"4.81"}],"mis":"M5-2-u4-X10","explanation":["10·100·1000을 곱하면 오른쪽, 0.1·0.01·0.001을 곱하면 왼쪽으로 옮겨요.","4.81 × 10 = 48.1 · 4.81 × 100 = 481이에요.","4810 × 0.001 = 4.81이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"0.375 × 1000","r":"375"},{"l":"37.5 × 0.01","r":"0.375"},{"l":"3.75 × 10","r":"37.5"}],"explanation":["10·100·1000을 곱하면 오른쪽, 0.1·0.01·0.001을 곱하면 왼쪽으로 옮겨요.","0.375 × 1000 = 375 · 37.5 × 0.01 = 0.375예요.","3.75 × 10 = 37.5예요."]},{"stem":"이번에는 다른 보기예요. 곱셈식과 그 곱을 바르게 이어 보세요.","pairs":[{"l":"52 × 0.01","r":"0.52"},{"l":"0.52 × 100","r":"52"},{"l":"5.2 × 0.001","r":"0.0052"}],"explanation":["10·100·1000을 곱하면 오른쪽, 0.1·0.01·0.001을 곱하면 왼쪽으로 옮겨요.","52 × 0.01 = 0.52 · 0.52 × 100 = 52예요.","5.2 × 0.001 = 0.0052예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#9','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',4,'mc','auto','23 × 45 = 1035를 이용해요. □ × 0.45 = 103.5에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M5-2-u4-X11','M5-2-u4-X10']::text[],true,'{"seq":9,"concept":"M5-2-u4-C8","difficulty":4,"kind":"mc","stem":"23 × 45 = 1035를 이용해요. □ × 0.45 = 103.5에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"230","correct":true},{"t":"23","mis":"M5-2-u4-X11"},{"t":"2.3","mis":"M5-2-u4-X10"},{"t":"2300","mis":"M5-2-u4-X11"}],"explanation":["0.45는 45의 ⟨1/100⟩배예요.","103.5는 1035의 ⟨1/10⟩배라 □는 23의 10배여야 해요.","230 × 0.45 = 103.5 — □는 230이에요."],"variant_rule":{"alt":[{"stem":"64 × 13 = 832를 이용해요. □ × 0.13 = 83.2에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"640","correct":true},{"t":"64","mis":"M5-2-u4-X11"},{"t":"6.4","mis":"M5-2-u4-X10"},{"t":"6400","mis":"M5-2-u4-X11"}],"explanation":["0.13은 13의 ⟨1/100⟩배예요.","83.2는 832의 ⟨1/10⟩배라 □는 64의 10배여야 해요.","640 × 0.13 = 83.2 — □는 640이에요."]},{"stem":"18 × 27 = 486을 이용해요. □ × 0.27 = 48.6에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"180","correct":true},{"t":"18","mis":"M5-2-u4-X11"},{"t":"1.8","mis":"M5-2-u4-X10"},{"t":"1800","mis":"M5-2-u4-X11"}],"explanation":["0.27은 27의 ⟨1/100⟩배예요.","48.6은 486의 ⟨1/10⟩배라 □는 18의 10배여야 해요.","180 × 0.27 = 48.6 — □는 180이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L08_challenge#10','math',5,2,'u4','L08','g5_2_math_u4_L08_challenge','lesson_challenge','M5-2-u4-C8',4,'essay','teacher','양치 컵으로 한 번 양치하면 물 4.81 L를 아껴요. 10번, 100번, 1000번 양치할 때 아끼는 물의 양을 구하고 곱의 소수점이 옮겨지는 규칙을 쓰세요. 그리고 0.09 × 0.07을 그 규칙으로 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C8","difficulty":4,"kind":"essay","stem":"양치 컵으로 한 번 양치하면 물 4.81 L를 아껴요. 10번, 100번, 1000번 양치할 때 아끼는 물의 양을 구하고 곱의 소수점이 옮겨지는 규칙을 쓰세요. 그리고 0.09 × 0.07을 그 규칙으로 계산해 보세요.","answer_guide":{"answer":"예: 4.81 × 10 = 48.1, 4.81 × 100 = 481, 4.81 × 1000 = 4810이다. 곱하는 수가 10배 될 때마다 곱의 소수점이 오른쪽으로 한 자리씩 옮겨진다. 0.09 × 0.07은 9 × 7 = 63에서 두 수의 소수점 아래 자릿수 2 + 2 = 4만큼 소수점을 왼쪽으로 옮기고 빈 자리를 0으로 채워 0.0063이다.","scoring_points":["48.1 L, 481 L, 4810 L를 구했는가","10배마다 소수점이 오른쪽으로 한 자리씩 옮겨진다고 썼는가","0.09 × 0.07 = 0.0063을 자릿수 규칙으로 구했는가"]},"explanation":["4.81 × 10 = 48.1, 4.81 × 100 = 481, 4.81 × 1000 = 4810이에요.","10배마다 오른쪽으로 한 자리씩 옮겨져요.","9 × 7 = 63 → 0.0063이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#1','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'sa','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 분리배출하기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u4-C9","difficulty":1,"kind":"sa","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 분리배출하기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["표에서 분리배출하기 줄을 찾아요.","한 사람의 효과는 0.4그루, 학생 수는 22명이에요.","그래서 22명이에요."],"mis":"M5-2-u4-X18","variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 대중교통 이용하기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["표에서 대중교통 이용하기 줄을 찾아요.","한 사람의 효과는 2.6그루, 학생 수는 9명이에요.","그래서 9명이에요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 자전거 타기를 실천한 학생은 몇 명인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["표에서 자전거 타기 줄을 찾아요.","한 사람의 효과는 8.6그루, 학생 수는 3명이에요.","그래서 3명이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#2','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u4-X14','M5-2-u4-X01','M5-2-u4-X05']::text[],true,'{"seq":2,"concept":"M5-2-u4-C9","difficulty":1,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 15","correct":true},{"t":"3 × 15","mis":"M5-2-u4-X14"},{"t":"19 × 15","mis":"M5-2-u4-X01"},{"t":"2 + 15","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1.9를 2로 어림해요.","식은 2 × 15 = 30이에요."],"variant_rule":{"alt":[{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 음식물 줄이기의 반 전체 효과를 1.6 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 20","correct":true},{"t":"3 × 20","mis":"M5-2-u4-X14"},{"t":"16 × 20","mis":"M5-2-u4-X01"},{"t":"2 + 20","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1.6을 2로 어림해요.","식은 2 × 20 = 40이에요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 잔반 줄이기의 반 전체 효과를 1.7 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 16","correct":true},{"t":"3 × 16","mis":"M5-2-u4-X14"},{"t":"17 × 16","mis":"M5-2-u4-X01"},{"t":"2 + 16","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1.7을 2로 어림해요.","식은 2 × 16 = 32예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#3','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'ox','auto','반 전체 효과는 한 사람의 효과에 실천한 학생 수를 곱해 구해요.',ARRAY['M5-2-u4-X05']::text[],true,'{"seq":3,"concept":"M5-2-u4-C9","difficulty":1,"kind":"ox","stem":"반 전체 효과는 한 사람의 효과에 실천한 학생 수를 곱해 구해요.","answer":"O","reason_options":[{"t":"같은 효과가 학생 수만큼 있으므로","correct":true},{"t":"한 사람의 효과와 학생 수를 더하므로","mis":"M5-2-u4-X05"}],"mis":"M5-2-u4-X05","explanation":["한 사람이 1.9그루라면 15명이면 1.9가 15번이에요.","같은 수를 여러 번 더하면 곱셈이에요.","1.9 × 15 = 28.5예요."],"variant_rule":{"alt":[{"stem":"0.4 × 22는 22보다 작아요.","answer":"O","reason_options":[{"t":"곱하는 0.4가 1보다 작으므로","correct":true},{"t":"22가 가장 큰 수이므로","mis":"M5-2-u4-X06"}],"explanation":["0.4는 1보다 작아요.","그래서 곱은 22보다 작아요.","0.4 × 22 = 8.8이에요."]},{"stem":"어림셈으로 1.9 × 15를 2 × 15 = 30으로 볼 수 있어요.","answer":"O","reason_options":[{"t":"1.9는 2에 가까운 수이므로","correct":true},{"t":"1.9를 19로 바꾸어야 하므로","mis":"M5-2-u4-X01"}],"explanation":["1.9를 2로 어림해요.","2 × 15 = 30이에요.","실제로는 1.9 × 15 = 28.5 — 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#4','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',1,'sa','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u4-C9","difficulty":1,"kind":"sa","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 효과를 1.9 → 2로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","2 × 15 = 30이에요.","실제로는 1.9 × 15 = 28.5 — 어림한 값과 비슷해요."],"mis":"M5-2-u4-X14","variant_rule":{"alt":[{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 빨대 안 쓰기의 반 전체 효과를 0.9 → 1로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1 × 30 = 30이에요.","실제로는 0.9 × 30 = 27 — 어림한 값과 비슷해요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 자전거 타기의 반 전체 효과를 8.6 → 9로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","9 × 3 = 27이에요.","실제로는 8.6 × 3 = 25.8 — 어림한 값과 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#5','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',2,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X05']::text[],true,'{"seq":5,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"28.5그루","correct":true},{"t":"285그루","mis":"M5-2-u4-X01"},{"t":"2.85그루","mis":"M5-2-u4-X02"},{"t":"16.9그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.9 × 15예요.","19 × 15 = 285의 ⟨1/10⟩배예요.","1.9 × 15 = 28.5 — 28.5그루예요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 텀블러 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"19.6그루","correct":true},{"t":"196그루","mis":"M5-2-u4-X01"},{"t":"1.96그루","mis":"M5-2-u4-X02"},{"t":"15.4그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.4 × 14예요.","14 × 14 = 196의 ⟨1/10⟩배예요.","1.4 × 14 = 19.6 — 19.6그루예요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 잔반 줄이기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"27.2그루","correct":true},{"t":"272그루","mis":"M5-2-u4-X01"},{"t":"2.72그루","mis":"M5-2-u4-X02"},{"t":"17.7그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.7 × 16이에요.","17 × 16 = 272의 ⟨1/10⟩배예요.","1.7 × 16 = 27.2 — 27.2그루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#6','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',2,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기와 장바구니 쓰기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X02']::text[],true,'{"seq":6,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기와 장바구니 쓰기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?","options":[{"t":"47.7그루","correct":true},{"t":"3.1그루","mis":"M5-2-u4-X15"},{"t":"477그루","mis":"M5-2-u4-X02"},{"t":"4.77그루","mis":"M5-2-u4-X02"}],"explanation":["플러그 뽑기: 1.9 × 15 = 28.5예요.","장바구니 쓰기: 1.2 × 16 = 19.2예요.","28.5 + 19.2 = 47.7(그루)예요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 계단 이용하기와 텀블러 쓰기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?","options":[{"t":"34그루","correct":true},{"t":"2.2그루","mis":"M5-2-u4-X15"},{"t":"340그루","mis":"M5-2-u4-X02"},{"t":"3.4그루","mis":"M5-2-u4-X02"}],"explanation":["계단 이용하기: 0.8 × 18 = 14.4예요.","텀블러 쓰기: 1.4 × 14 = 19.6이에요.","14.4 + 19.6 = 34(그루)예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 이면지 쓰기와 빨대 안 쓰기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?","options":[{"t":"43.8그루","correct":true},{"t":"1.6그루","mis":"M5-2-u4-X15"},{"t":"438그루","mis":"M5-2-u4-X02"},{"t":"4.38그루","mis":"M5-2-u4-X02"}],"explanation":["이면지 쓰기: 0.7 × 24 = 16.8이에요.","빨대 안 쓰기: 0.9 × 30 = 27이에요.","16.8 + 27 = 43.8(그루)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#7','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',2,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],true,'{"seq":7,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"플러그 뽑기","correct":true},{"t":"텔레비전 1시간 줄이기","mis":"M5-2-u4-X15"},{"t":"분리배출하기","mis":"M5-2-u4-X15"},{"t":"장바구니 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이에요.","가장 높게 나타난 방법은 플러그 뽑기예요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"대중교통 이용하기","correct":true},{"t":"샤워 시간 줄이기","mis":"M5-2-u4-X15"},{"t":"텀블러 쓰기","mis":"M5-2-u4-X18"},{"t":"계단 이용하기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","0.8 × 18 = 14.4, 1.4 × 14 = 19.6, 2.6 × 9 = 23.4, 0.6 × 25 = 15예요.","가장 높게 나타난 방법은 대중교통 이용하기예요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"잔반 줄이기","correct":true},{"t":"자전거 타기","mis":"M5-2-u4-X15"},{"t":"손수건 쓰기","mis":"M5-2-u4-X15"},{"t":"전등 끄기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","2.1 × 12 = 25.2, 0.3 × 28 = 8.4, 1.7 × 16 = 27.2, 8.6 × 3 = 25.8이에요.","가장 높게 나타난 방법은 잔반 줄이기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#8','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',2,'ox','auto','어림셈으로 구한 값은 계산 결과와 언제나 같아요.',ARRAY['M5-2-u4-X14']::text[],true,'{"seq":8,"concept":"M5-2-u4-C9","difficulty":2,"kind":"ox","stem":"어림셈으로 구한 값은 계산 결과와 언제나 같아요.","answer":"X","reason_options":[{"t":"어림셈은 크기를 가리는 데 쓰고 정확한 값은 계산으로 확인하므로","correct":true},{"t":"어림셈이 더 정확하므로","mis":"M5-2-u4-X14"}],"mis":"M5-2-u4-X14","explanation":["0.4를 0.5로 어림하면 0.5 × 22 = 11이에요.","실제로는 0.4 × 22 = 8.8이에요.","어림한 값은 계산 결과와 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"1.2 × 16 = 19.2예요.","answer":"O","reason_options":[{"t":"12 × 16 = 192의 ⟨1/10⟩배이므로","correct":true},{"t":"12 × 16 = 192이므로 소수점을 찍지 않아도 되므로","mis":"M5-2-u4-X01"}],"explanation":["12 × 16 = 192예요.","1.2는 12의 ⟨1/10⟩배예요.","1.2 × 16 = 19.2 — 맞아요."]},{"stem":"한 사람의 효과가 가장 큰 방법이 반 전체 효과도 언제나 가장 커요.","answer":"X","reason_options":[{"t":"학생 수가 적으면 곱이 작아질 수 있으므로","correct":true},{"t":"한 사람 효과만 보면 되므로","mis":"M5-2-u4-X15"}],"explanation":["텔레비전 1시간 줄이기는 13.3그루로 가장 커요.","그러나 2명뿐이라 13.3 × 2 = 26.6이에요.","플러그 뽑기 1.9 × 15 = 28.5가 더 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#9','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',2,'sa','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 분리배출하기의 반 전체 효과를 0.4 → 0.5로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u4-C9","difficulty":2,"kind":"sa","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 분리배출하기의 반 전체 효과를 0.4 → 0.5로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","0.5 × 22 = 11이에요.","실제로는 0.4 × 22 = 8.8 — 어림한 값과 비슷해요."],"mis":"M5-2-u4-X14","variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 계단 이용하기의 반 전체 효과를 0.8 → 1로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1 × 18 = 18이에요.","실제로는 0.8 × 18 = 14.4 — 어림한 값과 비슷해요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 음식물 줄이기의 반 전체 효과를 1.6 → 2로 어림하면 어림한 값은 몇 그루인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","2 × 20 = 40이에요.","실제로는 1.6 × 20 = 32 — 어림한 값과 비슷해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_basic#10','math',5,2,'u4','L09','g5_2_math_u4_L09_basic','lesson_basic','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 분리배출하기는 실천한 학생이 22명으로 가장 많은데, 반 전체 효과는 22그루보다 적어요. 그 까닭은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X14']::text[],true,'{"seq":10,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 분리배출하기는 실천한 학생이 22명으로 가장 많은데, 반 전체 효과는 22그루보다 적어요. 그 까닭은 무엇인가요?","options":[{"t":"한 사람의 효과 0.4그루가 1보다 작아 곱이 22보다 작기 때문","correct":true},{"t":"22가 가장 큰 수라서","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못해서","mis":"M5-2-u4-X14"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"}],"explanation":["반 전체 효과는 0.4 × 22예요.","곱하는 수 0.4가 1보다 작으면 곱은 22보다 작아요.","0.4 × 22 = 8.8 — 22보다 작아요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 샤워 시간 줄이기는 실천한 학생이 25명으로 가장 많은데, 반 전체 효과는 25그루보다 적어요. 그 까닭은 무엇인가요?","options":[{"t":"한 사람의 효과 0.6그루가 1보다 작아 곱이 25보다 작기 때문","correct":true},{"t":"25가 가장 큰 수라서","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못해서","mis":"M5-2-u4-X14"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"}],"explanation":["반 전체 효과는 0.6 × 25예요.","곱하는 수 0.6이 1보다 작으면 곱은 25보다 작아요.","0.6 × 25 = 15 — 25보다 작아요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 손수건 쓰기는 실천한 학생이 28명으로 가장 많은데, 반 전체 효과는 28그루보다 적어요. 그 까닭은 무엇인가요?","options":[{"t":"한 사람의 효과 0.3그루가 1보다 작아 곱이 28보다 작기 때문","correct":true},{"t":"28이 가장 큰 수라서","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못해서","mis":"M5-2-u4-X14"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"}],"explanation":["반 전체 효과는 0.3 × 28이에요.","곱하는 수 0.3이 1보다 작으면 곱은 28보다 작아요.","0.3 × 28 = 8.4 — 28보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#1','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',2,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 텔레비전 1시간 줄이기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X05']::text[],true,'{"seq":1,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 텔레비전 1시간 줄이기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"26.6그루","correct":true},{"t":"266그루","mis":"M5-2-u4-X01"},{"t":"2.66그루","mis":"M5-2-u4-X02"},{"t":"15.3그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 13.3 × 2예요.","133 × 2 = 266의 ⟨1/10⟩배예요.","13.3 × 2 = 26.6 — 26.6그루예요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 자전거 타기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"25.8그루","correct":true},{"t":"258그루","mis":"M5-2-u4-X01"},{"t":"2.58그루","mis":"M5-2-u4-X02"},{"t":"11.6그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 8.6 × 3이에요.","86 × 3 = 258의 ⟨1/10⟩배예요.","8.6 × 3 = 25.8 — 25.8그루예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 빨대 안 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"27그루","correct":true},{"t":"270그루","mis":"M5-2-u4-X01"},{"t":"2.7그루","mis":"M5-2-u4-X02"},{"t":"30.9그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 0.9 × 30이에요.","9 × 30 = 270의 ⟨1/10⟩배예요.","0.9 × 30 = 27 — 27그루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#2','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',2,'mc','auto','도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 대중교통 이용하기의 반 전체 효과를 2.6 → 3으로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u4-X14','M5-2-u4-X01','M5-2-u4-X05']::text[],true,'{"seq":2,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 대중교통 이용하기의 반 전체 효과를 2.6 → 3으로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 × 9","correct":true},{"t":"4 × 9","mis":"M5-2-u4-X14"},{"t":"26 × 9","mis":"M5-2-u4-X01"},{"t":"3 + 9","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","2.6을 3으로 어림해요.","식은 3 × 9 = 27이에요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 전등 끄기의 반 전체 효과를 2.1 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 12","correct":true},{"t":"3 × 12","mis":"M5-2-u4-X14"},{"t":"21 × 12","mis":"M5-2-u4-X01"},{"t":"2 + 12","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","2.1을 2로 어림해요.","식은 2 × 12 = 24예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 물 아껴 쓰기의 반 전체 효과를 2.4 → 2로 어림하여 구하는 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"2 × 11","correct":true},{"t":"3 × 11","mis":"M5-2-u4-X14"},{"t":"24 × 11","mis":"M5-2-u4-X01"},{"t":"2 + 11","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","2.4를 2로 어림해요.","식은 2 × 11 = 22예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#3','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 두 번째로 높게 나타난 실천 방법은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],true,'{"seq":3,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 두 번째로 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"텔레비전 1시간 줄이기","correct":true},{"t":"분리배출하기","mis":"M5-2-u4-X15"},{"t":"플러그 뽑기","mis":"M5-2-u4-X18"},{"t":"장바구니 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이에요.","두 번째로 높게 나타난 방법은 텔레비전 1시간 줄이기예요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 반 전체의 나무 심는 효과가 두 번째로 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"자전거 타기","correct":true},{"t":"손수건 쓰기","mis":"M5-2-u4-X15"},{"t":"잔반 줄이기","mis":"M5-2-u4-X18"},{"t":"전등 끄기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","2.1 × 12 = 25.2, 0.3 × 28 = 8.4, 1.7 × 16 = 27.2, 8.6 × 3 = 25.8이에요.","두 번째로 높게 나타난 방법은 자전거 타기예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 반 전체의 나무 심는 효과가 두 번째로 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"빨대 안 쓰기","correct":true},{"t":"물 아껴 쓰기","mis":"M5-2-u4-X15"},{"t":"음식물 줄이기","mis":"M5-2-u4-X18"},{"t":"이면지 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.6 × 20 = 32, 0.7 × 24 = 16.8, 2.4 × 11 = 26.4, 0.9 × 30 = 27이에요.","두 번째로 높게 나타난 방법은 빨대 안 쓰기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#4','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 텔레비전 1시간 줄이기는 한 사람의 효과가 13.3그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X14']::text[],true,'{"seq":4,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 텔레비전 1시간 줄이기는 한 사람의 효과가 13.3그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?","options":[{"t":"실천한 학생이 2명뿐이라 모두 합한 효과가 26.6그루이기 때문","correct":true},{"t":"한 사람 효과가 가장 크니 사실은 1등이기 때문","mis":"M5-2-u4-X15"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못했기 때문","mis":"M5-2-u4-X14"}],"explanation":["반 전체 효과는 한 사람의 효과 × 학생 수예요.","13.3 × 2 = 26.6이에요.","1등 플러그 뽑기의 28.5그루보다 작아요 — 학생 수도 함께 봐야 해요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 자전거 타기는 한 사람의 효과가 8.6그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?","options":[{"t":"실천한 학생이 3명뿐이라 모두 합한 효과가 25.8그루이기 때문","correct":true},{"t":"한 사람 효과가 가장 크니 사실은 1등이기 때문","mis":"M5-2-u4-X15"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못했기 때문","mis":"M5-2-u4-X14"}],"explanation":["반 전체 효과는 한 사람의 효과 × 학생 수예요.","8.6 × 3 = 25.8이에요.","1등 잔반 줄이기의 27.2그루보다 작아요 — 학생 수도 함께 봐야 해요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 물 아껴 쓰기는 한 사람의 효과가 2.4그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?","options":[{"t":"실천한 학생이 11명뿐이라 모두 합한 효과가 26.4그루이기 때문","correct":true},{"t":"한 사람 효과가 가장 크니 사실은 1등이기 때문","mis":"M5-2-u4-X15"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못했기 때문","mis":"M5-2-u4-X14"}],"explanation":["반 전체 효과는 한 사람의 효과 × 학생 수예요.","2.4 × 11 = 26.4예요.","1등 음식물 줄이기의 32그루보다 작아요 — 학생 수도 함께 봐야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#5','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법과 가장 낮은 방법의 차이는 몇 그루인가요?',ARRAY['M5-2-u4-X18','M5-2-u4-X15','M5-2-u4-X02']::text[],true,'{"seq":5,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법과 가장 낮은 방법의 차이는 몇 그루인가요?","options":[{"t":"19.7그루","correct":true},{"t":"37.3그루","mis":"M5-2-u4-X18"},{"t":"1.5그루","mis":"M5-2-u4-X15"},{"t":"197그루","mis":"M5-2-u4-X02"}],"explanation":["가장 높은 방법은 플러그 뽑기 28.5그루예요.","가장 낮은 방법은 분리배출하기 8.8그루예요.","28.5 − 8.8 = 19.7(그루)예요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 반 전체 효과가 가장 높은 방법과 가장 낮은 방법의 차이는 몇 그루인가요?","options":[{"t":"9그루","correct":true},{"t":"37.8그루","mis":"M5-2-u4-X18"},{"t":"1.8그루","mis":"M5-2-u4-X15"},{"t":"90그루","mis":"M5-2-u4-X02"}],"explanation":["가장 높은 방법은 대중교통 이용하기 23.4그루예요.","가장 낮은 방법은 계단 이용하기 14.4그루예요.","23.4 − 14.4 = 9(그루)예요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 반 전체 효과가 가장 높은 방법과 가장 낮은 방법의 차이는 몇 그루인가요?","options":[{"t":"18.8그루","correct":true},{"t":"35.6그루","mis":"M5-2-u4-X18"},{"t":"1.4그루","mis":"M5-2-u4-X15"},{"t":"188그루","mis":"M5-2-u4-X02"}],"explanation":["가장 높은 방법은 잔반 줄이기 27.2그루예요.","가장 낮은 방법은 손수건 쓰기 8.4그루예요.","27.2 − 8.4 = 18.8(그루)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#6','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',3,'error','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 수아는 「한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 반 전체 효과도 가장 높다」고 말했어요. 바르게 고친 것은 어느 것인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],true,'{"seq":6,"concept":"M5-2-u4-C9","difficulty":3,"kind":"error","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 수아는 「한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 반 전체 효과도 가장 높다」고 말했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"효과 × 학생 수로 견주어야 한다 — 가장 높은 방법은 플러그 뽑기이다","correct":true,"mis_target":"M5-2-u4-X15"},{"t":"학생 수가 가장 많은 분리배출하기가 가장 높다","mis":"M5-2-u4-X15"},{"t":"바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이에요.","가장 높은 방법은 플러그 뽑기예요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 민준은 「한 사람의 효과가 가장 큰 자전거 타기가 반 전체 효과도 가장 높다」고 말했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"효과 × 학생 수로 견주어야 한다 — 가장 높은 방법은 잔반 줄이기이다","correct":true,"mis_target":"M5-2-u4-X15"},{"t":"학생 수가 가장 많은 손수건 쓰기가 가장 높다","mis":"M5-2-u4-X15"},{"t":"바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","2.1 × 12 = 25.2, 0.3 × 28 = 8.4, 1.7 × 16 = 27.2, 8.6 × 3 = 25.8이에요.","가장 높은 방법은 잔반 줄이기예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 가온은 「한 사람의 효과가 가장 큰 물 아껴 쓰기가 반 전체 효과도 가장 높다」고 말했어요. 바르게 고친 것은 어느 것인가요?","options":[{"t":"효과 × 학생 수로 견주어야 한다 — 가장 높은 방법은 음식물 줄이기이다","correct":true,"mis_target":"M5-2-u4-X15"},{"t":"학생 수가 가장 많은 빨대 안 쓰기가 가장 높다","mis":"M5-2-u4-X15"},{"t":"바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["반 전체 효과 = 한 사람의 효과 × 학생 수예요.","1.6 × 20 = 32, 0.7 × 24 = 16.8, 2.4 × 11 = 26.4, 0.9 × 30 = 27이에요.","가장 높은 방법은 음식물 줄이기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#7','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',3,'ox','auto','한 사람의 효과가 가장 큰 방법이 반 전체 효과도 언제나 가장 커요.',ARRAY['M5-2-u4-X15']::text[],true,'{"seq":7,"concept":"M5-2-u4-C9","difficulty":3,"kind":"ox","stem":"한 사람의 효과가 가장 큰 방법이 반 전체 효과도 언제나 가장 커요.","answer":"X","reason_options":[{"t":"학생 수가 적으면 곱이 작아질 수 있으므로","correct":true},{"t":"한 사람 효과만 보면 되므로","mis":"M5-2-u4-X15"}],"mis":"M5-2-u4-X15","explanation":["텔레비전 1시간 줄이기는 13.3그루로 가장 커요.","그러나 2명뿐이라 13.3 × 2 = 26.6이에요.","플러그 뽑기 1.9 × 15 = 28.5가 더 커요."],"variant_rule":{"alt":[{"stem":"어림셈으로 구한 값은 계산 결과와 언제나 같아요.","answer":"X","reason_options":[{"t":"어림셈은 크기를 가리는 데 쓰고 정확한 값은 계산으로 확인하므로","correct":true},{"t":"어림셈이 더 정확하므로","mis":"M5-2-u4-X14"}],"explanation":["0.4를 0.5로 어림하면 0.5 × 22 = 11이에요.","실제로는 0.4 × 22 = 8.8이에요.","어림한 값은 계산 결과와 다를 수 있어요."]},{"stem":"0.4 × 22는 22보다 작아요.","answer":"O","reason_options":[{"t":"곱하는 0.4가 1보다 작으므로","correct":true},{"t":"22가 가장 큰 수이므로","mis":"M5-2-u4-X06"}],"explanation":["0.4는 1보다 작아요.","그래서 곱은 22보다 작아요.","0.4 × 22 = 8.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#8','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',4,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 가장 낮게 나타난 실천 방법은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],true,'{"seq":8,"concept":"M5-2-u4-C9","difficulty":4,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 가장 낮게 나타난 실천 방법은 무엇인가요?","options":[{"t":"분리배출하기","correct":true},{"t":"텔레비전 1시간 줄이기","mis":"M5-2-u4-X15"},{"t":"플러그 뽑기","mis":"M5-2-u4-X18"},{"t":"장바구니 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이에요.","가장 낮게 나타난 방법은 분리배출하기예요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 반 전체의 나무 심는 효과가 가장 낮게 나타난 실천 방법은 무엇인가요?","options":[{"t":"계단 이용하기","correct":true},{"t":"대중교통 이용하기","mis":"M5-2-u4-X15"},{"t":"샤워 시간 줄이기","mis":"M5-2-u4-X15"},{"t":"텀블러 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","0.8 × 18 = 14.4, 1.4 × 14 = 19.6, 2.6 × 9 = 23.4, 0.6 × 25 = 15예요.","가장 낮게 나타난 방법은 계단 이용하기예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 반 전체의 나무 심는 효과가 가장 낮게 나타난 실천 방법은 무엇인가요?","options":[{"t":"이면지 쓰기","correct":true},{"t":"물 아껴 쓰기","mis":"M5-2-u4-X15"},{"t":"빨대 안 쓰기","mis":"M5-2-u4-X15"},{"t":"음식물 줄이기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.6 × 20 = 32, 0.7 × 24 = 16.8, 2.4 × 11 = 26.4, 0.9 × 30 = 27이에요.","가장 낮게 나타난 방법은 이면지 쓰기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#9','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',4,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기와 텔레비전 1시간 줄이기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X02']::text[],true,'{"seq":9,"concept":"M5-2-u4-C9","difficulty":4,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기와 텔레비전 1시간 줄이기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?","options":[{"t":"55.1그루","correct":true},{"t":"15.2그루","mis":"M5-2-u4-X15"},{"t":"551그루","mis":"M5-2-u4-X02"},{"t":"5.51그루","mis":"M5-2-u4-X02"}],"explanation":["플러그 뽑기: 1.9 × 15 = 28.5예요.","텔레비전 1시간 줄이기: 13.3 × 2 = 26.6이에요.","28.5 + 26.6 = 55.1(그루)예요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 잔반 줄이기와 자전거 타기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?","options":[{"t":"53그루","correct":true},{"t":"10.3그루","mis":"M5-2-u4-X15"},{"t":"530그루","mis":"M5-2-u4-X02"},{"t":"5.3그루","mis":"M5-2-u4-X02"}],"explanation":["잔반 줄이기: 1.7 × 16 = 27.2예요.","자전거 타기: 8.6 × 3 = 25.8이에요.","27.2 + 25.8 = 53(그루)예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 음식물 줄이기와 빨대 안 쓰기를 함께 실천한 효과를 더하면 모두 몇 그루인가요?","options":[{"t":"59그루","correct":true},{"t":"2.5그루","mis":"M5-2-u4-X15"},{"t":"590그루","mis":"M5-2-u4-X02"},{"t":"5.9그루","mis":"M5-2-u4-X02"}],"explanation":["음식물 줄이기: 1.6 × 20 = 32예요.","빨대 안 쓰기: 0.9 × 30 = 27이에요.","32 + 27 = 59(그루)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_L09_challenge#10','math',5,2,'u4','L09','g5_2_math_u4_L09_challenge','lesson_challenge','M5-2-u4-C9',4,'essay','teacher','민주네 반 탄소 중립 생활 표(한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법을 어림셈으로 먼저 찾고 계산으로 확인한 뒤, 한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 1등이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u4-C9","difficulty":4,"kind":"essay","stem":"민주네 반 탄소 중립 생활 표(한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법을 어림셈으로 먼저 찾고 계산으로 확인한 뒤, 한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 1등이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 어림셈 — 2 × 15 = 30, 0.5 × 22 = 11, 1 × 16 = 16, 13 × 2 = 26이므로 플러그 뽑기가 가장 높을 것이다. 계산 — 1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이므로 가장 높은 방법은 플러그 뽑기(28.5그루)이다. 텔레비전 1시간 줄이기는 한 사람의 효과가 크지만 실천한 학생이 2명뿐이라 모두 합한 효과가 26.6그루로 플러그 뽑기보다 작다.","scoring_points":["어림셈으로 네 방법을 견주었는가","계산으로 플러그 뽑기 28.5그루가 가장 높음을 확인했는가","학생 수가 2명뿐이라 곱이 작다고 설명했는가"]},"explanation":["어림셈: 2 × 15 = 30이 가장 커요.","계산: 1.9 × 15 = 28.5 > 13.3 × 2 = 26.6이에요.","효과 × 학생 수로 견줘야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#1','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C1',1,'mc','auto','0.34의 10배는 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"0.34의 10배는 얼마인가요?","options":[{"t":"3.4","correct":true},{"t":"0.034","mis":"M5-2-u4-X10"},{"t":"34","mis":"M5-2-u4-X11"},{"t":"340","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","10배는 소수점을 오른쪽으로 한 자리 옮겨요.","0.34 × 10 = 3.4예요."],"variant_rule":{"alt":[{"stem":"2.58의 100배는 얼마인가요?","options":[{"t":"258","correct":true},{"t":"0.0258","mis":"M5-2-u4-X10"},{"t":"2580","mis":"M5-2-u4-X11"},{"t":"25.8","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","100배는 소수점을 오른쪽으로 두 자리 옮겨요.","2.58 × 100 = 258이에요."]},{"stem":"0.071의 1000배는 얼마인가요?","options":[{"t":"71","correct":true},{"t":"0.000071","mis":"M5-2-u4-X10"},{"t":"710","mis":"M5-2-u4-X11"},{"t":"7.1","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","1000배는 소수점을 오른쪽으로 세 자리 옮겨요.","0.071 × 1000 = 71이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#2','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C2',1,'sa','auto','0.4 × 6을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C2","difficulty":1,"kind":"sa","stem":"0.4 × 6을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["0.4는 0.1이 4개예요.","이 묶음이 6개이므로 0.1이 4 × 6 = 24개예요.","그래서 0.4 × 6 = 2.4예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"0.7 × 3을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["0.7은 0.1이 7개예요.","이 묶음이 3개이므로 0.1이 7 × 3 = 21개예요.","그래서 0.7 × 3 = 2.1이에요."]},{"stem":"1.1 × 5를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["1.1은 0.1이 11개예요.","이 묶음이 5개이므로 0.1이 11 × 5 = 55개예요.","그래서 1.1 × 5 = 5.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#3','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C3',1,'mc','auto','0.24 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],true,'{"seq":3,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"0.24 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨24/100⟩ × 3","correct":true},{"t":"⟨24/1000⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨1/24⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨24/100⟩ × ⟨3/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.24 = ⟨24/100⟩예요.","⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72예요."],"variant_rule":{"alt":[{"stem":"0.18 × 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨18/100⟩ × 5","correct":true},{"t":"⟨18/1000⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨1/18⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨18/100⟩ × ⟨5/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.18 = ⟨18/100⟩이에요.","⟨18/100⟩ × 5 = ⟨90/100⟩ = 0.9예요."]},{"stem":"1.06 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨106/100⟩ × 4","correct":true},{"t":"⟨106/1000⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/106⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨106/100⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.06 = ⟨106/100⟩이에요.","⟨106/100⟩ × 4 = ⟨424/100⟩ = 4.24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#4','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C4',1,'mc','auto','6 × 0.9는 6보다 큰가요, 작은가요?',ARRAY['M5-2-u4-X06','M5-2-u4-X07']::text[],true,'{"seq":4,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"6 × 0.9는 6보다 큰가요, 작은가요?","options":[{"t":"작다 — 6의 ⟨9/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 6을 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.9가 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.9를 1과 견주어요.","0.9는 1보다 작으니 곱은 6보다 작아요.","실제로 6 × 0.9 = 5.4예요."],"variant_rule":{"alt":[{"stem":"5 × 1.3은 5보다 큰가요, 작은가요?","options":[{"t":"크다 — 1.3이 1보다 크다","correct":true},{"t":"작다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"},{"t":"같다 — 5를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"작다 — 1.3에 소수점이 있다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 1.3을 1과 견주어요.","1.3은 1보다 크니 곱은 5보다 커요.","실제로 5 × 1.3 = 6.5예요."]},{"stem":"9 × 0.6은 9보다 큰가요, 작은가요?","options":[{"t":"작다 — 9의 ⟨6/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 9를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.6이 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.6을 1과 견주어요.","0.6은 1보다 작으니 곱은 9보다 작아요.","실제로 9 × 0.6 = 5.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#5','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C5',1,'sa','auto','6 × 0.38을 자연수의 곱셈을 이용해 계산하려고 해요. 6 × 38은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u4-C5","difficulty":1,"kind":"sa","stem":"6 × 0.38을 자연수의 곱셈을 이용해 계산하려고 해요. 6 × 38은 얼마인가요? 숫자로 쓰세요.","answer":["228"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","6 × 38 = 228이에요.","그래서 6 × 0.38 = 2.28이에요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"7 × 0.45를 자연수의 곱셈을 이용해 계산하려고 해요. 7 × 45는 얼마인가요? 숫자로 쓰세요.","answer":["315"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","7 × 45 = 315예요.","그래서 7 × 0.45 = 3.15예요."]},{"stem":"3 × 1.24를 자연수의 곱셈을 이용해 계산하려고 해요. 3 × 124는 얼마인가요? 숫자로 쓰세요.","answer":["372"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","3 × 124 = 372예요.","그래서 3 × 1.24 = 3.72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#6','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C6',1,'sa','auto','전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.6 × 0.9를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u4-C6","difficulty":1,"kind":"sa","stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.6 × 0.9를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["가로 6칸, 세로 9칸을 칠해요.","칠한 칸은 6 × 9 = 54칸이에요.","한 칸이 0.01이므로 0.6 × 0.9 = 0.54예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.4 × 0.7을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["가로 4칸, 세로 7칸을 칠해요.","칠한 칸은 4 × 7 = 28칸이에요.","한 칸이 0.01이므로 0.4 × 0.7 = 0.28이에요."]},{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.3 × 0.3을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["가로 3칸, 세로 3칸을 칠해요.","칠한 칸은 3 × 3 = 9칸이에요.","한 칸이 0.01이므로 0.3 × 0.3 = 0.09예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#7','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C7',1,'sa','auto','0.47 × 0.3의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":1,"kind":"sa","stem":"0.47 × 0.3의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.47은 소수 두 자리, 0.3은 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 0.47 × 0.3 = 0.141 — 소수 세 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"2.5 × 1.89의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["2.5는 소수 한 자리, 1.89는 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 2 = 3이에요.","실제로 2.5 × 1.89 = 4.725 — 소수 세 자리 수예요."]},{"stem":"1.23 × 0.4의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1.23은 소수 두 자리, 0.4는 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 1.23 × 0.4 = 0.492 — 소수 세 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#8','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',1,'mc','auto','4.81 × 100을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":8,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"4.81 × 100을 계산하면 얼마인가요?","options":[{"t":"481","correct":true},{"t":"0.0481","mis":"M5-2-u4-X10"},{"t":"4810","mis":"M5-2-u4-X11"},{"t":"48.1","mis":"M5-2-u4-X11"}],"explanation":["100을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","100에는 0이 2개 — 오른쪽으로 두 자리예요.","4.81 × 100 = 481이에요."],"variant_rule":{"alt":[{"stem":"0.375 × 10을 계산하면 얼마인가요?","options":[{"t":"3.75","correct":true},{"t":"0.0375","mis":"M5-2-u4-X10"},{"t":"37.5","mis":"M5-2-u4-X11"},{"t":"0.375","mis":"M5-2-u4-X11"}],"explanation":["10을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","10에는 0이 1개 — 오른쪽으로 한 자리예요.","0.375 × 10 = 3.75예요."]},{"stem":"2.38 × 1000을 계산하면 얼마인가요?","options":[{"t":"2380","correct":true},{"t":"0.00238","mis":"M5-2-u4-X10"},{"t":"23800","mis":"M5-2-u4-X11"},{"t":"238","mis":"M5-2-u4-X11"}],"explanation":["1000을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","1000에는 0이 3개 — 오른쪽으로 세 자리예요.","2.38 × 1000 = 2380이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#9','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C2',2,'mc','auto','1.2 × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"1.2 × 4를 계산하면 얼마인가요?","options":[{"t":"4.8","correct":true},{"t":"48","mis":"M5-2-u4-X01"},{"t":"0.48","mis":"M5-2-u4-X02"},{"t":"480","mis":"M5-2-u4-X02"}],"explanation":["12 × 4 = 48이에요.","1.2는 12의 ⟨1/10⟩배이므로 곱도 48의 ⟨1/10⟩배예요.","1.2 × 4 = 4.8이에요."],"variant_rule":{"alt":[{"stem":"0.7 × 6을 계산하면 얼마인가요?","options":[{"t":"4.2","correct":true},{"t":"42","mis":"M5-2-u4-X01"},{"t":"0.42","mis":"M5-2-u4-X02"},{"t":"420","mis":"M5-2-u4-X02"}],"explanation":["7 × 6 = 42예요.","0.7은 7의 ⟨1/10⟩배이므로 곱도 42의 ⟨1/10⟩배예요.","0.7 × 6 = 4.2예요."]},{"stem":"2.6 × 3을 계산하면 얼마인가요?","options":[{"t":"7.8","correct":true},{"t":"78","mis":"M5-2-u4-X01"},{"t":"0.78","mis":"M5-2-u4-X02"},{"t":"780","mis":"M5-2-u4-X02"}],"explanation":["26 × 3 = 78이에요.","2.6은 26의 ⟨1/10⟩배이므로 곱도 78의 ⟨1/10⟩배예요.","2.6 × 3 = 7.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
