INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#13','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C6',2,'mc','auto','0.6 × 0.9를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":13,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"0.6 × 0.9를 계산하면 얼마인가요?","options":[{"t":"0.54","correct":true},{"t":"5.4","mis":"M5-2-u4-X03"},{"t":"54","mis":"M5-2-u4-X01"},{"t":"0.054","mis":"M5-2-u4-X02"}],"explanation":["6 × 9 = 54예요.","0.6은 6의 ⟨1/10⟩배, 0.9는 9의 ⟨1/10⟩배예요.","그래서 곱은 54의 ⟨1/100⟩배인 0.54예요."],"variant_rule":{"alt":[{"stem":"1.9 × 3.6을 계산하면 얼마인가요?","options":[{"t":"6.84","correct":true},{"t":"68.4","mis":"M5-2-u4-X03"},{"t":"684","mis":"M5-2-u4-X01"},{"t":"0.684","mis":"M5-2-u4-X02"}],"explanation":["19 × 36 = 684예요.","1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","그래서 곱은 684의 ⟨1/100⟩배인 6.84예요."]},{"stem":"3.4 × 2.7을 계산하면 얼마인가요?","options":[{"t":"9.18","correct":true},{"t":"91.8","mis":"M5-2-u4-X03"},{"t":"918","mis":"M5-2-u4-X01"},{"t":"0.918","mis":"M5-2-u4-X02"}],"explanation":["34 × 27 = 918이에요.","3.4는 34의 ⟨1/10⟩배, 2.7은 27의 ⟨1/10⟩배예요.","그래서 곱은 918의 ⟨1/100⟩배인 9.18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#14','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C7',2,'mc','auto','0.47 × 0.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":14,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"0.47 × 0.3을 계산하면 얼마인가요?","options":[{"t":"0.141","correct":true},{"t":"1.41","mis":"M5-2-u4-X03"},{"t":"141","mis":"M5-2-u4-X01"},{"t":"0.0141","mis":"M5-2-u4-X02"}],"explanation":["47 × 3 = 141이에요.","0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배예요.","그래서 곱은 141의 ⟨1/1000⟩배인 0.141이에요."],"variant_rule":{"alt":[{"stem":"3.2 × 0.71을 계산하면 얼마인가요?","options":[{"t":"2.272","correct":true},{"t":"22.72","mis":"M5-2-u4-X03"},{"t":"2272","mis":"M5-2-u4-X01"},{"t":"0.2272","mis":"M5-2-u4-X02"}],"explanation":["32 × 71 = 2272예요.","3.2는 32의 ⟨1/10⟩배, 0.71은 71의 ⟨1/100⟩배예요.","그래서 곱은 2272의 ⟨1/1000⟩배인 2.272예요."]},{"stem":"25.2 × 1.4를 계산하면 얼마인가요?","options":[{"t":"35.28","correct":true},{"t":"352.8","mis":"M5-2-u4-X03"},{"t":"3528","mis":"M5-2-u4-X01"},{"t":"3.528","mis":"M5-2-u4-X02"}],"explanation":["252 × 14 = 3528이에요.","25.2는 252의 ⟨1/10⟩배, 1.4는 14의 ⟨1/10⟩배예요.","그래서 곱은 3528의 ⟨1/100⟩배인 35.28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#15','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',2,'mc','auto','49 × 32 = 1568이에요. 0.49 × 0.32를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":15,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"49 × 32 = 1568이에요. 0.49 × 0.32를 계산하면 얼마인가요?","options":[{"t":"0.1568","correct":true},{"t":"15.68","mis":"M5-2-u4-X03"},{"t":"1568","mis":"M5-2-u4-X01"},{"t":"1.568","mis":"M5-2-u4-X02"}],"explanation":["0.49와 0.32의 소수점 아래 자릿수는 2개와 2개예요.","2 + 2 = 4 — 1568에서 소수점을 왼쪽으로 네 자리 옮겨요.","0.49 × 0.32 = 0.1568이에요."],"variant_rule":{"alt":[{"stem":"138 × 46 = 6348이에요. 13.8 × 4.6을 계산하면 얼마인가요?","options":[{"t":"63.48","correct":true},{"t":"634.8","mis":"M5-2-u4-X03"},{"t":"6348","mis":"M5-2-u4-X01"},{"t":"6.348","mis":"M5-2-u4-X02"}],"explanation":["13.8과 4.6의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 6348에서 소수점을 왼쪽으로 두 자리 옮겨요.","13.8 × 4.6 = 63.48이에요."]},{"stem":"37 × 21 = 777이에요. 3.7 × 2.1을 계산하면 얼마인가요?","options":[{"t":"7.77","correct":true},{"t":"77.7","mis":"M5-2-u4-X03"},{"t":"777","mis":"M5-2-u4-X01"},{"t":"0.777","mis":"M5-2-u4-X02"}],"explanation":["3.7과 2.1의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 777에서 소수점을 왼쪽으로 두 자리 옮겨요.","3.7 × 2.1 = 7.77이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#16','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C9',2,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X05']::text[],true,'{"seq":16,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"28.5그루","correct":true},{"t":"285그루","mis":"M5-2-u4-X01"},{"t":"2.85그루","mis":"M5-2-u4-X02"},{"t":"16.9그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.9 × 15예요.","19 × 15 = 285의 ⟨1/10⟩배예요.","1.9 × 15 = 28.5 — 28.5그루예요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 텀블러 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"19.6그루","correct":true},{"t":"196그루","mis":"M5-2-u4-X01"},{"t":"1.96그루","mis":"M5-2-u4-X02"},{"t":"15.4그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.4 × 14예요.","14 × 14 = 196의 ⟨1/10⟩배예요.","1.4 × 14 = 19.6 — 19.6그루예요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 잔반 줄이기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"27.2그루","correct":true},{"t":"272그루","mis":"M5-2-u4-X01"},{"t":"2.72그루","mis":"M5-2-u4-X02"},{"t":"17.7그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.7 × 16이에요.","17 × 16 = 272의 ⟨1/10⟩배예요.","1.7 × 16 = 27.2 — 27.2그루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#17','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C2',3,'error','auto','수아는 1.2 × 4를 48로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":17,"concept":"M5-2-u4-C2","difficulty":3,"kind":"error","stem":"수아는 1.2 × 4를 48로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 4.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"12 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.2는 1과 2 사이의 수라 곱은 48보다 훨씬 작아야 해요.","12 × 4 = 48은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 4.8이에요."],"variant_rule":{"alt":[{"stem":"민준은 2.3 × 6을 138로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 13.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"23 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["2.3은 2와 3 사이의 수라 곱은 138보다 훨씬 작아야 해요.","23 × 6 = 138은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 13.8이에요."]},{"stem":"가온은 3.7 × 5를 185로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 18.5이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"37 × 5를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["3.7은 3과 4 사이의 수라 곱은 185보다 훨씬 작아야 해요.","37 × 5 = 185는 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 18.5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#18','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C3',3,'error','auto','수아는 1.35 × 4를 0.540으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X04']::text[],true,'{"seq":18,"concept":"M5-2-u4-C3","difficulty":3,"kind":"error","stem":"수아는 1.35 × 4를 0.540으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 5.4이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"135 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["1.35는 1보다 크므로 곱은 1 × 4 = 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배이므로 곱은 5.40이에요.","바른 곱은 5.4 — 0.540은 ⟨1/10⟩배 더 작게 쓴 거예요."],"variant_rule":{"alt":[{"stem":"민준은 2.46 × 3을 0.738로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 7.38이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"246 × 3을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["2.46은 2보다 크므로 곱은 2 × 3 = 6보다 커야 해요.","246 × 3 = 738의 ⟨1/100⟩배이므로 곱은 7.38이에요.","바른 곱은 7.38 — 0.738은 ⟨1/10⟩배 더 작게 쓴 거예요."]},{"stem":"가온은 0.75 × 6을 0.450으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 4.5이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"75 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["0.75 × 6을 어림하면 4.8쯤이에요.","75 × 6 = 450의 ⟨1/100⟩배이므로 곱은 4.50이에요.","바른 곱은 4.5 — 0.450은 ⟨1/10⟩배 더 작게 쓴 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#19','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C5',3,'error','auto','수아는 6 × 0.38을 22.8로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X06']::text[],true,'{"seq":19,"concept":"M5-2-u4-C5","difficulty":3,"kind":"error","stem":"수아는 6 × 0.38을 22.8로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 2.28이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"6 × 38을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.38은 38의 ⟨1/100⟩배이므로 곱도 6 × 38 = 228의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 6보다 작아야 하는데 22.8은 6보다 커요.","바른 곱은 2.28이에요."],"variant_rule":{"alt":[{"stem":"민준은 9 × 0.45를 40.5로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 4.05이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"9 × 45를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.45는 45의 ⟨1/100⟩배이므로 곱도 9 × 45 = 405의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 9보다 작아야 하는데 40.5는 9보다 커요.","바른 곱은 4.05예요."]},{"stem":"가온은 5 × 0.84를 42로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 4.2이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"5 × 84를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.84는 84의 ⟨1/100⟩배이므로 곱도 5 × 84 = 420의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 5보다 작아야 하는데 42는 5보다 커요.","바른 곱은 4.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#20','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C6',3,'error','auto','수아는 1.9 × 3.6을 68.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":20,"concept":"M5-2-u4-C6","difficulty":3,"kind":"error","stem":"수아는 1.9 × 3.6을 68.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 684의 ⟨1/100⟩배인 6.84이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"19 × 36을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","곱은 19 × 36 = 684의 ⟨1/100⟩배여야 해요.","바른 곱은 6.84예요."],"variant_rule":{"alt":[{"stem":"민준은 75.9 × 0.6을 455.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 4554의 ⟨1/100⟩배인 45.54이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"759 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["75.9는 759의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배예요.","곱은 759 × 6 = 4554의 ⟨1/100⟩배여야 해요.","바른 곱은 45.54예요."]},{"stem":"가온은 2.6 × 4.3을 111.8로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 1118의 ⟨1/100⟩배인 11.18이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"26 × 43을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["2.6은 26의 ⟨1/10⟩배, 4.3은 43의 ⟨1/10⟩배예요.","곱은 26 × 43 = 1118의 ⟨1/100⟩배여야 해요.","바른 곱은 11.18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#21','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C7',3,'mc','auto','계산하지 않고 어림하여 알맞은 말을 고르세요. 3.2 × 0.71은 2.1보다 …',ARRAY['M5-2-u4-X07','M5-2-u4-X14']::text[],true,'{"seq":21,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 3.2 × 0.71은 2.1보다 …","options":[{"t":"크다 — 3.2는 3보다, 0.71은 0.7보다 크다","correct":true},{"t":"작다 — 0.71이 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 3 × 0.7 = 2.1이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["3 × 0.7 = 2.1을 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 2.1보다 커요.","실제로 3.2 × 0.71 = 2.272예요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 0.89 × 0.6은 0.54보다 …","options":[{"t":"작다 — 0.89는 0.9보다 작다","correct":true},{"t":"크다 — 두 수를 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 0.9 × 0.6 = 0.54이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.9 × 0.6 = 0.54를 기준으로 삼아요.","0.89가 0.9보다 작으니 곱도 0.54보다 작아요.","실제로 0.89 × 0.6 = 0.534예요."]},{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 5.1 × 1.12는 5보다 …","options":[{"t":"크다 — 5.1은 5보다, 1.12는 1보다 크다","correct":true},{"t":"작다 — 1.12가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 5 × 1 = 5이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["5 × 1 = 5를 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 5보다 커요.","실제로 5.1 × 1.12 = 5.712예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#22','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C9',3,'mc','auto','민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],true,'{"seq":22,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"플러그 뽑기","correct":true},{"t":"텔레비전 1시간 줄이기","mis":"M5-2-u4-X15"},{"t":"분리배출하기","mis":"M5-2-u4-X15"},{"t":"장바구니 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이에요.","가장 높게 나타난 방법은 플러그 뽑기예요."],"variant_rule":{"alt":[{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"대중교통 이용하기","correct":true},{"t":"샤워 시간 줄이기","mis":"M5-2-u4-X15"},{"t":"텀블러 쓰기","mis":"M5-2-u4-X18"},{"t":"계단 이용하기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","0.8 × 18 = 14.4, 1.4 × 14 = 19.6, 2.6 × 9 = 23.4, 0.6 × 25 = 15예요.","가장 높게 나타난 방법은 대중교통 이용하기예요."]},{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"잔반 줄이기","correct":true},{"t":"자전거 타기","mis":"M5-2-u4-X15"},{"t":"손수건 쓰기","mis":"M5-2-u4-X15"},{"t":"전등 끄기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","2.1 × 12 = 25.2, 0.3 × 28 = 8.4, 1.7 × 16 = 27.2, 8.6 × 3 = 25.8이에요.","가장 높게 나타난 방법은 잔반 줄이기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#23','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',4,'mc','auto','다을은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」, 봄은 「138 × 46 = 6348이니까 1.38 × 4.6 = 63.48」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.',ARRAY['M5-2-u4-X18','M5-2-u4-X03']::text[],true,'{"seq":23,"concept":"M5-2-u4-C8","difficulty":4,"kind":"mc","stem":"다을은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」, 봄은 「138 × 46 = 6348이니까 1.38 × 4.6 = 63.48」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"봄 — 바른 곱은 6.348","correct":true},{"t":"다을 — 바른 곱은 1.568","mis":"M5-2-u4-X18"},{"t":"봄 — 바른 곱은 634.8","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["0.49 × 0.32의 소수점 아래 자릿수는 2 + 2 = 4예요.","1.38 × 4.6의 소수점 아래 자릿수는 2 + 1 = 3이에요.","봄의 말이 틀렸어요 — 바른 곱은 6.348이에요."],"variant_rule":{"alt":[{"stem":"1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?","options":[{"t":"390 km","correct":true},{"t":"338 km","mis":"M5-2-u4-X16"},{"t":"260 km","mis":"M5-2-u4-X18"},{"t":"290 km","mis":"M5-2-u4-X16"}],"explanation":["30분은 1시간의 ⟨30/60⟩이라 0.5시간이에요.","1시간 30분 = 1.5시간이에요.","260 × 1.5 = 390 — 390 km예요."]},{"stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 텔레비전 1시간 줄이기는 한 사람의 효과가 13.3그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?","options":[{"t":"실천한 학생이 2명뿐이라 모두 합한 효과가 26.6그루이기 때문","correct":true},{"t":"한 사람 효과가 가장 크니 사실은 1등이기 때문","mis":"M5-2-u4-X15"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못했기 때문","mis":"M5-2-u4-X14"}],"explanation":["반 전체 효과는 한 사람의 효과 × 학생 수예요.","13.3 × 2 = 26.6이에요.","1등 플러그 뽑기의 28.5그루보다 작아요 — 학생 수도 함께 봐야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#24','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C3',4,'essay','teacher','운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달린 거리를 분수의 곱셈과 자연수의 곱셈으로 각각 구하고, 0.24 × 3과 2.4 × 3의 곱이 어떤 관계인지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u4-C3","difficulty":4,"kind":"essay","stem":"운동장 한 바퀴는 0.24 km예요. 운동장을 3바퀴 달린 거리를 분수의 곱셈과 자연수의 곱셈으로 각각 구하고, 0.24 × 3과 2.4 × 3의 곱이 어떤 관계인지 쓰세요.","answer_guide":{"answer":"예: 분수로 — ⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72이다. 자연수로 — 24 × 3 = 72이고 0.24는 24의 ⟨1/100⟩배이므로 곱도 72의 ⟨1/100⟩배인 0.72이다. 2.4 × 3 = 7.2이고 0.24는 2.4의 ⟨1/10⟩배이므로 0.24 × 3의 곱은 2.4 × 3의 곱의 ⟨1/10⟩배이다.","scoring_points":["분수의 곱셈으로 0.72 km를 구했는가","자연수의 곱셈과 ⟨1/100⟩배로 0.72를 구했는가","0.24 × 3의 곱이 2.4 × 3의 곱의 ⟨1/10⟩배라고 썼는가"]},"explanation":["⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72예요.","72의 ⟨1/100⟩배 — 0.72 km예요.","2.4 × 3 = 7.2의 ⟨1/10⟩배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_a#25','math',5,2,'u4','','g5_2_math_u4_review_a','unit_review','M5-2-u4-C8',4,'essay','teacher','주연이는 「49 × 32 = 1568이므로 0.49 × 0.32 = 0.1568」, 예건이는 「138 × 46 = 6348이므로 13.8 × 4.6 = 634.8」이라고 말했어요. 누가 잘못 말했는지 찾고 곱의 소수점 위치를 정하는 규칙으로 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u4-C8","difficulty":4,"kind":"essay","stem":"주연이는 「49 × 32 = 1568이므로 0.49 × 0.32 = 0.1568」, 예건이는 「138 × 46 = 6348이므로 13.8 × 4.6 = 634.8」이라고 말했어요. 누가 잘못 말했는지 찾고 곱의 소수점 위치를 정하는 규칙으로 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 0.49 × 0.32는 소수 두 자리 수끼리의 곱이라 소수점 아래 자릿수가 2 + 2 = 4이므로 0.1568이 맞다. 13.8 × 4.6은 소수 한 자리 수끼리의 곱이라 1 + 1 = 2이므로 6348에서 소수점을 왼쪽으로 두 자리 옮긴 63.48이 되어야 한다. 예건이가 잘못 말했고 바른 곱은 63.48이다.","scoring_points":["주연이의 말이 맞음을 자릿수 2 + 2 = 4로 확인했는가","예건이가 잘못 말했다고 찾았는가","바른 곱 63.48을 구했는가"]},"explanation":["2 + 2 = 4 — 0.1568이 맞아요.","1 + 1 = 2 — 6348 → 63.48이에요.","예건이가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#1','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C1',1,'mc','auto','2.58의 100배는 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"2.58의 100배는 얼마인가요?","options":[{"t":"258","correct":true},{"t":"0.0258","mis":"M5-2-u4-X10"},{"t":"2580","mis":"M5-2-u4-X11"},{"t":"25.8","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","100배는 소수점을 오른쪽으로 두 자리 옮겨요.","2.58 × 100 = 258이에요."],"variant_rule":{"alt":[{"stem":"0.071의 1000배는 얼마인가요?","options":[{"t":"71","correct":true},{"t":"0.000071","mis":"M5-2-u4-X10"},{"t":"710","mis":"M5-2-u4-X11"},{"t":"7.1","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","1000배는 소수점을 오른쪽으로 세 자리 옮겨요.","0.071 × 1000 = 71이에요."]},{"stem":"5.6의 10배는 얼마인가요?","options":[{"t":"56","correct":true},{"t":"0.56","mis":"M5-2-u4-X10"},{"t":"560","mis":"M5-2-u4-X11"},{"t":"5600","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","10배는 소수점을 오른쪽으로 한 자리 옮겨요.","5.6 × 10 = 56이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#2','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C2',1,'sa','auto','0.7 × 3을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C2","difficulty":1,"kind":"sa","stem":"0.7 × 3을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["0.7은 0.1이 7개예요.","이 묶음이 3개이므로 0.1이 7 × 3 = 21개예요.","그래서 0.7 × 3 = 2.1이에요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"1.1 × 5를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["1.1은 0.1이 11개예요.","이 묶음이 5개이므로 0.1이 11 × 5 = 55개예요.","그래서 1.1 × 5 = 5.5예요."]},{"stem":"0.9 × 4를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["0.9는 0.1이 9개예요.","이 묶음이 4개이므로 0.1이 9 × 4 = 36개예요.","그래서 0.9 × 4 = 3.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#3','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C3',1,'mc','auto','0.18 × 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],true,'{"seq":3,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"0.18 × 5를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨18/100⟩ × 5","correct":true},{"t":"⟨18/1000⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨1/18⟩ × 5","mis":"M5-2-u4-X08"},{"t":"⟨18/100⟩ × ⟨5/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.18 = ⟨18/100⟩이에요.","⟨18/100⟩ × 5 = ⟨90/100⟩ = 0.9예요."],"variant_rule":{"alt":[{"stem":"1.06 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨106/100⟩ × 4","correct":true},{"t":"⟨106/1000⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/106⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨106/100⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.06 = ⟨106/100⟩이에요.","⟨106/100⟩ × 4 = ⟨424/100⟩ = 4.24예요."]},{"stem":"0.52 × 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨52/100⟩ × 2","correct":true},{"t":"⟨52/1000⟩ × 2","mis":"M5-2-u4-X08"},{"t":"⟨1/52⟩ × 2","mis":"M5-2-u4-X08"},{"t":"⟨52/100⟩ × ⟨2/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.52 = ⟨52/100⟩예요.","⟨52/100⟩ × 2 = ⟨104/100⟩ = 1.04예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#4','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C4',1,'mc','auto','5 × 1.3은 5보다 큰가요, 작은가요?',ARRAY['M5-2-u4-X07']::text[],true,'{"seq":4,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"5 × 1.3은 5보다 큰가요, 작은가요?","options":[{"t":"크다 — 1.3이 1보다 크다","correct":true},{"t":"작다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"},{"t":"같다 — 5를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"작다 — 1.3에 소수점이 있다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 1.3을 1과 견주어요.","1.3은 1보다 크니 곱은 5보다 커요.","실제로 5 × 1.3 = 6.5예요."],"variant_rule":{"alt":[{"stem":"9 × 0.6은 9보다 큰가요, 작은가요?","options":[{"t":"작다 — 9의 ⟨6/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 9를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.6이 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.6을 1과 견주어요.","0.6은 1보다 작으니 곱은 9보다 작아요.","실제로 9 × 0.6 = 5.4예요."]},{"stem":"4 × 2.2는 4보다 큰가요, 작은가요?","options":[{"t":"크다 — 2.2가 1보다 크다","correct":true},{"t":"작다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"},{"t":"같다 — 4를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"작다 — 2.2에 소수점이 있다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 2.2를 1과 견주어요.","2.2는 1보다 크니 곱은 4보다 커요.","실제로 4 × 2.2 = 8.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#5','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',1,'sa','auto','7 × 0.45를 자연수의 곱셈을 이용해 계산하려고 해요. 7 × 45는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u4-C5","difficulty":1,"kind":"sa","stem":"7 × 0.45를 자연수의 곱셈을 이용해 계산하려고 해요. 7 × 45는 얼마인가요? 숫자로 쓰세요.","answer":["315"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","7 × 45 = 315예요.","그래서 7 × 0.45 = 3.15예요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"3 × 1.24를 자연수의 곱셈을 이용해 계산하려고 해요. 3 × 124는 얼마인가요? 숫자로 쓰세요.","answer":["372"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","3 × 124 = 372예요.","그래서 3 × 1.24 = 3.72예요."]},{"stem":"9 × 0.16을 자연수의 곱셈을 이용해 계산하려고 해요. 9 × 16은 얼마인가요? 숫자로 쓰세요.","answer":["144"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","9 × 16 = 144예요.","그래서 9 × 0.16 = 1.44예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#6','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C6',1,'sa','auto','전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.4 × 0.7을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u4-C6","difficulty":1,"kind":"sa","stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.4 × 0.7을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["가로 4칸, 세로 7칸을 칠해요.","칠한 칸은 4 × 7 = 28칸이에요.","한 칸이 0.01이므로 0.4 × 0.7 = 0.28이에요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.3 × 0.3을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["가로 3칸, 세로 3칸을 칠해요.","칠한 칸은 3 × 3 = 9칸이에요.","한 칸이 0.01이므로 0.3 × 0.3 = 0.09예요."]},{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.8 × 0.5를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["가로 8칸, 세로 5칸을 칠해요.","칠한 칸은 8 × 5 = 40칸이에요.","한 칸이 0.01이므로 0.8 × 0.5 = 0.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#7','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',1,'sa','auto','2.5 × 1.89의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":1,"kind":"sa","stem":"2.5 × 1.89의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["2.5는 소수 한 자리, 1.89는 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 1 + 2 = 3이에요.","실제로 2.5 × 1.89 = 4.725 — 소수 세 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"1.23 × 0.4의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1.23은 소수 두 자리, 0.4는 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 1.23 × 0.4 = 0.492 — 소수 세 자리 수예요."]},{"stem":"0.47 × 0.83의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.47은 소수 두 자리, 0.83은 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 2 = 4예요.","실제로 0.47 × 0.83 = 0.3901 — 소수 네 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#8','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',1,'mc','auto','0.375 × 10을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":8,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"0.375 × 10을 계산하면 얼마인가요?","options":[{"t":"3.75","correct":true},{"t":"0.0375","mis":"M5-2-u4-X10"},{"t":"37.5","mis":"M5-2-u4-X11"},{"t":"0.375","mis":"M5-2-u4-X11"}],"explanation":["10을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","10에는 0이 1개 — 오른쪽으로 한 자리예요.","0.375 × 10 = 3.75예요."],"variant_rule":{"alt":[{"stem":"2.38 × 1000을 계산하면 얼마인가요?","options":[{"t":"2380","correct":true},{"t":"0.00238","mis":"M5-2-u4-X10"},{"t":"23800","mis":"M5-2-u4-X11"},{"t":"238","mis":"M5-2-u4-X11"}],"explanation":["1000을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","1000에는 0이 3개 — 오른쪽으로 세 자리예요.","2.38 × 1000 = 2380이에요."]},{"stem":"0.06 × 100을 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"0.0006","mis":"M5-2-u4-X10"},{"t":"60","mis":"M5-2-u4-X11"},{"t":"0.6","mis":"M5-2-u4-X11"}],"explanation":["100을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","100에는 0이 2개 — 오른쪽으로 두 자리예요.","0.06 × 100 = 6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#9','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C2',2,'mc','auto','0.7 × 6을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"0.7 × 6을 계산하면 얼마인가요?","options":[{"t":"4.2","correct":true},{"t":"42","mis":"M5-2-u4-X01"},{"t":"0.42","mis":"M5-2-u4-X02"},{"t":"420","mis":"M5-2-u4-X02"}],"explanation":["7 × 6 = 42예요.","0.7은 7의 ⟨1/10⟩배이므로 곱도 42의 ⟨1/10⟩배예요.","0.7 × 6 = 4.2예요."],"variant_rule":{"alt":[{"stem":"2.6 × 3을 계산하면 얼마인가요?","options":[{"t":"7.8","correct":true},{"t":"78","mis":"M5-2-u4-X01"},{"t":"0.78","mis":"M5-2-u4-X02"},{"t":"780","mis":"M5-2-u4-X02"}],"explanation":["26 × 3 = 78이에요.","2.6은 26의 ⟨1/10⟩배이므로 곱도 78의 ⟨1/10⟩배예요.","2.6 × 3 = 7.8이에요."]},{"stem":"3.8 × 5를 계산하면 얼마인가요?","options":[{"t":"19","correct":true},{"t":"190","mis":"M5-2-u4-X01"},{"t":"1.9","mis":"M5-2-u4-X02"},{"t":"1900","mis":"M5-2-u4-X02"}],"explanation":["38 × 5 = 190이에요.","3.8은 38의 ⟨1/10⟩배이므로 곱도 190의 ⟨1/10⟩배예요.","3.8 × 5 = 19예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#10','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C3',2,'mc','auto','1.35 × 4를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":10,"concept":"M5-2-u4-C3","difficulty":2,"kind":"mc","stem":"1.35 × 4를 계산하면 얼마인가요?","options":[{"t":"5.4","correct":true},{"t":"540","mis":"M5-2-u4-X01"},{"t":"54","mis":"M5-2-u4-X02"},{"t":"0.54","mis":"M5-2-u4-X02"}],"explanation":["135 × 4 = 540이에요.","1.35는 135의 ⟨1/100⟩배이므로 곱도 540의 ⟨1/100⟩배예요.","1.35 × 4 = 5.4예요."],"variant_rule":{"alt":[{"stem":"2.59 × 13을 계산하면 얼마인가요?","options":[{"t":"33.67","correct":true},{"t":"3367","mis":"M5-2-u4-X01"},{"t":"336.7","mis":"M5-2-u4-X02"},{"t":"3.367","mis":"M5-2-u4-X02"}],"explanation":["259 × 13 = 3367이에요.","2.59는 259의 ⟨1/100⟩배이므로 곱도 3367의 ⟨1/100⟩배예요.","2.59 × 13 = 33.67이에요."]},{"stem":"0.68 × 7을 계산하면 얼마인가요?","options":[{"t":"4.76","correct":true},{"t":"476","mis":"M5-2-u4-X01"},{"t":"47.6","mis":"M5-2-u4-X02"},{"t":"0.476","mis":"M5-2-u4-X02"}],"explanation":["68 × 7 = 476이에요.","0.68은 68의 ⟨1/100⟩배이므로 곱도 476의 ⟨1/100⟩배예요.","0.68 × 7 = 4.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#11','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C4',2,'mc','auto','7 × 1.6을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":11,"concept":"M5-2-u4-C4","difficulty":2,"kind":"mc","stem":"7 × 1.6을 계산하면 얼마인가요?","options":[{"t":"11.2","correct":true},{"t":"112","mis":"M5-2-u4-X01"},{"t":"1.12","mis":"M5-2-u4-X02"},{"t":"1120","mis":"M5-2-u4-X02"}],"explanation":["7 × 16 = 112예요.","1.6은 16의 ⟨1/10⟩배이므로 곱도 112의 ⟨1/10⟩배예요.","7 × 1.6 = 11.2예요."],"variant_rule":{"alt":[{"stem":"12 × 0.7을 계산하면 얼마인가요?","options":[{"t":"8.4","correct":true},{"t":"84","mis":"M5-2-u4-X01"},{"t":"0.84","mis":"M5-2-u4-X02"},{"t":"840","mis":"M5-2-u4-X02"}],"explanation":["12 × 7 = 84예요.","0.7은 7의 ⟨1/10⟩배이므로 곱도 84의 ⟨1/10⟩배예요.","12 × 0.7 = 8.4예요."]},{"stem":"23 × 1.8을 계산하면 얼마인가요?","options":[{"t":"41.4","correct":true},{"t":"414","mis":"M5-2-u4-X01"},{"t":"4.14","mis":"M5-2-u4-X02"},{"t":"4140","mis":"M5-2-u4-X02"}],"explanation":["23 × 18 = 414예요.","1.8은 18의 ⟨1/10⟩배이므로 곱도 414의 ⟨1/10⟩배예요.","23 × 1.8 = 41.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#12','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',2,'mc','auto','8 × 3.16을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":12,"concept":"M5-2-u4-C5","difficulty":2,"kind":"mc","stem":"8 × 3.16을 계산하면 얼마인가요?","options":[{"t":"25.28","correct":true},{"t":"2528","mis":"M5-2-u4-X01"},{"t":"252.8","mis":"M5-2-u4-X02"},{"t":"2.528","mis":"M5-2-u4-X02"}],"explanation":["8 × 316 = 2528이에요.","3.16은 316의 ⟨1/100⟩배이므로 곱도 2528의 ⟨1/100⟩배예요.","8 × 3.16 = 25.28이에요."],"variant_rule":{"alt":[{"stem":"15 × 0.24를 계산하면 얼마인가요?","options":[{"t":"3.6","correct":true},{"t":"360","mis":"M5-2-u4-X01"},{"t":"36","mis":"M5-2-u4-X02"},{"t":"0.36","mis":"M5-2-u4-X02"}],"explanation":["15 × 24 = 360이에요.","0.24는 24의 ⟨1/100⟩배이므로 곱도 360의 ⟨1/100⟩배예요.","15 × 0.24 = 3.6이에요."]},{"stem":"9 × 1.07을 계산하면 얼마인가요?","options":[{"t":"9.63","correct":true},{"t":"963","mis":"M5-2-u4-X01"},{"t":"96.3","mis":"M5-2-u4-X02"},{"t":"0.963","mis":"M5-2-u4-X02"}],"explanation":["9 × 107 = 963이에요.","1.07은 107의 ⟨1/100⟩배이므로 곱도 963의 ⟨1/100⟩배예요.","9 × 1.07 = 9.63이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#13','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C6',2,'mc','auto','1.9 × 3.6을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":13,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"1.9 × 3.6을 계산하면 얼마인가요?","options":[{"t":"6.84","correct":true},{"t":"68.4","mis":"M5-2-u4-X03"},{"t":"684","mis":"M5-2-u4-X01"},{"t":"0.684","mis":"M5-2-u4-X02"}],"explanation":["19 × 36 = 684예요.","1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","그래서 곱은 684의 ⟨1/100⟩배인 6.84예요."],"variant_rule":{"alt":[{"stem":"3.4 × 2.7을 계산하면 얼마인가요?","options":[{"t":"9.18","correct":true},{"t":"91.8","mis":"M5-2-u4-X03"},{"t":"918","mis":"M5-2-u4-X01"},{"t":"0.918","mis":"M5-2-u4-X02"}],"explanation":["34 × 27 = 918이에요.","3.4는 34의 ⟨1/10⟩배, 2.7은 27의 ⟨1/10⟩배예요.","그래서 곱은 918의 ⟨1/100⟩배인 9.18이에요."]},{"stem":"5.2 × 1.3을 계산하면 얼마인가요?","options":[{"t":"6.76","correct":true},{"t":"67.6","mis":"M5-2-u4-X03"},{"t":"676","mis":"M5-2-u4-X01"},{"t":"0.676","mis":"M5-2-u4-X02"}],"explanation":["52 × 13 = 676이에요.","5.2는 52의 ⟨1/10⟩배, 1.3은 13의 ⟨1/10⟩배예요.","그래서 곱은 676의 ⟨1/100⟩배인 6.76이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#14','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',2,'mc','auto','3.2 × 0.71을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":14,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"3.2 × 0.71을 계산하면 얼마인가요?","options":[{"t":"2.272","correct":true},{"t":"22.72","mis":"M5-2-u4-X03"},{"t":"2272","mis":"M5-2-u4-X01"},{"t":"0.2272","mis":"M5-2-u4-X02"}],"explanation":["32 × 71 = 2272예요.","3.2는 32의 ⟨1/10⟩배, 0.71은 71의 ⟨1/100⟩배예요.","그래서 곱은 2272의 ⟨1/1000⟩배인 2.272예요."],"variant_rule":{"alt":[{"stem":"25.2 × 1.4를 계산하면 얼마인가요?","options":[{"t":"35.28","correct":true},{"t":"352.8","mis":"M5-2-u4-X03"},{"t":"3528","mis":"M5-2-u4-X01"},{"t":"3.528","mis":"M5-2-u4-X02"}],"explanation":["252 × 14 = 3528이에요.","25.2는 252의 ⟨1/10⟩배, 1.4는 14의 ⟨1/10⟩배예요.","그래서 곱은 3528의 ⟨1/100⟩배인 35.28이에요."]},{"stem":"0.68 × 2.5를 계산하면 얼마인가요?","options":[{"t":"1.7","correct":true},{"t":"17","mis":"M5-2-u4-X03"},{"t":"1700","mis":"M5-2-u4-X01"},{"t":"0.17","mis":"M5-2-u4-X02"}],"explanation":["68 × 25 = 1700이에요.","0.68은 68의 ⟨1/100⟩배, 2.5는 25의 ⟨1/10⟩배예요.","그래서 곱은 1700의 ⟨1/1000⟩배인 1.700이에요 — 끝자리 0은 생략해 1.7로 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#15','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C8',2,'mc','auto','138 × 46 = 6348이에요. 13.8 × 4.6을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":15,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"138 × 46 = 6348이에요. 13.8 × 4.6을 계산하면 얼마인가요?","options":[{"t":"63.48","correct":true},{"t":"634.8","mis":"M5-2-u4-X03"},{"t":"6348","mis":"M5-2-u4-X01"},{"t":"6.348","mis":"M5-2-u4-X02"}],"explanation":["13.8과 4.6의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 6348에서 소수점을 왼쪽으로 두 자리 옮겨요.","13.8 × 4.6 = 63.48이에요."],"variant_rule":{"alt":[{"stem":"37 × 21 = 777이에요. 3.7 × 2.1을 계산하면 얼마인가요?","options":[{"t":"7.77","correct":true},{"t":"77.7","mis":"M5-2-u4-X03"},{"t":"777","mis":"M5-2-u4-X01"},{"t":"0.777","mis":"M5-2-u4-X02"}],"explanation":["3.7과 2.1의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 777에서 소수점을 왼쪽으로 두 자리 옮겨요.","3.7 × 2.1 = 7.77이에요."]},{"stem":"259 × 13 = 3367이에요. 2.59 × 1.3을 계산하면 얼마인가요?","options":[{"t":"3.367","correct":true},{"t":"33.67","mis":"M5-2-u4-X03"},{"t":"3367","mis":"M5-2-u4-X01"},{"t":"0.3367","mis":"M5-2-u4-X02"}],"explanation":["2.59와 1.3의 소수점 아래 자릿수는 2개와 1개예요.","2 + 1 = 3 — 3367에서 소수점을 왼쪽으로 세 자리 옮겨요.","2.59 × 1.3 = 3.367이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#16','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C9',2,'mc','auto','도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 텀블러 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X05']::text[],true,'{"seq":16,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 텀블러 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"19.6그루","correct":true},{"t":"196그루","mis":"M5-2-u4-X01"},{"t":"1.96그루","mis":"M5-2-u4-X02"},{"t":"15.4그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.4 × 14예요.","14 × 14 = 196의 ⟨1/10⟩배예요.","1.4 × 14 = 19.6 — 19.6그루예요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 잔반 줄이기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"27.2그루","correct":true},{"t":"272그루","mis":"M5-2-u4-X01"},{"t":"2.72그루","mis":"M5-2-u4-X02"},{"t":"17.7그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.7 × 16이에요.","17 × 16 = 272의 ⟨1/10⟩배예요.","1.7 × 16 = 27.2 — 27.2그루예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 빨대 안 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"27그루","correct":true},{"t":"270그루","mis":"M5-2-u4-X01"},{"t":"2.7그루","mis":"M5-2-u4-X02"},{"t":"30.9그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 0.9 × 30이에요.","9 × 30 = 270의 ⟨1/10⟩배예요.","0.9 × 30 = 27 — 27그루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#17','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C2',3,'error','auto','민준은 2.3 × 6을 138로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":17,"concept":"M5-2-u4-C2","difficulty":3,"kind":"error","stem":"민준은 2.3 × 6을 138로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 13.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"23 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["2.3은 2와 3 사이의 수라 곱은 138보다 훨씬 작아야 해요.","23 × 6 = 138은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 13.8이에요."],"variant_rule":{"alt":[{"stem":"가온은 3.7 × 5를 185로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 18.5이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"37 × 5를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["3.7은 3과 4 사이의 수라 곱은 185보다 훨씬 작아야 해요.","37 × 5 = 185는 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 18.5예요."]},{"stem":"여울은 0.8 × 9를 72로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 7.2이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"8 × 9를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["0.8은 0과 1 사이의 수라 곱은 72보다 훨씬 작아야 해요.","8 × 9 = 72는 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 7.2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#18','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C3',3,'error','auto','민준은 2.46 × 3을 0.738로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X04']::text[],true,'{"seq":18,"concept":"M5-2-u4-C3","difficulty":3,"kind":"error","stem":"민준은 2.46 × 3을 0.738로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 7.38이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"246 × 3을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["2.46은 2보다 크므로 곱은 2 × 3 = 6보다 커야 해요.","246 × 3 = 738의 ⟨1/100⟩배이므로 곱은 7.38이에요.","바른 곱은 7.38 — 0.738은 ⟨1/10⟩배 더 작게 쓴 거예요."],"variant_rule":{"alt":[{"stem":"가온은 0.75 × 6을 0.450으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 4.5이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"75 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["0.75 × 6을 어림하면 4.8쯤이에요.","75 × 6 = 450의 ⟨1/100⟩배이므로 곱은 4.50이에요.","바른 곱은 4.5 — 0.450은 ⟨1/10⟩배 더 작게 쓴 거예요."]},{"stem":"여울은 3.14 × 5를 1.570으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 15.7이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"314 × 5를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["3.14는 3보다 크므로 곱은 3 × 5 = 15보다 커야 해요.","314 × 5 = 1570의 ⟨1/100⟩배이므로 곱은 15.70이에요.","바른 곱은 15.7 — 1.570은 ⟨1/10⟩배 더 작게 쓴 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#19','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',3,'error','auto','민준은 9 × 0.45를 40.5로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X06']::text[],true,'{"seq":19,"concept":"M5-2-u4-C5","difficulty":3,"kind":"error","stem":"민준은 9 × 0.45를 40.5로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 4.05이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"9 × 45를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.45는 45의 ⟨1/100⟩배이므로 곱도 9 × 45 = 405의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 9보다 작아야 하는데 40.5는 9보다 커요.","바른 곱은 4.05예요."],"variant_rule":{"alt":[{"stem":"가온은 5 × 0.84를 42로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 4.2이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"5 × 84를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.84는 84의 ⟨1/100⟩배이므로 곱도 5 × 84 = 420의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 5보다 작아야 하는데 42는 5보다 커요.","바른 곱은 4.2예요."]},{"stem":"여울은 7 × 0.26을 18.2로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 1.82이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"7 × 26을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.26은 26의 ⟨1/100⟩배이므로 곱도 7 × 26 = 182의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 7보다 작아야 하는데 18.2는 7보다 커요.","바른 곱은 1.82예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#20','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C6',3,'error','auto','민준은 75.9 × 0.6을 455.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":20,"concept":"M5-2-u4-C6","difficulty":3,"kind":"error","stem":"민준은 75.9 × 0.6을 455.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 4554의 ⟨1/100⟩배인 45.54이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"759 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["75.9는 759의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배예요.","곱은 759 × 6 = 4554의 ⟨1/100⟩배여야 해요.","바른 곱은 45.54예요."],"variant_rule":{"alt":[{"stem":"가온은 2.6 × 4.3을 111.8로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 1118의 ⟨1/100⟩배인 11.18이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"26 × 43을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["2.6은 26의 ⟨1/10⟩배, 4.3은 43의 ⟨1/10⟩배예요.","곱은 26 × 43 = 1118의 ⟨1/100⟩배여야 해요.","바른 곱은 11.18이에요."]},{"stem":"여울은 4.5 × 2.8을 126으로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 1260의 ⟨1/100⟩배인 12.6이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"45 × 28을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["4.5는 45의 ⟨1/10⟩배, 2.8은 28의 ⟨1/10⟩배예요.","곱은 45 × 28 = 1260의 ⟨1/100⟩배여야 해요.","바른 곱은 12.6이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#21','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',3,'mc','auto','계산하지 않고 어림하여 알맞은 말을 고르세요. 0.89 × 0.6은 0.54보다 …',ARRAY['M5-2-u4-X06','M5-2-u4-X14']::text[],true,'{"seq":21,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 0.89 × 0.6은 0.54보다 …","options":[{"t":"작다 — 0.89는 0.9보다 작다","correct":true},{"t":"크다 — 두 수를 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 0.9 × 0.6 = 0.54이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.9 × 0.6 = 0.54를 기준으로 삼아요.","0.89가 0.9보다 작으니 곱도 0.54보다 작아요.","실제로 0.89 × 0.6 = 0.534예요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 5.1 × 1.12는 5보다 …","options":[{"t":"크다 — 5.1은 5보다, 1.12는 1보다 크다","correct":true},{"t":"작다 — 1.12가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 5 × 1 = 5이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["5 × 1 = 5를 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 5보다 커요.","실제로 5.1 × 1.12 = 5.712예요."]},{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 3.08 × 4.2는 12보다 …","options":[{"t":"크다 — 3.08은 3보다, 4.2는 4보다 크다","correct":true},{"t":"작다 — 4.2가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 3 × 4 = 12이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["3 × 4 = 12를 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 12보다 커요.","실제로 3.08 × 4.2 = 12.936이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#22','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C9',3,'mc','auto','도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],true,'{"seq":22,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"대중교통 이용하기","correct":true},{"t":"샤워 시간 줄이기","mis":"M5-2-u4-X15"},{"t":"텀블러 쓰기","mis":"M5-2-u4-X18"},{"t":"계단 이용하기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","0.8 × 18 = 14.4, 1.4 × 14 = 19.6, 2.6 × 9 = 23.4, 0.6 × 25 = 15예요.","가장 높게 나타난 방법은 대중교통 이용하기예요."],"variant_rule":{"alt":[{"stem":"하린이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 전등 끄기 2.1그루·12명, 손수건 쓰기 0.3그루·28명, 잔반 줄이기 1.7그루·16명, 자전거 타기 8.6그루·3명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"잔반 줄이기","correct":true},{"t":"자전거 타기","mis":"M5-2-u4-X15"},{"t":"손수건 쓰기","mis":"M5-2-u4-X15"},{"t":"전등 끄기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","2.1 × 12 = 25.2, 0.3 × 28 = 8.4, 1.7 × 16 = 27.2, 8.6 × 3 = 25.8이에요.","가장 높게 나타난 방법은 잔반 줄이기예요."]},{"stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"음식물 줄이기","correct":true},{"t":"물 아껴 쓰기","mis":"M5-2-u4-X15"},{"t":"빨대 안 쓰기","mis":"M5-2-u4-X15"},{"t":"이면지 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.6 × 20 = 32, 0.7 × 24 = 16.8, 2.4 × 11 = 26.4, 0.9 × 30 = 27이에요.","가장 높게 나타난 방법은 음식물 줄이기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#23','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',4,'mc','auto','1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?',ARRAY['M5-2-u4-X16','M5-2-u4-X18']::text[],true,'{"seq":23,"concept":"M5-2-u4-C5","difficulty":4,"kind":"mc","stem":"1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?","options":[{"t":"390 km","correct":true},{"t":"338 km","mis":"M5-2-u4-X16"},{"t":"260 km","mis":"M5-2-u4-X18"},{"t":"290 km","mis":"M5-2-u4-X16"}],"explanation":["30분은 1시간의 ⟨30/60⟩이라 0.5시간이에요.","1시간 30분 = 1.5시간이에요.","260 × 1.5 = 390 — 390 km예요."],"variant_rule":{"alt":[{"stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 텔레비전 1시간 줄이기는 한 사람의 효과가 13.3그루로 가장 큰데도 반 전체 효과는 1등이 아니에요. 그 까닭은 무엇인가요?","options":[{"t":"실천한 학생이 2명뿐이라 모두 합한 효과가 26.6그루이기 때문","correct":true},{"t":"한 사람 효과가 가장 크니 사실은 1등이기 때문","mis":"M5-2-u4-X15"},{"t":"학생 수는 곱하지 않기 때문","mis":"M5-2-u4-X15"},{"t":"어림셈을 잘못했기 때문","mis":"M5-2-u4-X14"}],"explanation":["반 전체 효과는 한 사람의 효과 × 학생 수예요.","13.3 × 2 = 26.6이에요.","1등 플러그 뽑기의 28.5그루보다 작아요 — 학생 수도 함께 봐야 해요."]},{"stem":"높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.7배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"14.7 cm","correct":true},{"t":"28.6 cm","mis":"M5-2-u4-X17"},{"t":"147 cm","mis":"M5-2-u4-X02"},{"t":"21 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 30 × 0.7 = 21(cm)예요.","두 번째 인형은 21 × 0.7 = 14.7(cm)예요.","그래서 14.7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#24','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C7',4,'essay','teacher','고무나무의 높이는 25.2 cm이고 몬스테라는 고무나무의 1.4배예요. 몬스테라의 높이를 어림하여 먼저 말하고, 계산하여 구한 뒤 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u4-C7","difficulty":4,"kind":"essay","stem":"고무나무의 높이는 25.2 cm이고 몬스테라는 고무나무의 1.4배예요. 몬스테라의 높이를 어림하여 먼저 말하고, 계산하여 구한 뒤 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 25.2를 25로, 1.4를 1.5쯤으로 보면 몬스테라는 25.2 cm보다 크고 25 × 1.5 = 37.5보다 조금 작은 정도이다. 252 × 14 = 3528이고 곱은 그 ⟨1/100⟩배이므로 25.2 × 1.4 = 35.28이다. 몬스테라의 높이는 35.28 cm로 어림한 크기와 비슷하다.","scoring_points":["1.4가 1보다 커서 25.2 cm보다 크다는 등 어림했는가","25.2 × 1.4 = 35.28을 구했는가","어림한 값과 견주었는가"]},"explanation":["1.4 > 1 — 25.2 cm보다 커요.","252 × 14 = 3528의 ⟨1/100⟩배는 35.28이에요.","35.28 cm — 어림과 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_b#25','math',5,2,'u4','','g5_2_math_u4_review_b','unit_review','M5-2-u4-C5',4,'essay','teacher','수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들어 곱하려고 해요. 두 수를 만드는 방법을 쓰고 곱을 구한 뒤, 곱이 가장 큰 두 자리 수보다 작은 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u4-C5","difficulty":4,"kind":"essay","stem":"수 카드 0, 8, 4, 7, 3을 한 번씩 모두 써서 가장 큰 두 자리 수와 가장 작은 소수 두 자리 수를 만들어 곱하려고 해요. 두 수를 만드는 방법을 쓰고 곱을 구한 뒤, 곱이 가장 큰 두 자리 수보다 작은 까닭을 쓰세요.","answer_guide":{"answer":"예: 큰 카드 8과 7로 가장 큰 두 자리 수 87을 만든다. 남은 0, 3, 4로 0을 일의 자리에 두면 가장 작은 소수 두 자리 수 0.34가 된다. 87 × 34 = 2958이므로 87 × 0.34 = 29.58이다. 곱하는 수 0.34가 1보다 작으므로 곱은 87보다 작다.","scoring_points":["87과 0.34를 바르게 만들었는가","87 × 0.34 = 29.58을 구했는가","0.34가 1보다 작아 곱이 87보다 작다고 설명했는가"]},"explanation":["가장 큰 두 자리 수는 87, 가장 작은 소수 두 자리 수는 0.34예요.","87 × 0.34 = 29.58이에요.","0.34 < 1이라 곱은 87보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#1','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C1',1,'mc','auto','0.071의 1000배는 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":1,"concept":"M5-2-u4-C1","difficulty":1,"kind":"mc","stem":"0.071의 1000배는 얼마인가요?","options":[{"t":"71","correct":true},{"t":"0.000071","mis":"M5-2-u4-X10"},{"t":"710","mis":"M5-2-u4-X11"},{"t":"7.1","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","1000배는 소수점을 오른쪽으로 세 자리 옮겨요.","0.071 × 1000 = 71이에요."],"variant_rule":{"alt":[{"stem":"5.6의 10배는 얼마인가요?","options":[{"t":"56","correct":true},{"t":"0.56","mis":"M5-2-u4-X10"},{"t":"560","mis":"M5-2-u4-X11"},{"t":"5600","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","10배는 소수점을 오른쪽으로 한 자리 옮겨요.","5.6 × 10 = 56이에요."]},{"stem":"0.34의 10배는 얼마인가요?","options":[{"t":"3.4","correct":true},{"t":"0.034","mis":"M5-2-u4-X10"},{"t":"34","mis":"M5-2-u4-X11"},{"t":"340","mis":"M5-2-u4-X11"}],"explanation":["10배 할 때마다 소수점이 오른쪽으로 한 자리씩 옮겨져요.","10배는 소수점을 오른쪽으로 한 자리 옮겨요.","0.34 × 10 = 3.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#2','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C2',1,'sa','auto','1.1 × 5를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u4-C2","difficulty":1,"kind":"sa","stem":"1.1 × 5를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["1.1은 0.1이 11개예요.","이 묶음이 5개이므로 0.1이 11 × 5 = 55개예요.","그래서 1.1 × 5 = 5.5예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"0.9 × 4를 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["0.9는 0.1이 9개예요.","이 묶음이 4개이므로 0.1이 9 × 4 = 36개예요.","그래서 0.9 × 4 = 3.6이에요."]},{"stem":"0.4 × 6을 0.1의 개수로 생각하면 곱은 0.1이 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["0.4는 0.1이 4개예요.","이 묶음이 6개이므로 0.1이 4 × 6 = 24개예요.","그래서 0.4 × 6 = 2.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#3','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C3',1,'mc','auto','1.06 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M5-2-u4-X08','M5-2-u4-X03']::text[],true,'{"seq":3,"concept":"M5-2-u4-C3","difficulty":1,"kind":"mc","stem":"1.06 × 4를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨106/100⟩ × 4","correct":true},{"t":"⟨106/1000⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨1/106⟩ × 4","mis":"M5-2-u4-X08"},{"t":"⟨106/100⟩ × ⟨4/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","1.06 = ⟨106/100⟩이에요.","⟨106/100⟩ × 4 = ⟨424/100⟩ = 4.24예요."],"variant_rule":{"alt":[{"stem":"0.52 × 2를 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨52/100⟩ × 2","correct":true},{"t":"⟨52/1000⟩ × 2","mis":"M5-2-u4-X08"},{"t":"⟨1/52⟩ × 2","mis":"M5-2-u4-X08"},{"t":"⟨52/100⟩ × ⟨2/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.52 = ⟨52/100⟩예요.","⟨52/100⟩ × 2 = ⟨104/100⟩ = 1.04예요."]},{"stem":"0.24 × 3을 분수의 곱셈으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"⟨24/100⟩ × 3","correct":true},{"t":"⟨24/1000⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨1/24⟩ × 3","mis":"M5-2-u4-X08"},{"t":"⟨24/100⟩ × ⟨3/10⟩","mis":"M5-2-u4-X03"}],"explanation":["소수 한 자리 수는 분모가 10, 두 자리 수는 분모가 100인 분수예요.","0.24 = ⟨24/100⟩예요.","⟨24/100⟩ × 3 = ⟨72/100⟩ = 0.72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#4','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C4',1,'mc','auto','9 × 0.6은 9보다 큰가요, 작은가요?',ARRAY['M5-2-u4-X06','M5-2-u4-X07']::text[],true,'{"seq":4,"concept":"M5-2-u4-C4","difficulty":1,"kind":"mc","stem":"9 × 0.6은 9보다 큰가요, 작은가요?","options":[{"t":"작다 — 9의 ⟨6/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 9를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.6이 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.6을 1과 견주어요.","0.6은 1보다 작으니 곱은 9보다 작아요.","실제로 9 × 0.6 = 5.4예요."],"variant_rule":{"alt":[{"stem":"4 × 2.2는 4보다 큰가요, 작은가요?","options":[{"t":"크다 — 2.2가 1보다 크다","correct":true},{"t":"작다 — 소수를 곱하면 늘 작아진다","mis":"M5-2-u4-X07"},{"t":"같다 — 4를 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"작다 — 2.2에 소수점이 있다","mis":"M5-2-u4-X07"}],"explanation":["곱하는 수 2.2를 1과 견주어요.","2.2는 1보다 크니 곱은 4보다 커요.","실제로 4 × 2.2 = 8.8이에요."]},{"stem":"6 × 0.9는 6보다 큰가요, 작은가요?","options":[{"t":"작다 — 6의 ⟨9/10⟩이다","correct":true},{"t":"크다 — 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 6을 그대로 둔다","mis":"M5-2-u4-X07"},{"t":"크다 — 0.9가 곱해졌다","mis":"M5-2-u4-X06"}],"explanation":["곱하는 수 0.9를 1과 견주어요.","0.9는 1보다 작으니 곱은 6보다 작아요.","실제로 6 × 0.9 = 5.4예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#5','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C5',1,'sa','auto','3 × 1.24를 자연수의 곱셈을 이용해 계산하려고 해요. 3 × 124는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u4-C5","difficulty":1,"kind":"sa","stem":"3 × 1.24를 자연수의 곱셈을 이용해 계산하려고 해요. 3 × 124는 얼마인가요? 숫자로 쓰세요.","answer":["372"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","3 × 124 = 372예요.","그래서 3 × 1.24 = 3.72예요."],"mis":"M5-2-u4-X13","variant_rule":{"alt":[{"stem":"9 × 0.16을 자연수의 곱셈을 이용해 계산하려고 해요. 9 × 16은 얼마인가요? 숫자로 쓰세요.","answer":["144"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","9 × 16 = 144예요.","그래서 9 × 0.16 = 1.44예요."]},{"stem":"6 × 0.38을 자연수의 곱셈을 이용해 계산하려고 해요. 6 × 38은 얼마인가요? 숫자로 쓰세요.","answer":["228"],"explanation":["소수점을 떼고 자연수끼리 곱해요.","6 × 38 = 228이에요.","그래서 6 × 0.38 = 2.28이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#6','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C6',1,'sa','auto','전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.3 × 0.3을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u4-C6","difficulty":1,"kind":"sa","stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.3 × 0.3을 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["가로 3칸, 세로 3칸을 칠해요.","칠한 칸은 3 × 3 = 9칸이에요.","한 칸이 0.01이므로 0.3 × 0.3 = 0.09예요."],"mis":"M5-2-u4-X09","variant_rule":{"alt":[{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.8 × 0.5를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["가로 8칸, 세로 5칸을 칠해요.","칠한 칸은 8 × 5 = 40칸이에요.","한 칸이 0.01이므로 0.8 × 0.5 = 0.4예요."]},{"stem":"전체 크기가 1인 정사각형 모눈종이를 가로·세로 10칸씩 100칸으로 나누었어요. 여기에 0.6 × 0.9를 나타내면 칠한 칸은 몇 칸인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["가로 6칸, 세로 9칸을 칠해요.","칠한 칸은 6 × 9 = 54칸이에요.","한 칸이 0.01이므로 0.6 × 0.9 = 0.54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#7','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C7',1,'sa','auto','1.23 × 0.4의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u4-C7","difficulty":1,"kind":"sa","stem":"1.23 × 0.4의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["1.23은 소수 두 자리, 0.4는 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 1.23 × 0.4 = 0.492 — 소수 세 자리 수예요."],"mis":"M5-2-u4-X03","variant_rule":{"alt":[{"stem":"0.47 × 0.83의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["0.47은 소수 두 자리, 0.83은 소수 두 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 2 = 4예요.","실제로 0.47 × 0.83 = 0.3901 — 소수 네 자리 수예요."]},{"stem":"0.47 × 0.3의 곱은 소수 몇 자리 수인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["0.47은 소수 두 자리, 0.3은 소수 한 자리 수예요.","곱의 소수점 아래 자릿수는 2 + 1 = 3이에요.","실제로 0.47 × 0.3 = 0.141 — 소수 세 자리 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#8','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C8',1,'mc','auto','2.38 × 1000을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X10','M5-2-u4-X11']::text[],true,'{"seq":8,"concept":"M5-2-u4-C8","difficulty":1,"kind":"mc","stem":"2.38 × 1000을 계산하면 얼마인가요?","options":[{"t":"2380","correct":true},{"t":"0.00238","mis":"M5-2-u4-X10"},{"t":"23800","mis":"M5-2-u4-X11"},{"t":"238","mis":"M5-2-u4-X11"}],"explanation":["1000을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","1000에는 0이 3개 — 오른쪽으로 세 자리예요.","2.38 × 1000 = 2380이에요."],"variant_rule":{"alt":[{"stem":"0.06 × 100을 계산하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"0.0006","mis":"M5-2-u4-X10"},{"t":"60","mis":"M5-2-u4-X11"},{"t":"0.6","mis":"M5-2-u4-X11"}],"explanation":["100을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","100에는 0이 2개 — 오른쪽으로 두 자리예요.","0.06 × 100 = 6이에요."]},{"stem":"4.81 × 100을 계산하면 얼마인가요?","options":[{"t":"481","correct":true},{"t":"0.0481","mis":"M5-2-u4-X10"},{"t":"4810","mis":"M5-2-u4-X11"},{"t":"48.1","mis":"M5-2-u4-X11"}],"explanation":["100을 곱하면 소수점이 오른쪽으로 0의 개수만큼 옮겨져요.","100에는 0이 2개 — 오른쪽으로 두 자리예요.","4.81 × 100 = 481이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_c#9','math',5,2,'u4','','g5_2_math_u4_review_c','unit_review','M5-2-u4-C2',2,'mc','auto','2.6 × 3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":9,"concept":"M5-2-u4-C2","difficulty":2,"kind":"mc","stem":"2.6 × 3을 계산하면 얼마인가요?","options":[{"t":"7.8","correct":true},{"t":"78","mis":"M5-2-u4-X01"},{"t":"0.78","mis":"M5-2-u4-X02"},{"t":"780","mis":"M5-2-u4-X02"}],"explanation":["26 × 3 = 78이에요.","2.6은 26의 ⟨1/10⟩배이므로 곱도 78의 ⟨1/10⟩배예요.","2.6 × 3 = 7.8이에요."],"variant_rule":{"alt":[{"stem":"3.8 × 5를 계산하면 얼마인가요?","options":[{"t":"19","correct":true},{"t":"190","mis":"M5-2-u4-X01"},{"t":"1.9","mis":"M5-2-u4-X02"},{"t":"1900","mis":"M5-2-u4-X02"}],"explanation":["38 × 5 = 190이에요.","3.8은 38의 ⟨1/10⟩배이므로 곱도 190의 ⟨1/10⟩배예요.","3.8 × 5 = 19예요."]},{"stem":"1.2 × 4를 계산하면 얼마인가요?","options":[{"t":"4.8","correct":true},{"t":"48","mis":"M5-2-u4-X01"},{"t":"0.48","mis":"M5-2-u4-X02"},{"t":"480","mis":"M5-2-u4-X02"}],"explanation":["12 × 4 = 48이에요.","1.2는 12의 ⟨1/10⟩배이므로 곱도 48의 ⟨1/10⟩배예요.","1.2 × 4 = 4.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
