INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#13','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C6',2,'mc','auto','5.2 × 1.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":13,"concept":"M5-2-u4-C6","difficulty":2,"kind":"mc","stem":"5.2 × 1.3을 계산하면 얼마인가요?","options":[{"t":"6.76","correct":true},{"t":"67.6","mis":"M5-2-u4-X03"},{"t":"676","mis":"M5-2-u4-X01"},{"t":"0.676","mis":"M5-2-u4-X02"}],"explanation":["52 × 13 = 676이에요.","5.2는 52의 ⟨1/10⟩배, 1.3은 13의 ⟨1/10⟩배예요.","그래서 곱은 676의 ⟨1/100⟩배인 6.76이에요."],"variant_rule":{"alt":[{"stem":"0.6 × 0.9를 계산하면 얼마인가요?","options":[{"t":"0.54","correct":true},{"t":"5.4","mis":"M5-2-u4-X03"},{"t":"54","mis":"M5-2-u4-X01"},{"t":"0.054","mis":"M5-2-u4-X02"}],"explanation":["6 × 9 = 54예요.","0.6은 6의 ⟨1/10⟩배, 0.9는 9의 ⟨1/10⟩배예요.","그래서 곱은 54의 ⟨1/100⟩배인 0.54예요."]},{"stem":"1.9 × 3.6을 계산하면 얼마인가요?","options":[{"t":"6.84","correct":true},{"t":"68.4","mis":"M5-2-u4-X03"},{"t":"684","mis":"M5-2-u4-X01"},{"t":"0.684","mis":"M5-2-u4-X02"}],"explanation":["19 × 36 = 684예요.","1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","그래서 곱은 684의 ⟨1/100⟩배인 6.84예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#14','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C7',2,'mc','auto','0.68 × 2.5를 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":14,"concept":"M5-2-u4-C7","difficulty":2,"kind":"mc","stem":"0.68 × 2.5를 계산하면 얼마인가요?","options":[{"t":"1.7","correct":true},{"t":"17","mis":"M5-2-u4-X03"},{"t":"1700","mis":"M5-2-u4-X01"},{"t":"0.17","mis":"M5-2-u4-X02"}],"explanation":["68 × 25 = 1700이에요.","0.68은 68의 ⟨1/100⟩배, 2.5는 25의 ⟨1/10⟩배예요.","그래서 곱은 1700의 ⟨1/1000⟩배인 1.700이에요 — 끝자리 0은 생략해 1.7로 써요."],"variant_rule":{"alt":[{"stem":"0.47 × 0.3을 계산하면 얼마인가요?","options":[{"t":"0.141","correct":true},{"t":"1.41","mis":"M5-2-u4-X03"},{"t":"141","mis":"M5-2-u4-X01"},{"t":"0.0141","mis":"M5-2-u4-X02"}],"explanation":["47 × 3 = 141이에요.","0.47은 47의 ⟨1/100⟩배, 0.3은 3의 ⟨1/10⟩배예요.","그래서 곱은 141의 ⟨1/1000⟩배인 0.141이에요."]},{"stem":"3.2 × 0.71을 계산하면 얼마인가요?","options":[{"t":"2.272","correct":true},{"t":"22.72","mis":"M5-2-u4-X03"},{"t":"2272","mis":"M5-2-u4-X01"},{"t":"0.2272","mis":"M5-2-u4-X02"}],"explanation":["32 × 71 = 2272예요.","3.2는 32의 ⟨1/10⟩배, 0.71은 71의 ⟨1/100⟩배예요.","그래서 곱은 2272의 ⟨1/1000⟩배인 2.272예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#15','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C8',2,'mc','auto','259 × 13 = 3367이에요. 2.59 × 1.3을 계산하면 얼마인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X01','M5-2-u4-X02']::text[],true,'{"seq":15,"concept":"M5-2-u4-C8","difficulty":2,"kind":"mc","stem":"259 × 13 = 3367이에요. 2.59 × 1.3을 계산하면 얼마인가요?","options":[{"t":"3.367","correct":true},{"t":"33.67","mis":"M5-2-u4-X03"},{"t":"3367","mis":"M5-2-u4-X01"},{"t":"0.3367","mis":"M5-2-u4-X02"}],"explanation":["2.59와 1.3의 소수점 아래 자릿수는 2개와 1개예요.","2 + 1 = 3 — 3367에서 소수점을 왼쪽으로 세 자리 옮겨요.","2.59 × 1.3 = 3.367이에요."],"variant_rule":{"alt":[{"stem":"49 × 32 = 1568이에요. 0.49 × 0.32를 계산하면 얼마인가요?","options":[{"t":"0.1568","correct":true},{"t":"15.68","mis":"M5-2-u4-X03"},{"t":"1568","mis":"M5-2-u4-X01"},{"t":"1.568","mis":"M5-2-u4-X02"}],"explanation":["0.49와 0.32의 소수점 아래 자릿수는 2개와 2개예요.","2 + 2 = 4 — 1568에서 소수점을 왼쪽으로 네 자리 옮겨요.","0.49 × 0.32 = 0.1568이에요."]},{"stem":"138 × 46 = 6348이에요. 13.8 × 4.6을 계산하면 얼마인가요?","options":[{"t":"63.48","correct":true},{"t":"634.8","mis":"M5-2-u4-X03"},{"t":"6348","mis":"M5-2-u4-X01"},{"t":"6.348","mis":"M5-2-u4-X02"}],"explanation":["13.8과 4.6의 소수점 아래 자릿수는 1개와 1개예요.","1 + 1 = 2 — 6348에서 소수점을 왼쪽으로 두 자리 옮겨요.","13.8 × 4.6 = 63.48이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#16','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C9',2,'mc','auto','서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 빨대 안 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X02','M5-2-u4-X05']::text[],true,'{"seq":16,"concept":"M5-2-u4-C9","difficulty":2,"kind":"mc","stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 빨대 안 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"27그루","correct":true},{"t":"270그루","mis":"M5-2-u4-X01"},{"t":"2.7그루","mis":"M5-2-u4-X02"},{"t":"30.9그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 0.9 × 30이에요.","9 × 30 = 270의 ⟨1/10⟩배예요.","0.9 × 30 = 27 — 27그루예요."],"variant_rule":{"alt":[{"stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 플러그 뽑기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"28.5그루","correct":true},{"t":"285그루","mis":"M5-2-u4-X01"},{"t":"2.85그루","mis":"M5-2-u4-X02"},{"t":"16.9그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.9 × 15예요.","19 × 15 = 285의 ⟨1/10⟩배예요.","1.9 × 15 = 28.5 — 28.5그루예요."]},{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 텀블러 쓰기의 반 전체 나무 심는 효과를 계산하면 몇 그루인가요?","options":[{"t":"19.6그루","correct":true},{"t":"196그루","mis":"M5-2-u4-X01"},{"t":"1.96그루","mis":"M5-2-u4-X02"},{"t":"15.4그루","mis":"M5-2-u4-X05"}],"explanation":["반 전체 효과 = 1.4 × 14예요.","14 × 14 = 196의 ⟨1/10⟩배예요.","1.4 × 14 = 19.6 — 19.6그루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#17','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C2',3,'error','auto','여울은 0.8 × 9를 72로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X01','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":17,"concept":"M5-2-u4-C2","difficulty":3,"kind":"error","stem":"여울은 0.8 × 9를 72로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 7.2이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"8 × 9를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["0.8은 0과 1 사이의 수라 곱은 72보다 훨씬 작아야 해요.","8 × 9 = 72는 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 7.2예요."],"variant_rule":{"alt":[{"stem":"수아는 1.2 × 4를 48로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 4.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"12 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.2는 1과 2 사이의 수라 곱은 48보다 훨씬 작아야 해요.","12 × 4 = 48은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 4.8이에요."]},{"stem":"민준은 2.3 × 6을 138로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 찍지 않았다 — 바른 곱은 13.8이다","correct":true,"mis_target":"M5-2-u4-X01"},{"t":"23 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["2.3은 2와 3 사이의 수라 곱은 138보다 훨씬 작아야 해요.","23 × 6 = 138은 맞지만 곱해지는 수가 ⟨1/10⟩배이니 곱도 ⟨1/10⟩배예요.","바른 곱은 13.8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#18','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C3',3,'error','auto','여울은 3.14 × 5를 1.570으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X04']::text[],true,'{"seq":18,"concept":"M5-2-u4-C3","difficulty":3,"kind":"error","stem":"여울은 3.14 × 5를 1.570으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 15.7이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"314 × 5를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["3.14는 3보다 크므로 곱은 3 × 5 = 15보다 커야 해요.","314 × 5 = 1570의 ⟨1/100⟩배이므로 곱은 15.70이에요.","바른 곱은 15.7 — 1.570은 ⟨1/10⟩배 더 작게 쓴 거예요."],"variant_rule":{"alt":[{"stem":"수아는 1.35 × 4를 0.540으로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 5.4이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"135 × 4를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["1.35는 1보다 크므로 곱은 1 × 4 = 4보다 커야 해요.","135 × 4 = 540의 ⟨1/100⟩배이므로 곱은 5.40이에요.","바른 곱은 5.4 — 0.540은 ⟨1/10⟩배 더 작게 쓴 거예요."]},{"stem":"민준은 2.46 × 3을 0.738로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"소수점을 너무 왼쪽에 찍었다 — 바른 곱은 7.38이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"246 × 3을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"끝자리 0을 지우지 않았을 뿐이다","mis":"M5-2-u4-X04"}],"explanation":["2.46은 2보다 크므로 곱은 2 × 3 = 6보다 커야 해요.","246 × 3 = 738의 ⟨1/100⟩배이므로 곱은 7.38이에요.","바른 곱은 7.38 — 0.738은 ⟨1/10⟩배 더 작게 쓴 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#19','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C5',3,'error','auto','여울은 7 × 0.26을 18.2로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u4-X02','M5-2-u4-X13','M5-2-u4-X06']::text[],true,'{"seq":19,"concept":"M5-2-u4-C5","difficulty":3,"kind":"error","stem":"여울은 7 × 0.26을 18.2로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 1.82이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"7 × 26을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.26은 26의 ⟨1/100⟩배이므로 곱도 7 × 26 = 182의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 7보다 작아야 하는데 18.2는 7보다 커요.","바른 곱은 1.82예요."],"variant_rule":{"alt":[{"stem":"수아는 6 × 0.38을 22.8로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 2.28이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"6 × 38을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.38은 38의 ⟨1/100⟩배이므로 곱도 6 × 38 = 228의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 6보다 작아야 하는데 22.8은 6보다 커요.","바른 곱은 2.28이에요."]},{"stem":"민준은 9 × 0.45를 40.5로 계산했어요. 잘못된 곳을 바르게 말한 것은 어느 것인가요?","options":[{"t":"곱의 소수점을 한 자리 덜 옮겼다 — 바른 곱은 4.05이다","correct":true,"mis_target":"M5-2-u4-X02"},{"t":"9 × 45를 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"곱하면 커지니 맞게 계산했다","mis":"M5-2-u4-X06"}],"explanation":["0.45는 45의 ⟨1/100⟩배이므로 곱도 9 × 45 = 405의 ⟨1/100⟩배예요.","곱하는 수가 1보다 작으니 곱은 9보다 작아야 하는데 40.5는 9보다 커요.","바른 곱은 4.05예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#20','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C6',3,'error','auto','여울은 4.5 × 2.8을 126으로 계산했어요. 바르게 고친 설명은 어느 것인가요?',ARRAY['M5-2-u4-X03','M5-2-u4-X13','M5-2-u4-X18']::text[],true,'{"seq":20,"concept":"M5-2-u4-C6","difficulty":3,"kind":"error","stem":"여울은 4.5 × 2.8을 126으로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 1260의 ⟨1/100⟩배인 12.6이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"45 × 28을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["4.5는 45의 ⟨1/10⟩배, 2.8은 28의 ⟨1/10⟩배예요.","곱은 45 × 28 = 1260의 ⟨1/100⟩배여야 해요.","바른 곱은 12.6이에요."],"variant_rule":{"alt":[{"stem":"수아는 1.9 × 3.6을 68.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 684의 ⟨1/100⟩배인 6.84이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"19 × 36을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["1.9는 19의 ⟨1/10⟩배, 3.6은 36의 ⟨1/10⟩배예요.","곱은 19 × 36 = 684의 ⟨1/100⟩배여야 해요.","바른 곱은 6.84예요."]},{"stem":"민준은 75.9 × 0.6을 455.4로 계산했어요. 바르게 고친 설명은 어느 것인가요?","options":[{"t":"한 수의 소수점 아래 자릿수만 세었다 — 곱은 4554의 ⟨1/100⟩배인 45.54이다","correct":true,"mis_target":"M5-2-u4-X03"},{"t":"759 × 6을 잘못 계산했다","mis":"M5-2-u4-X13"},{"t":"잘못된 곳이 없다","mis":"M5-2-u4-X18"}],"explanation":["75.9는 759의 ⟨1/10⟩배, 0.6은 6의 ⟨1/10⟩배예요.","곱은 759 × 6 = 4554의 ⟨1/100⟩배여야 해요.","바른 곱은 45.54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#21','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C7',3,'mc','auto','계산하지 않고 어림하여 알맞은 말을 고르세요. 3.08 × 4.2는 12보다 …',ARRAY['M5-2-u4-X07','M5-2-u4-X14']::text[],true,'{"seq":21,"concept":"M5-2-u4-C7","difficulty":3,"kind":"mc","stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 3.08 × 4.2는 12보다 …","options":[{"t":"크다 — 3.08은 3보다, 4.2는 4보다 크다","correct":true},{"t":"작다 — 4.2가 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 3 × 4 = 12이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["3 × 4 = 12를 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 12보다 커요.","실제로 3.08 × 4.2 = 12.936이에요."],"variant_rule":{"alt":[{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 3.2 × 0.71은 2.1보다 …","options":[{"t":"크다 — 3.2는 3보다, 0.71은 0.7보다 크다","correct":true},{"t":"작다 — 0.71이 1보다 작다","mis":"M5-2-u4-X07"},{"t":"같다 — 어림하면 3 × 0.7 = 2.1이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["3 × 0.7 = 2.1을 기준으로 삼아요.","두 수가 모두 기준보다 조금씩 크니 곱도 2.1보다 커요.","실제로 3.2 × 0.71 = 2.272예요."]},{"stem":"계산하지 않고 어림하여 알맞은 말을 고르세요. 0.89 × 0.6은 0.54보다 …","options":[{"t":"작다 — 0.89는 0.9보다 작다","correct":true},{"t":"크다 — 두 수를 곱하면 늘 커진다","mis":"M5-2-u4-X06"},{"t":"같다 — 어림하면 0.9 × 0.6 = 0.54이다","mis":"M5-2-u4-X14"},{"t":"견줄 수 없다 — 정확히 계산해야만 안다","mis":"M5-2-u4-X14"}],"explanation":["0.9 × 0.6 = 0.54를 기준으로 삼아요.","0.89가 0.9보다 작으니 곱도 0.54보다 작아요.","실제로 0.89 × 0.6 = 0.534예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#22','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C9',3,'mc','auto','서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?',ARRAY['M5-2-u4-X15','M5-2-u4-X18']::text[],true,'{"seq":22,"concept":"M5-2-u4-C9","difficulty":3,"kind":"mc","stem":"서연이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 음식물 줄이기 1.6그루·20명, 이면지 쓰기 0.7그루·24명, 물 아껴 쓰기 2.4그루·11명, 빨대 안 쓰기 0.9그루·30명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"음식물 줄이기","correct":true},{"t":"물 아껴 쓰기","mis":"M5-2-u4-X15"},{"t":"빨대 안 쓰기","mis":"M5-2-u4-X15"},{"t":"이면지 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.6 × 20 = 32, 0.7 × 24 = 16.8, 2.4 × 11 = 26.4, 0.9 × 30 = 27이에요.","가장 높게 나타난 방법은 음식물 줄이기예요."],"variant_rule":{"alt":[{"stem":"민주네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"플러그 뽑기","correct":true},{"t":"텔레비전 1시간 줄이기","mis":"M5-2-u4-X15"},{"t":"분리배출하기","mis":"M5-2-u4-X15"},{"t":"장바구니 쓰기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이에요.","가장 높게 나타난 방법은 플러그 뽑기예요."]},{"stem":"도윤이네 반 탄소 중립 생활 표(실천 방법 · 한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 계단 이용하기 0.8그루·18명, 텀블러 쓰기 1.4그루·14명, 대중교통 이용하기 2.6그루·9명, 샤워 시간 줄이기 0.6그루·25명. 반 전체의 나무 심는 효과가 가장 높게 나타난 실천 방법은 무엇인가요?","options":[{"t":"대중교통 이용하기","correct":true},{"t":"샤워 시간 줄이기","mis":"M5-2-u4-X15"},{"t":"텀블러 쓰기","mis":"M5-2-u4-X18"},{"t":"계단 이용하기","mis":"M5-2-u4-X18"}],"explanation":["방법마다 한 사람의 효과 × 학생 수를 구해요.","0.8 × 18 = 14.4, 1.4 × 14 = 19.6, 2.6 × 9 = 23.4, 0.6 × 25 = 15예요.","가장 높게 나타난 방법은 대중교통 이용하기예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#23','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C4',4,'mc','auto','높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.7배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?',ARRAY['M5-2-u4-X17','M5-2-u4-X02','M5-2-u4-X18']::text[],true,'{"seq":23,"concept":"M5-2-u4-C4","difficulty":4,"kind":"mc","stem":"높이가 30 cm인 마트료시카를 열 때마다 안에 든 인형의 높이가 바로 바깥 인형의 0.7배가 돼요. 두 번째로 꺼낸 인형의 높이는 몇 cm인가요?","options":[{"t":"14.7 cm","correct":true},{"t":"28.6 cm","mis":"M5-2-u4-X17"},{"t":"147 cm","mis":"M5-2-u4-X02"},{"t":"21 cm","mis":"M5-2-u4-X18"}],"explanation":["첫 번째 인형은 30 × 0.7 = 21(cm)예요.","두 번째 인형은 21 × 0.7 = 14.7(cm)예요.","그래서 14.7 cm예요."],"variant_rule":{"alt":[{"stem":"다을은 「49 × 32 = 1568이니까 0.49 × 0.32 = 0.1568」, 봄은 「138 × 46 = 6348이니까 1.38 × 4.6 = 63.48」이라고 말했어요. 잘못 말한 친구와 바른 곱을 고르세요.","options":[{"t":"봄 — 바른 곱은 6.348","correct":true},{"t":"다을 — 바른 곱은 1.568","mis":"M5-2-u4-X18"},{"t":"봄 — 바른 곱은 634.8","mis":"M5-2-u4-X03"},{"t":"둘 다 바르게 말했다","mis":"M5-2-u4-X18"}],"explanation":["0.49 × 0.32의 소수점 아래 자릿수는 2 + 2 = 4예요.","1.38 × 4.6의 소수점 아래 자릿수는 2 + 1 = 3이에요.","봄의 말이 틀렸어요 — 바른 곱은 6.348이에요."]},{"stem":"1시간에 260 km를 가는 고속 열차가 같은 빠르기로 1시간 30분 동안 가는 거리는 몇 km인가요?","options":[{"t":"390 km","correct":true},{"t":"338 km","mis":"M5-2-u4-X16"},{"t":"260 km","mis":"M5-2-u4-X18"},{"t":"290 km","mis":"M5-2-u4-X16"}],"explanation":["30분은 1시간의 ⟨30/60⟩이라 0.5시간이에요.","1시간 30분 = 1.5시간이에요.","260 × 1.5 = 390 — 390 km예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#24','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C1',4,'essay','teacher','어린이 안전 체험관에서 기념품으로 1.5 kg인 소화기를 3개 받았어요. 소화기의 무게를 덧셈식과 곱셈식으로 각각 나타내고 모두 몇 kg인지 구해 보세요. 그리고 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u4-C1","difficulty":4,"kind":"essay","stem":"어린이 안전 체험관에서 기념품으로 1.5 kg인 소화기를 3개 받았어요. 소화기의 무게를 덧셈식과 곱셈식으로 각각 나타내고 모두 몇 kg인지 구해 보세요. 그리고 4 kg까지 담을 수 있는 종이봉투 하나에 모두 담을 수 있는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 덧셈식은 1.5 + 1.5 + 1.5이고 곱셈식은 1.5 × 3이다. 1.5 + 1.5 + 1.5 = 4.5이므로 모두 4.5 kg이다. 4.5 > 4이므로 4 kg까지 담을 수 있는 종이봉투 하나에는 모두 담을 수 없다.","scoring_points":["덧셈식과 곱셈식 1.5 × 3을 모두 썼는가","4.5 kg을 구했는가","4.5 kg이 4 kg보다 무거워 담을 수 없다고 판단했는가"]},"explanation":["1.5 + 1.5 + 1.5 = 1.5 × 3이에요.","1.5 × 3 = 4.5(kg)이에요.","4.5 > 4 — 한 봉투에 다 담을 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u4_review_d#25','math',5,2,'u4','','g5_2_math_u4_review_d','unit_review','M5-2-u4-C9',4,'essay','teacher','민주네 반 탄소 중립 생활 표(한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법을 어림셈으로 먼저 찾고 계산으로 확인한 뒤, 한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 1등이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"M5-2-u4-C9","difficulty":4,"kind":"essay","stem":"민주네 반 탄소 중립 생활 표(한 사람의 연간 나무 심는 효과 · 실천한 학생 수): 플러그 뽑기 1.9그루·15명, 분리배출하기 0.4그루·22명, 장바구니 쓰기 1.2그루·16명, 텔레비전 1시간 줄이기 13.3그루·2명. 반 전체 효과가 가장 높은 방법을 어림셈으로 먼저 찾고 계산으로 확인한 뒤, 한 사람의 효과가 가장 큰 텔레비전 1시간 줄이기가 1등이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 어림셈 — 2 × 15 = 30, 0.5 × 22 = 11, 1 × 16 = 16, 13 × 2 = 26이므로 플러그 뽑기가 가장 높을 것이다. 계산 — 1.9 × 15 = 28.5, 0.4 × 22 = 8.8, 1.2 × 16 = 19.2, 13.3 × 2 = 26.6이므로 가장 높은 방법은 플러그 뽑기(28.5그루)이다. 텔레비전 1시간 줄이기는 한 사람의 효과가 크지만 실천한 학생이 2명뿐이라 모두 합한 효과가 26.6그루로 플러그 뽑기보다 작다.","scoring_points":["어림셈으로 네 방법을 견주었는가","계산으로 플러그 뽑기 28.5그루가 가장 높음을 확인했는가","학생 수가 2명뿐이라 곱이 작다고 설명했는가"]},"explanation":["어림셈: 2 × 15 = 30이 가장 커요.","계산: 1.9 × 15 = 28.5 > 13.3 × 2 = 26.6이에요.","효과 × 학생 수로 견줘야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
